INSERT INTO `ai_prep_question_bank` (`category`, `subject`, `concept`, `difficulty_level`, `scope`, `time_limit_seconds`, `question_text`, `ground_truth`, `is_active`)
VALUES
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'How do hash tables work in Python dictionaries, and why are they efficient for key-value storage?', '{"key_points": [{"id": "KP1", "description": "Explain Python dictionary internal architecture combining a dense entries array and a sparse hash indices table (Python 3.6+ compact dict).", "required": true, "acceptable_evidence": ["Technical keywords: PyDictObject, compact dict, sparse hash table, dense entries array, dk_indices, dk_entries, memory footprint reduction.", "Explains that modern CPython dictionaries separate the sparse index table (`dk_indices`) from the dense entry array (`dk_entries`), storing `[hash, key_ref, value_ref]` consecutively to preserve insertion order and reduce memory overhead by 30-40%.", "Contrasts this with legacy CPython where each sparse bucket held empty padding slots for hash, key, and value."]}, {"id": "KP2", "description": "Detail hash calculation and open addressing collision resolution using pseudo-random perturbation probing.", "required": true, "acceptable_evidence": ["Technical keywords: hash(), perturb, open addressing, quadratic/pseudo-random probing, collision resolution, dummy tombstone.", "Explains that when two keys collide (`hash(k1) % size == hash(k2) % size`), CPython resolves collisions via open addressing with pseudo-random perturbation (`idx = ((5 * idx) + 1 + perturb) & mask; perturb >>= 5`) rather than simple linear probing.", "Details how deleted keys are marked with dummy/tombstone markers to ensure search chains remain intact."]}, {"id": "KP3", "description": "Analyze amortized O(1) time complexity, hash resize triggers, and key immutability constraints (`__hash__` and `__eq__`).", "required": true, "acceptable_evidence": ["Technical keywords: amortized O(1), load factor 2/3, resizing, rehashing, immutable keys, __hash__, __eq__.", "Explains that lookups, insertions, and deletions are amortized $O(1)$ under healthy hash distributions, but can degrade to $O(N)$ under malicious or poorly distributed hash collisions (HashDoS).", "Notes that resizing occurs when the dictionary reaches a 2/3 load factor, triggering table reallocation and index recomputation, and requires keys to implement compatible `__hash__` and `__eq__` methods."]}], "critical_failures": ["Claims Python dictionaries resolve hash collisions using separate chaining with linked lists like Java HashMap, failing to recognize CPython open addressing with perturbation probing.", "Asserts that mutable objects like lists or unhashable dicts can be used as dictionary keys.", "Fails to explain why Python 3.6+ dictionaries preserve insertion order through dense entries and sparse indices separation."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 90, 'How do you assemble context for agents, including retrieving dependencies, constraints, and repository-specific rules?', '{"key_points": [{"id": "KP1", "description": "Allocate strict token budgets across system instructions, repository rules, conversational memory, and retrieved domain passages.", "required": true, "acceptable_evidence": ["Technical keywords: token budget, tiktoken, cl100k_base, context window allocation, system instructions, dynamic packing.", "Explains that context assembly requires deterministic token budgeting across bounded buckets: e.g., 1,500 tokens for system rules, 2,000 for conversation history, 3,500 for retrieved chunks, leaving sufficient headroom for generation within model limits (e.g., 8k or 16k tokens).", "Describes calculating token counts dynamically using tokenizers (`tiktoken` for OpenAI, Hugging Face fast tokenizers for open-source LLMs) before passing strings to the model."]}, {"id": "KP2", "description": "Retrieve and inject relevant repository constraints, coding conventions, and architectural dependencies into agent execution prompts.", "required": true, "acceptable_evidence": ["Technical keywords: repository rules, AST dependencies, .cursorrules, project constraints, hierarchical prompt injection.", "Explains how coding and diagnostic agents pull repository constraints (e.g., framework versions, coding conventions, API schemas) from indexed configuration files or abstract syntax trees (AST).", "Details injecting constraints into structured XML or Markdown tags (e.g., `<system_constraints>`, `<retrieved_evidence>`) to maintain prompt clarity and prevent cross-attention drift."]}, {"id": "KP3", "description": "Implement truncation, semantic summarization, and priority-based shedding when assembled context exceeds prompt limits.", "required": true, "acceptable_evidence": ["Technical keywords: priority queue, token shedding, sliding window, semantic summarization, lost-in-the-middle mitigation.", "Explains that when context overflows token limits, lower-priority context (older chat turns, lowest-ranked retrieval passages) is dropped or compressed via background LLM summarization.", "Details placing the most critical operational instructions and highest-ranked evidence chunks at the beginning and end of the context to counter the ''lost-in-the-middle'' phenomenon."]}], "critical_failures": ["Concatenates retrieved documents and agent history naively without token budgeting or bounds checking, causing context overflow and runtime API errors.", "Fails to structure assembled context with clear delimiters or schema tags, allowing retrieved content to override system policies (indirect prompt injection).", "Discards critical constraints or system instructions rather than pruning auxiliary conversation history when token limits are reached."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'SPECIFIC', 90, 'How do you create rolling averages and lag features for time-series data, and what is their significance in modeling?', '{"key_points": [{"id": "KP1", "description": "Engineer rolling window statistics and lag features to capture temporal velocity, acceleration, and cyclical trends.", "required": true, "acceptable_evidence": ["Technical keywords: rolling averages, lag features, moving window, standard deviation, transaction velocity, Pandas shift(), rolling().", "Explains creating lag features ($t-1, t-2, t-7$) and rolling aggregate metrics (e.g., 1-hour, 24-hour, 7-day rolling mean, count, and z-score) to represent customer spending velocity or transaction bursts.", "Provides concrete examples from fraud detection: transaction counts in the past 10 minutes vs. historical 30-day baseline to detect account takeover bursts."]}, {"id": "KP2", "description": "Enforce strict temporal point-in-time correctness to prevent lookahead data leakage during feature generation.", "required": true, "acceptable_evidence": ["Technical keywords: data leakage, point-in-time join, asof join, chronological train/test split, label maturity window.", "Explains that rolling metrics must compute strictly over observations strictly preceding the event timestamp ($t_i < T_{event}$), forbidding future transactions in window aggregations.", "Details using chronological time-based splits (e.g., train on Q1-Q3, validate on Q4) rather than random `train_test_split`, and enforcing label maturity windows to handle delayed chargeback confirmations."]}, {"id": "KP3", "description": "Bridge offline feature calculation with low-latency production feature serving using dual-store feature architectures.", "required": true, "acceptable_evidence": ["Technical keywords: Feast, Hopsworks, Redis online store, S3/Parquet offline store, training-serving skew, sliding window aggregation.", "Explains how batch ETL computes historical rolling features stored in S3/Delta Lake for offline model training, while Redis or streaming Flink/Kafka pipelines maintain live rolling aggregates for low-latency (<50ms) inference.", "Describes maintaining consistent feature definitions across training and production serving to eliminate training-serving skew."]}], "critical_failures": ["Applies random `train_test_split` on temporal transaction data or includes future rows in rolling window calculations, causing catastrophic data leakage.", "Computes rolling statistics globally across the entire dataset before splitting into train and test folds.", "Ignores training-serving skew by implementing different feature calculation algorithms in Python training scripts versus production inference APIs."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How do you decide what data should be indexed in a RAG system, and how do you prevent noise in retrieval?', '{"key_points": [{"id": "KP1", "description": "Establish strict document admission criteria and taxonomy filters to eliminate redundant, outdated, and low-signal documentation.", "required": true, "acceptable_evidence": ["Technical keywords: admission criteria, content filtering, boilerplates, document taxonomy, signal-to-noise ratio, active lifecycle status.", "Explains defining ingestion boundaries based on business relevance: filtering out outdated software manuals, duplicate FAQ revisions, boilerplates, navigational HTML footers, and draft documents.", "References EV call center knowledge ingestion where only official vehicle service manuals, active technical service bulletins (TSBs), and verified diagnostic procedures are admitted."]}, {"id": "KP2", "description": "Apply cryptographic and semantic deduplication to eliminate identical and near-duplicate document passages.", "required": true, "acceptable_evidence": ["Technical keywords: SHA256 content hashing, MinHash LSH, SimHash, semantic deduplication, cosine similarity threshold.", "Details two-stage deduplication: exact hashing (SHA-256) on normalized text to drop byte-for-byte duplicates, followed by MinHash/SimHash or vector embedding similarity (>0.95 cosine) to identify near-identical policy revisions.", "Explains how indexing redundant chunks pollutes vector dense spaces, clusters top-k results on duplicates, and wastes context tokens."]}, {"id": "KP3", "description": "Filter noisy boilerplate and structural artifacts during document parsing using layout-aware heuristics.", "required": true, "acceptable_evidence": ["Technical keywords: layout-aware parsing, Docling, header/footer stripping, regex scrubbing, page numbers, legal disclaimers.", "Explains removing repetitive headers, page numbers, copyright footers, and multi-page legal disclaimers that match generic keyword queries and dilute semantic retrieval scores.", "Mentions stripping OCR noise and malformed markup from scanned technician notes before chunking."]}], "critical_failures": ["Ingests raw document repositories indiscriminately without deduplication or filtering, flooding the vector database with duplicate chunks and outdated drafts.", "Indexes repeating headers, page numbers, and copyright footers into chunk content, causing them to dominate dense embedding space.", "Fails to establish version control or admission gates, causing obsolete vehicle or Medicaid policies to be retrieved as active ground truth."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 90, 'How do you decide when to use RAG versus fine-tuning? Can you give me a real-world example?', '{"key_points": [{"id": "KP1", "description": "Contrast RAG and Fine-Tuning across dynamic knowledge access, training cost, knowledge staleness, and hallucinations.", "required": true, "acceptable_evidence": ["Technical keywords: dynamic knowledge vs. parametric knowledge, knowledge cutoff, continuous retraining cost, hallucinations, domain grounding.", "Explains that RAG is designed for external, rapidly updating, or private knowledge (e.g., EV firmware release notes, Medicaid policy updates) without retraining, providing real-time data freshness and verifiable source citations.", "Contrasts with Fine-Tuning, which updates internal model weights to teach tone, dialect, structured output formats (e.g., custom JSON/SQL), or specialized tasks, but is static, expensive to retrain, and prone to hallucinations."]}, {"id": "KP2", "description": "Analyze auditability, source citation, and governance requirements between retrieved evidence and parametric memory.", "required": true, "acceptable_evidence": ["Technical keywords: verifiable citations, audit trail, regulatory compliance, black-box weights, HIPAA/Medicaid traceability.", "Explains that highly regulated enterprise domains (healthcare, lending, automotive safety) require exact page, section, and effective date citations that fine-tuned weights cannot reliably generate without hallucination.", "Details how RAG provides an explicit audit trail linking every factual claim to an immutable source chunk ID."]}, {"id": "KP3", "description": "Provide a concrete real-world decision framework combining RAG for factual retrieval and PEFT/LoRA for formatting and domain syntax.", "required": true, "acceptable_evidence": ["Technical keywords: LoRA, QLoRA, domain adaptation, hybrid RAG-PEFT, EV diagnostic codes, structured JSON synthesis.", "Presents a real-world decision matrix: fine-tuning a small open model (Llama-3-8B with LoRA) to master structured diagnostic diagnostic formats or Medical terminology, while deploying RAG to retrieve the live vehicle manual or state policy chunks.", "Explains the economic and operational trade-offs: RAG incurs inference vector search latency (~50-100ms) but zero training overhead, whereas fine-tuning requires ongoing GPU compute and pipeline curation."]}], "critical_failures": ["Recommends fine-tuning as the primary solution for keeping an LLM updated with rapidly changing enterprise documentation or policy guidelines.", "Claims fine-tuned models can generate verifiable document page citations and audit trails directly from internal model weights.", "Asserts that RAG changes model parameters or teaches the LLM new reasoning capabilities rather than augmenting prompt context."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How do you define and measure groundedness in your system, and how do you ensure responses are properly aligned with retrieved context and source documents?', '{"key_points": [{"id": "KP1", "description": "Define groundedness and faithfulness as the mathematical entailment of generated claims strictly within retrieved context chunks.", "required": true, "acceptable_evidence": ["Technical keywords: groundedness, faithfulness, natural language inference (NLI), entailment, premise vs hypothesis, hallucination.", "Defines groundedness: an answer is grounded if and only if every factual statement in the generation can be inferred directly from the retrieved context passages without relying on ungrounded pre-trained parametric knowledge.", "Differentiates groundedness (did the LLM invent facts not in context?) from answer correctness (did the system retrieve the right real-world policy?)."]}, {"id": "KP2", "description": "Deconstruct generated responses into atomic factual statements and verify entailment using automated NLI or LLM judges.", "required": true, "acceptable_evidence": ["Technical keywords: atomic statements, claim decomposition, DeBERTa-v3, LLM-as-a-judge, RAGAS Faithfulness, DeepEval.", "Details the claim verification pipeline: (1) decompose LLM response into atomic propositions, (2) run cross-checking against retrieved chunks using a cross-encoder NLI model (e.g., DeBERTa-v3) or deterministic LLM-as-a-Judge (`temperature=0`), (3) score faithfulness as $|\\\\text{entailed claims}| / |\\\\text{total claims}|$.", "Provides examples from the EV Call Center where non-entailed claims trigger automated redaction."]}, {"id": "KP3", "description": "Enforce grounding at generation time via negative constraints, temperature tuning, and citation anchors.", "required": true, "acceptable_evidence": ["Technical keywords: temperature=0, prompt constraints, citation tagging [doc_id], negative constraint, unknown fallback.", "Explains prompt engineering techniques to enforce grounding: setting `temperature=0.0`, injecting strict negative constraints (''If the answer cannot be found in the provided context, state that the information is unavailable''), and requiring mandatory inline citation markers `[doc_id:pX]`.", "Explains how requiring citation anchors forces the model to attend to specific context tokens."]}], "critical_failures": ["Conflates groundedness with answer fluency or lexical similarity metrics like BLEU/ROUGE.", "Evaluates groundedness without decomposing responses into atomic claims or verifying logical entailment against retrieved context.", "Allows the model to draw on outside parametric knowledge without citing retrieved context, leading to unverifiable hallucinations in production."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How do you define success criteria for deploying a RAG system in a production environment?', '{"key_points": [{"id": "KP1", "description": "Establish dual-track evaluation frameworks aligning technical system metrics with core business KPIs.", "required": true, "acceptable_evidence": ["Technical keywords: technical metrics vs business KPIs, AHT (Average Handle Time), FCR (First Call Resolution), CSAT, deflection rate.", "Explains establishing dual-track goals: technical metrics (Faithfulness $\\\\ge 0.90$, Context Recall $\\\\ge 0.85$, p95 latency $< 2.5s$) mapped directly to business impact (reducing Average Handle Time from 10m to 6m, increasing First Call Resolution from 70% to 85%, and driving CSAT above 4.5/5).", "Emphasizes that high technical accuracy is meaningless if it does not improve call center agent productivity or resolution speed."]}, {"id": "KP2", "description": "Define production Operational Service Level Agreements (SLAs) across latency, availability, and error budgets.", "required": true, "acceptable_evidence": ["Technical keywords: SLAs, SLIs, p95/p99 latency, time-to-first-token (TTFT), error budget, 99.9% uptime, graceful degradation.", "Details operational SLAs: p95 latency under 2.5 seconds, streaming Time-to-First-Token (TTFT) under 800ms, service availability of 99.9%, and fallback circuit breakers triggering if retrieval fails.", "Explains defining error budgets for LLM hallucinations and guardrail interventions before releasing updates to production."]}, {"id": "KP3", "description": "Implement continuous calibration loops (CC/CD) with automated rollback thresholds and stakeholder sign-off gates.", "required": true, "acceptable_evidence": ["Technical keywords: Continuous Calibration (CC/CD), golden dataset gates, automated rollback, stakeholder acceptance criteria, SME review.", "Explains defining clear release gates: new models or prompt changes must pass a 200-question Golden Dataset test with zero critical safety regressions before deployment.", "Details operational review cadence with customer support leads and domain SMEs to validate real-world usability and audit trail compliance."]}], "critical_failures": ["Defines production success solely through model accuracy or perplexity without defining business KPIs (AHT, FCR, CSAT) or operational SLAs.", "Omits latency and uptime SLAs, allowing multi-second delays that disrupt real-time customer support interactions.", "Lacks automated evaluation gates or rollback criteria to catch accuracy regressions prior to production cutover."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'HARD', 'SPECIFIC', 120, 'How do you deploy and configure PGVector in AWS environments such as RDS and integrate it with ML pipelines?', '{"key_points": [{"id": "KP1", "description": "Provision Amazon RDS PostgreSQL with the pgvector extension and configure vector column data types.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon RDS PostgreSQL, pgvector extension, CREATE EXTENSION vector, vector(768), halfvec, shared_preload_libraries.", "Details enabling `vector` extension in AWS RDS parameter groups, defining vector columns (`vector(768)` or `vector(1536)`), and storing dense embeddings alongside relational business entities (metadata, documents, timestamps).", "Explains using PostgreSQL 16+ with memory tuning (`shared_buffers`, `maintenance_work_mem`) to accommodate in-memory vector indexing."]}, {"id": "KP2", "description": "Build and tune Hierarchical Navigable Small World (HNSW) indexes using `m` and `ef_construction` parameters.", "required": true, "acceptable_evidence": ["Technical keywords: HNSW index, ivfflat, vector_cosine_ops, m=16, ef_construction=64, hnsw.ef_search, recall vs latency.", "Explains creating HNSW index (`CREATE INDEX ON chunks USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64)`) to achieve millisecond-level ANN search compared to slow IVFFlat lists.", "Details tuning query-time `hnsw.ef_search` (e.g., 40 to 100) to balance retrieval recall against query latency."]}, {"id": "KP3", "description": "Architect high-throughput retrieval using read replicas, connection pooling (PgBouncer), and ACID transactional pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: RDS Read Replicas, PgBouncer, connection pooling, IAM database authentication, AWS Secrets Manager.", "Details scaling vector queries across Aurora/RDS Read Replicas to isolate compute-heavy vector distance calculations from OLTP writes.", "Explains using PgBouncer to manage high-concurrency connection spikes from FastAPI microservices and securing credentials via IAM / AWS Secrets Manager."]}, {"id": "KP4", "description": "Evaluate architectural scale boundaries where dedicated vector databases (Milvus) supersede PGVector.", "required": false, "acceptable_evidence": ["Technical keywords: RAM saturation, index build times, scale boundaries, Milvus vs PGVector, billions of vectors.", "Analyzes trade-offs: PGVector is ideal for unified relational metadata + vector search up to several million vectors, but faces severe RAM saturation, long maintenance index build locks, and lack of horizontal index sharding beyond 10-20M vectors compared to distributed Milvus."]}], "critical_failures": ["Queries millions of vectors in PostgreSQL using sequential scans (`ORDER BY embedding <=> query_vector`) without creating an HNSW or IVFFlat index.", "Sets `maintenance_work_mem` too low in PostgreSQL, causing HNSW index creation to fail or thrash disk swap space.", "Overlooks RDS read replicas and connection pooling, allowing heavy vector searches to exhaust connection limits and crash OLTP database operations."]}', 1),
('HIRING_MANAGER', 'DevOps and Cloud', 'CI/CD & GitOps', 'MEDIUM', 'SPECIFIC', 90, 'How do you ensure consistency between staging and production environments in a RAG system?', '{"key_points": [{"id": "KP1", "description": "Enforce identical container images, dependency lockfiles, and model artifact digests across Staging and Production environments.", "required": true, "acceptable_evidence": ["Technical keywords: build once promote many, immutable Docker digest, poetry.lock, MLflow model registry URI, Git SHA.", "Explains the principle of ''Build Once, Promote Many'': container images built in CI are pushed to Amazon ECR tagged with immutable Git commit SHAs and promoted from Staging to Production without rebuilding.", "Details locking model weights, embedding model versions (`all-MiniLM-L6-v2`), and Python dependencies (`poetry.lock`) to eliminate runtime environment drift."]}, {"id": "KP2", "description": "Synchronize vector store collections, indexing algorithms, and knowledge corpus versions between environments.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus collection schema, HNSW index parity, corpus synchronization, data masking, staging replica.", "Explains maintaining identical vector database configurations: matching index types (HNSW), distance metrics (Cosine/IP), and schema definitions across Staging and Production Milvus clusters.", "Details syncing a sanitized or production-representative document corpus into Staging to validate retrieval recall under realistic vector distributions."]}, {"id": "KP3", "description": "Validate system performance and contract stability using automated smoke tests and shadow traffic replay prior to cutover.", "required": true, "acceptable_evidence": ["Technical keywords: automated smoke tests, shadow traffic, traffic mirroring, Golden Dataset regression gate, canary deployment.", "Explains executing automated end-to-end regression suites against Staging, testing health endpoints, vector retrieval top-k, and Golden Dataset metrics before triggering deployment.", "Mentions shadowing live production traffic to Staging to measure latency, GPU memory utilization, and guardrail performance under real load."]}], "critical_failures": ["Rebuilds Docker images or recompiles dependencies separately in Production using mutable tags (`latest`), introducing dependency skew.", "Tests Staging against different vector index types or embedding dimensions than Production, rendering staging validation useless.", "Promotes code directly to Production without automated validation against a staged Golden Dataset."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How do you use metadata, collections, and versioning to manage and retrieve documents effectively in a vector database?', '{"key_points": [{"id": "KP1", "description": "Design collection partitioning and partition key strategies to isolate document revisions and tenant domains.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus partition keys, collection partitioning, namespace isolation, tenant_id, doc_version, partition pruning.", "Explains structuring vector collections using physical or logical partition keys (e.g., `tenant_id`, `policy_year`, `vehicle_model_year`) to enable partition pruning during queries, dramatically reducing search search space and latency.", "Contrasts single monolithic collections with partitioned collections in Milvus/Pinecone."]}, {"id": "KP2", "description": "Implement document versioning and tombstoning to ensure only active policy revisions are retrieved at runtime.", "required": true, "acceptable_evidence": ["Technical keywords: document versioning, effective_date, expiration_date, is_active, soft delete, tombstone, metadata filtering.", "Details tagging every chunk with version metadata: `version: ''2.1''`, `effective_date: ''2026-01-01''`, `status: ''ACTIVE''`. Runtime queries filter strictly on `status == ''ACTIVE'' AND effective_date <= CURRENT_DATE`.", "Explains how superseding a document marks old records as deprecated without triggering immediate, costly vector index rebuilds."]}, {"id": "KP3", "description": "Manage document lifecycle transitions (ingestion, update, rollback, and purging) via atomic batch operations.", "required": true, "acceptable_evidence": ["Technical keywords: atomic swap, blue-green collection alias, batch deletion, index compaction, rollback runbook.", "Explains executing zero-downtime knowledge base updates using collection aliasing: indexing new document revisions into an alternate collection (`collection_v2`) and atomically switching the production alias (`active_collection_alias`) once indexing and calibration verify 100% integrity.", "Details automated rollback runbooks that revert the alias to the previous collection in seconds if accuracy drops."]}], "critical_failures": ["Overwrites vector records in-place without version tracking, preventing auditability and making rollbacks impossible when erroneous documents are ingested.", "Queries unpartitioned vector stores with linear scans over inactive and historical document revisions.", "Performs document updates by deleting and re-indexing the entire database during live production traffic, causing downtime and index thrashing."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How does BM25 work conceptually, and how is it different from TF-IDF?', '{"key_points": [{"id": "KP1", "description": "Deconstruct the BM25 mathematical formulation and explain non-linear term frequency saturation via parameter $k_1$.", "required": true, "acceptable_evidence": ["Technical keywords: BM25, term frequency saturation, k1 parameter, asymptotic limit, TF-IDF linear scaling.", "Explains the mathematical difference in TF treatment: while classic TF-IDF scales term frequency linearly or logarithmically without upper bounds, BM25 uses the non-linear saturation curve $\\\\frac{TF \\\\cdot (k_1 + 1)}{TF + k_1 \\\\cdot (1 - b + b \\\\cdot \\\\frac{|D|}{avgdl})}$.", "Explains that $k_1$ (typically 1.2 to 2.0) controls saturation speed: repeating a keyword 50 times yields diminishing returns over appearing 3 times, preventing keyword stuffing."]}, {"id": "KP2", "description": "Analyze document length normalization mechanics controlled by parameter $b$ against average document length.", "required": true, "acceptable_evidence": ["Technical keywords: document length normalization, b parameter, avgdl, document length penalty, short vs long documents.", "Explains that parameter $b$ (typically 0.75) penalizes long documents that contain many words by chance: if $|D| > avgdl$, the denominator increases, scaling down the term score.", "Details how setting $b=1.0$ applies full document length normalization, whereas $b=0.0$ disables length penalties entirely."]}, {"id": "KP3", "description": "Explain the role of Inverse Document Frequency (IDF) and why BM25 excels at exact technical code lookups.", "required": true, "acceptable_evidence": ["Technical keywords: Inverse Document Frequency (IDF), rare terms, exact token matching, diagnostic trouble codes (DTC), CPT codes.", "Explains how IDF heavily weights rare domain tokens (e.g., error code ''P0A80'', Medicaid CPT ''99213'', part number ''EV-BAT-400V'') while attenuating common stop words.", "Explains why lexical BM25 is essential in hybrid search: dense embeddings often blur exact alphanumeric strings, whereas BM25 matches exact codes with 100% precision."]}], "critical_failures": ["Claims BM25 is a vector dense embedding model, failing to understand it is a probabilistic sparse lexical matching algorithm.", "Asserts that TF-IDF and BM25 handle term frequency identically without term saturation or document length normalization.", "Fails to explain the role of hyper-parameters $k_1$ (term frequency saturation) and $b$ (length normalization)."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How does Maximum Marginal Relevance (MMR) re-ranking improve retrieval quality in a RAG pipeline?', '{"key_points": [{"id": "KP1", "description": "Explain the Maximum Marginal Relevance (MMR) mathematical objective function and greedy selection algorithm.", "required": true, "acceptable_evidence": ["Technical keywords: Maximum Marginal Relevance (MMR), lambda parameter, greedy selection, Sim1(d, q), Sim2(d, di), diversity vs relevance.", "Defines the mathematical formula: $\\\\text{MMR} = \\\\arg\\\\max_{d_i \\\\in R \\\\setminus S} [\\\\lambda \\\\cdot \\\\text{Sim}(d_i, q) - (1 - \\\\lambda) \\\\cdot \\\\max_{d_j \\\\in S} \\\\text{Sim}(d_i, d_j)]$, where $R$ is candidate pool and $S$ is already selected set.", "Explains the iterative selection: at each step, select the document that maximizes relevance to the query while penalizing similarity to already chosen documents in $S$."]}, {"id": "KP2", "description": "Analyze tuning parameter $\\\\lambda$ to balance relevance exploitation against redundancy reduction.", "required": true, "acceptable_evidence": ["Technical keywords: lambda tuning, lambda=1 (pure relevance), lambda=0 (maximal diversity), redundancy penalty, top-k context window.", "Explains the spectrum: $\\\\lambda = 1.0$ reduces to standard cosine similarity top-k (often returning 5 slightly different chunks of the same manual section), while lower $\\\\lambda$ (e.g., 0.5 to 0.7) forces the selection of chunks covering distinct aspects of a multi-part question.", "Discusses preventing context window waste caused by near-identical overlapping chunks."]}, {"id": "KP3", "description": "Contrast MMR with Cross-Encoder reranking in computational latency and pipeline sequencing.", "required": true, "acceptable_evidence": ["Technical keywords: embedding-based similarity, cross-encoder reranking, computational efficiency, two-tier reranking, latency budget.", "Explains that MMR operates purely on pre-computed embedding vectors via fast dot products ($O(K \\\\cdot N)$), making it computationally cheap (<5ms) compared to deep Transformer Cross-Encoders (~50-100ms).", "Details using MMR either as an initial diversity filter on vector candidates (e.g., filtering top 50 to 15 diverse chunks) before Cross-Encoder reranking, or as a final diversification step."]}], "critical_failures": ["Confuses MMR with cross-encoder reranking or Reciprocal Rank Fusion (RRF), failing to explain its diversity penalty term.", "Claims $\\\\lambda = 1.0$ maximizes diversity, reversing the mathematical relationship where $\\\\lambda=1.0$ is pure relevance.", "Fails to identify how MMR prevents redundant, near-duplicate chunks from occupying limited LLM context tokens."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How does hybrid retrieval (semantic + keyword search) work in your system, and why did you include a cross-encoder re-ranker?', '{"key_points": [{"id": "KP1", "description": "Architect a two-stage hybrid retrieval pipeline combining dense vector search and sparse BM25 lexical search.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid retrieval, dense vector search, sparse lexical search, BM25, Milvus HNSW, Elasticsearch / OpenSearch, candidate generation.", "Explains executing parallel candidate retrieval: generating top-50 candidates via dense semantic vector search (capturing contextual synonyms and intent) and top-50 candidates via BM25 lexical search (capturing exact error codes, part numbers, and policy names).", "Details why single-method retrieval fails: dense retrieval misses exact alphanumeric strings, while keyword search misses semantic synonyms."]}, {"id": "KP2", "description": "Merge heterogeneous candidate rankings using Reciprocal Rank Fusion (RRF) with constant parameter $k=60$.", "required": true, "acceptable_evidence": ["Technical keywords: Reciprocal Rank Fusion (RRF), RRF score, rank-based normalization, k=60 constant, score incomparability.", "Explains why score fusion cannot use raw scores (cosine similarity $[0, 1]$ vs. unbounded BM25 $[0, \\\\infty)$) and requires rank-based fusion: $RRF\\\\_Score(d) = \\\\sum_{m \\\\in M} \\\\frac{1}{k + r_m(d)}$, where $k=60$.", "Details how RRF elevates documents that score highly across both retrievers while safeguarding against outlier scale skews."]}, {"id": "KP3", "description": "Refine top fused candidates using a deep Transformer Cross-Encoder reranker (`bge-reranker-base`).", "required": true, "acceptable_evidence": ["Technical keywords: Cross-Encoder reranker, bge-reranker-base, full cross-attention, top-k selection, final context packing.", "Explains passing the top 20-30 RRF fused candidates to a Cross-Encoder that concatenates query and passage (`[CLS] Query [SEP] Chunk [SEP]`) to compute full bi-directional cross-attention relevance scores.", "Details selecting the top 3-5 reranked chunks for final prompt context injection, demonstrating significant gains in Recall@5 and NDCG@10."]}, {"id": "KP4", "description": "Quantify retrieval performance improvements of hybrid + reranking over pure semantic search.", "required": false, "acceptable_evidence": ["Technical keywords: Recall@5, MRR@10, latency trade-off, ablation analysis, EV Call Center benchmark.", "Provides benchmark data from the Study Guides: pure semantic retrieval achieved 72% Recall@5; hybrid BM25 + dense boosted it to 84%; adding the Cross-Encoder lifted Recall@5 to 94% with an acceptable ~40ms reranking latency overhead."]}], "critical_failures": ["Attempts to combine dense cosine scores and BM25 scores by adding raw scores directly without normalization or Reciprocal Rank Fusion (RRF).", "Omits the Cross-Encoder reranking stage or treats Cross-Encoders as identical to Bi-Encoder vector embedding models.", "Fails to explain the complementary strengths of dense semantic retrieval (concept matching) and sparse BM25 retrieval (exact keyword/code matching)."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'How does indexing work in practice for queries such as selecting records by ID, and why does it speed up data retrieval?', '{"key_points": [{"id": "KP1", "description": "Explain B-Tree / B+Tree data structure mechanics, balanced node fanout, and logarithmic search depth.", "required": true, "acceptable_evidence": ["Technical keywords: B+Tree, node fanout, page size (8KB/16KB), logarithmic depth O(log N), disk I/O reduction, root-to-leaf traversal.", "Explains that relational databases (PostgreSQL, MySQL InnoDB) organize primary and secondary indexes as B+Trees, where internal nodes store keys and page pointers with high fanout (100-1000 keys per page) and leaf nodes store row pointers or clustered data.", "Details how high fanout ensures 3-4 disk page reads locate any record among billions of rows."]}, {"id": "KP2", "description": "Differentiate clustered indexes (index-organized tables) from non-clustered secondary indexes.", "required": true, "acceptable_evidence": ["Technical keywords: clustered index, secondary index, primary key lookup, heap table, tuple ID (ctid), pointer indirection.", "Explains that in clustered architectures (e.g., MySQL InnoDB), leaf nodes contain the actual table rows ordered by primary key, making PK lookups zero-indirection point reads.", "Contrasts with secondary indexes or heap-based engines (e.g., PostgreSQL), where leaf nodes store tuple pointers (`ctid`) requiring a secondary table heap page fetch unless satisfied by a covering index index-only scan."]}, {"id": "KP3", "description": "Analyze storage layout, cache-friendly sequential page scans, and B+Tree range query leaf linkages.", "required": true, "acceptable_evidence": ["Technical keywords: doubly-linked leaf nodes, sequential I/O, range scan, buffer pool, disk page alignment.", "Explains that B+Tree leaf pages are connected via doubly-linked pointers, enabling efficient sequential range scans (`WHERE id BETWEEN 100 AND 200`) without re-traversing upper tree nodes.", "Notes how matching node sizes to hardware filesystem pages maximizes buffer cache hit ratios and minimizes random disk head movement."]}], "critical_failures": ["Claims relational indexes use hash tables for primary key range queries, ignoring B+Tree ordering requirements.", "Fails to distinguish clustered indexes (data stored in leaf pages) from secondary indexes (requiring pointer lookup to table heap).", "Asserts that indexing improves write performance, failing to recognize the write amplification and index rebalancing overhead on `INSERT`/`UPDATE`."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How does multi-query retrieval work, and how did it improve answer quality in your system?', '{"key_points": [{"id": "KP1", "description": "Implement LLM-driven query rewriting to generate diverse perspective variations of an initial user query.", "required": true, "acceptable_evidence": ["Technical keywords: multi-query generation, query expansion, query rewriting, diverse perspectives, semantic variations.", "Explains prompting a lightweight LLM to generate 3-5 alternative phrasings of user questions: capturing synonyms, formal technical terminology, and colloquial expressions (e.g., rewriting ''car won''t charge'' to ''EV fast-charging failure'', ''CCS protocol handshake error'', and ''battery thermal lockout'').", "Details how this overcomes the sensitivity of vector similarity to specific phrasing."]}, {"id": "KP2", "description": "Execute parallel multi-vector retrieval and aggregate resulting candidate sets using deduplication and rank fusion.", "required": true, "acceptable_evidence": ["Technical keywords: parallel vector retrieval, async execution, candidate pooling, Reciprocal Rank Fusion, deduplication by chunk_id.", "Details executing parallel embedding and vector searches across all query variants asynchronously (`asyncio.gather`), combining retrieved chunks into a unified candidate pool.", "Explains deduplicating chunks by `chunk_id` and recalculating aggregate relevance scores using Reciprocal Rank Fusion (RRF) or max-score pooling."]}, {"id": "KP3", "description": "Decompose complex multi-hop or compound questions into discrete sequential sub-queries.", "required": true, "acceptable_evidence": ["Technical keywords: sub-query decomposition, multi-hop reasoning, compound queries, dependency graph, step-back prompting.", "Explains decomposing complex comparative queries (e.g., ''Compare Medicaid dental benefits in California vs. Texas'') into isolated sub-queries (`sub-query 1: California Medicaid adult dental coverage`, `sub-query 2: Texas Medicaid adult dental coverage`).", "Details executing targeted retrieval per sub-query and synthesizing individual context chunks into a coherent final prompt."]}], "critical_failures": ["Executes multi-query generation synchronously in serial loops, multiplying user-facing retrieval latency by 3x-5x.", "Fails to deduplicate retrieved chunks across query variations, passing duplicate content that clutters the LLM context window.", "Uses multi-query expansion indiscriminately on simple factual lookups where it introduces noise and dilutes retrieval precision."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How does reranking improve retrieval results, and how does a cross-encoder model work in this context?', '{"key_points": [{"id": "KP1", "description": "Contrast Cross-Encoder joint self-attention architecture with Bi-Encoder dual-tower embedding retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: Cross-Encoder vs. Bi-Encoder, dual-tower, full cross-attention, [CLS] Query [SEP] Document, token interaction.", "Explains architectural difference: Bi-Encoders encode query and document independently into fixed vectors ($O(Q) + O(D)$) allowing pre-indexed vector search, but miss fine-grained token-to-token interactions.", "Contrasts with Cross-Encoders, which feed query and candidate chunk together into a Transformer (`[CLS] Query [SEP] Chunk [SEP]`), allowing every query token to attend directly to every chunk token across all self-attention layers."]}, {"id": "KP2", "description": "Explain Cross-Encoder classification head scoring and soft relevance calibration.", "required": true, "acceptable_evidence": ["Technical keywords: bge-reranker-base, ms-marco, logit score, sigmoid activation, relevance score calibration.", "Explains that Cross-Encoders take the final `[CLS]` token representation and pass it through a linear classification layer to output a raw logit, mapped via Sigmoid to a normalized relevance probability score $[0, 1]$.", "Details how these calibrated scores accurately reflect relevance regardless of vector distance geometry."]}, {"id": "KP3", "description": "Analyze two-stage retrieval trade-offs: Bi-Encoder high recall candidate generation followed by Cross-Encoder precision reranking.", "required": true, "acceptable_evidence": ["Technical keywords: two-stage retrieval, candidate pool (top-30/50), inference latency budget (~30-50ms), ONNX Runtime / TensorRT.", "Explains that because Cross-Encoders are computationally intensive ($O(K \\\\cdot (L_Q + L_D)^2)$), they cannot search millions of chunks directly; instead, fast Bi-Encoders/BM25 retrieve top 30-50 candidates, and the Cross-Encoder filters down to top 3-5.", "Details optimizing Cross-Encoder serving latency via batching, FP16 quantization, and ONNX Runtime to keep overhead under 40ms."]}], "critical_failures": ["Claims Cross-Encoders produce static vector embeddings that can be stored in Milvus or Pinecone for fast similarity search.", "Asserts that Bi-Encoders provide richer token-level interaction than Cross-Encoders.", "Attempts to run Cross-Encoder scoring across the entire million-document corpus on live user queries rather than as a second-stage reranker on top candidates."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How does semantic chunking with overlap work, and why is it important for improving retrieval quality?', '{"key_points": [{"id": "KP1", "description": "Explain chunk size and sliding token overlap mechanics to preserve semantic context across chunk boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: chunk size, sliding window overlap, 10-20% overlap, boundary truncation, sentence splitting.", "Explains that arbitrary text splitting cuts across sentences, clauses, or logical steps, isolating pronouns from referents or splitting error condition tables.", "Details applying sliding token overlap (e.g., 500-token chunks with 50-100 token overlap) so border sentences appear in consecutive chunks, ensuring embedding vectors retain complete contextual meaning."]}, {"id": "KP2", "description": "Implement semantic boundary chunking using sentence embedding cosine similarity distance thresholds.", "required": true, "acceptable_evidence": ["Technical keywords: semantic chunking, cosine distance threshold, percentile threshold, breakpoint detection, spacy sentence tokenizer.", "Explains the semantic chunking algorithm: (1) split document into sentences via spaCy/NLTK, (2) compute embeddings for consecutive sentence windows, (3) calculate cosine distance between adjacent sentences, (4) identify topic shifts at distance spikes (e.g., 95th percentile distance), and (5) split chunks at these semantic breakpoints.", "Contrasts semantic chunking with naive fixed-character splitting."]}, {"id": "KP3", "description": "Analyze retrieval trade-offs between small chunks (high embedding precision) and large chunks (rich context window).", "required": true, "acceptable_evidence": ["Technical keywords: chunk size trade-off, small chunks (200-300 tokens), large chunks (1000+ tokens), embedding dilution, parent-child chunking.", "Analyzes trade-offs: small chunks capture sharp semantic vectors and improve retrieval precision but lack broader context; large chunks provide complete answers but suffer from embedding dilution where critical facts are averaged out.", "Presents hierarchical parent-child chunking as an optimal solution: search on small 250-token child chunks and return 1000-token parent sections to the LLM."]}], "critical_failures": ["Splits documents into fixed character counts without overlap or sentence boundary awareness, severing words and sentences in half.", "Claims sliding window overlap creates severe duplicate hallucinations without explaining how deduplication and reranking resolve boundary artifacts.", "Fails to explain the embedding dilution problem in overly large text chunks."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How does the claims agent retrieve and process data from databases or external APIs?', '{"key_points": [{"id": "KP1", "description": "Design the end-to-end tool calling and data integration architecture for an autonomous claims processing agent.", "required": true, "acceptable_evidence": ["Technical keywords: claims agent, tool calling, Pydantic schemas, external REST APIs, relational database queries, LangGraph / LangChain.", "Explains the multi-step claims validation workflow: the agent parses claim requests, extracts member IDs and procedure codes, invokes external eligibility APIs, queries relational databases for claim history, and compares results against policy rules.", "Details defining strict Pydantic schemas for API tool definitions to ensure deterministic structured arguments."]}, {"id": "KP2", "description": "Enforce authentication, rate limiting, and secure credential storage for agent external tool calls.", "required": true, "acceptable_evidence": ["Technical keywords: OAuth2 client credentials, mTLS, AWS Secrets Manager, connection pooling, rate limit backoff.", "Explains securing outbound API integrations: retrieving tokens via OAuth2 client credentials stored in AWS Secrets Manager, enforcing mTLS for partner payer endpoints, and implementing exponential backoff for API rate limits.", "Details read-only database replicas and parameterized SQL queries to prevent SQL injection during dynamic agent database lookups."]}, {"id": "KP3", "description": "Implement multi-step decision synthesis, discrepancy validation, and Human-in-the-Loop (HITL) escalation triggers.", "required": true, "acceptable_evidence": ["Technical keywords: cross-system validation, discrepancy check, HITL escalation, claim approval thresholds, audit trail.", "Explains reconciling data across systems: verifying that billing codes match eligibility criteria and that claim amounts do not exceed pre-authorized limits.", "Details automated escalation to human claims adjusters when discrepancies exceed confidence thresholds or claim amounts cross high-risk financial boundaries ($5,000+)."]}], "critical_failures": ["Allows the claims agent to execute arbitrary, unparameterized SQL queries generated by the LLM directly against production databases.", "Omits error handling and retry logic for external API timeouts, causing the entire agent workflow to crash.", "Grants the agent full autonomous approval authority over high-value claims without Human-in-the-Loop (HITL) safety thresholds."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How is human-in-the-loop interaction structured between service agents and the RAG system?', '{"key_points": [{"id": "KP1", "description": "Establish quantitative confidence thresholds and domain safety triggers for automated human escalation.", "required": true, "acceptable_evidence": ["Technical keywords: Human-in-the-Loop (HITL), escalation triggers, confidence threshold, high-voltage battery safety, Medicaid prior authorization.", "Explains establishing deterministic escalation gates: routing cases to human specialists when retrieval confidence drops below 0.65, when conflicting policies exist, or when safety-critical actions are detected (e.g., EV high-voltage battery disconnects, Medicaid surgical denials).", "Contrasts low-risk autonomous queries (e.g., standard billing FAQs) with high-stakes actions requiring explicit human approval."]}, {"id": "KP2", "description": "Design an interactive agent-assist interface surfacing draft responses, confidence scores, and source citations.", "required": true, "acceptable_evidence": ["Technical keywords: agent copilot, draft response, source citation highlighting, accept/edit/reject, Streamlit / React UI.", "Details the customer support copilot interface: displaying the AI-generated draft response alongside confidence scores, clickable source document citations (page, paragraph), and quick action controls (Accept, Edit, Reject).", "Explains how source highlighting empowers call center agents to verify technical accuracy in under 10 seconds before communicating with customers."]}, {"id": "KP3", "description": "Close the active learning flywheel by harvesting human corrections into versioned Golden Datasets.", "required": true, "acceptable_evidence": ["Technical keywords: active learning, correction harvesting, Golden Dataset expansion, SME feedback loop, regression test suite.", "Explains logging every human edit and rejection into an observability queue (Langfuse / DynamoDB), categorizing failure types (retrieval miss, hallucination, tone error).", "Details periodic SME curation where validated human corrections are converted into new test cases in the CI Golden Dataset to prevent recurring failures."]}], "critical_failures": ["Deploys autonomous agents on high-liability safety or financial actions without human escalation or approval gates.", "Treats human rejection feedback as a dead end without logging corrections into an active learning dataset for system improvement.", "Forces human operators to read raw unformatted JSON logs rather than providing an explainable UI with source citation highlights."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How much hands-on experience do you have with LLMs and RAG pipelines, and what specific components have you worked on?', '{"key_points": [{"id": "KP1", "description": "Articulate deep end-to-end engineering ownership across document ingestion, chunking, embedding, vector databases, and LLM serving.", "required": true, "acceptable_evidence": ["Technical keywords: end-to-end RAG architecture, hands-on engineering, Docling, Sentence-Transformers, Milvus, FastAPI, Langfuse.", "Details direct hands-on implementation across every tier: building ingestion pipelines with Docling and Presidio, evaluating embedding models (`all-MiniLM-L6-v2`, `BGE`), provisioning and tuning Milvus on AWS EKS, and building FastAPI streaming inference services.", "References specific production projects from the Study Guides (EV Call Center Assistant, Medicaid Knowledge Platform, TalentScreen) demonstrating practical depth."]}, {"id": "KP2", "description": "Highlight complex technical problem-solving and architectural transitions executed to solve real production failures.", "required": true, "acceptable_evidence": ["Technical keywords: POC to production migration, ChromaDB to Milvus, hybrid search RRF, cross-encoder reranking, latency optimization.", "Discusses concrete technical challenges overcome: migrating from lightweight ChromaDB to distributed Milvus when scaling past 500k chunks, resolving domain code retrieval misses by introducing hybrid BM25 + dense search with RRF, and eliminating hallucinations via Cross-Encoder reranking.", "Quantifies outcomes: reducing Average Handle Time by 35% and slashing hallucination rates from 18% to under 2%."]}, {"id": "KP3", "description": "Demonstrate production discipline across CI/CD evaluation, observability tracing, and cost/latency governance.", "required": true, "acceptable_evidence": ["Technical keywords: Continuous Calibration (CC/CD), DeepEval, RAGAS, OpenTelemetry, Langfuse, token budgeting, GPU cost control.", "Explains integrating automated Golden Dataset evaluation gates into GitHub Actions CI, deploying async Langfuse tracing to monitor live production token costs, and optimizing prompt budgets to maintain sub-2 second response latency.", "Highlights collaboration with DevOps, Product, and domain experts to deliver compliant, scalable AI infrastructure."]}], "critical_failures": ["Describes RAG abstractly at a tutorial level (e.g., ''I called LangChain RetrievalQA'') without demonstrating low-level engineering experience.", "Cannot explain the rationale behind architectural migrations (such as moving from ChromaDB to Milvus or adding hybrid reranking).", "Ignores operational reality: does not mention evaluation metrics, latency constraints, cost management, or production monitoring."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'In what scenarios is BM25 more effective than vector search, and why is combining them beneficial?', '{"key_points": [{"id": "KP1", "description": "Identify domain scenarios where sparse lexical search (BM25) significantly outperforms dense vector similarity.", "required": true, "acceptable_evidence": ["Technical keywords: exact keyword matching, out-of-vocabulary (OOV), diagnostic trouble codes (DTC), alphanumeric identifiers, CPT/ICD codes.", "Explains that BM25 excels when queries contain rare, exact alphanumeric strings: vehicle error codes (e.g., ''DTC-U0100'', ''B2000-49''), medical procedure codes (''CPT-99214''), part numbers, and policy subsection references.", "Explains why dense embeddings fail on these queries: subword tokenizers split arbitrary alphanumeric strings into generic sub-tokens whose dense vectors collapse into unrelated embedding neighborhoods."]}, {"id": "KP2", "description": "Identify domain scenarios where dense vector semantic retrieval significantly outperforms lexical keyword matching.", "required": true, "acceptable_evidence": ["Technical keywords: semantic similarity, synonymy, polysemy, vocabulary mismatch, conceptual intent, natural language queries.", "Explains that dense vector search excels on conceptual, multi-word natural language questions where user phrasing differs from document vocabulary (e.g., user asks ''battery won''t charge overnight'', manual describes ''high-voltage DC fast-charging thermal lockout and onboard charger fault'').", "Details how dense embedding geometry maps semantic synonyms and paraphrases to adjacent points in vector space."]}, {"id": "KP3", "description": "Formulate the dual-retrieval synergy that makes hybrid search the production standard for enterprise knowledge systems.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid retrieval synergy, dual-channel search, high recall, vocabulary mismatch resolution, Reciprocal Rank Fusion.", "Explains that combining both methods via Reciprocal Rank Fusion ensures that queries containing both conceptual intent and exact technical identifiers (e.g., ''how to clear DTC-P0A80 hybrid battery failure in 2024 model'') achieve maximum recall.", "Demonstrates that neither pure dense nor pure sparse retrieval alone can satisfy enterprise support accuracy requirements."]}], "critical_failures": ["Claims dense vector embeddings always outperform BM25 across all query types, failing to recognize embedding failure on exact alphanumeric codes.", "Asserts that BM25 can capture semantic synonyms and conceptual paraphrasing without query expansion.", "Fails to articulate why hybrid search combining both paradigms is essential in enterprise production systems."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'In what scenarios is PGVector an appropriate choice for vector storage, and when would you prefer more scalable solutions like Milvus?', '{"key_points": [{"id": "KP1", "description": "Evaluate PGVector suitability for consolidated architectures with low-to-medium vector scale and unified relational data.", "required": true, "acceptable_evidence": ["Technical keywords: PGVector, PostgreSQL, ACID transactions, relational joins, metadata filtering, unified infrastructure, < 5M vectors.", "Explains that PGVector is ideal for small-to-medium workloads (< 5 million vectors) where teams already operate PostgreSQL: it enables ACID transactions, zero data movement, and complex SQL joins between relational business entities and vector embeddings in a single query.", "Emphasizes low operational overhead: avoids maintaining and monitoring a separate distributed database cluster."]}, {"id": "KP2", "description": "Analyze technical and architectural limitations of PGVector under high throughput and large-scale data volume.", "required": true, "acceptable_evidence": ["Technical keywords: shared resource contention, RAM saturation, HNSW index build time, vacuum locks, horizontal scaling limits.", "Identifies critical PGVector bottlenecks: (1) memory contention where large HNSW indexes exhaust PostgreSQL buffer pools, hurting OLTP query performance, (2) single-node write scaling limits, and (3) prolonged maintenance locks during index rebuilding.", "Explains that PostgreSQL was designed for relational row/column layouts, not disaggregated high-dimensional vector math at scale."]}, {"id": "KP3", "description": "Detail distributed architecture advantages of dedicated vector databases (Milvus) for hyper-scale enterprise deployments.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus, disaggregated architecture, query nodes, data nodes, index nodes, object storage (S3), billions of vectors.", "Explains that Milvus decouples compute and storage into specialized microservice roles (Query Nodes, Data Nodes, Index Nodes, Root Coordinator) backed by MinIO/S3 and Etcd.", "Highlights dedicated advantages: horizontal pod autoscaling for QPS spikes, distributed GPU-accelerated HNSW/Knowhere indexing, and zero-impact ingestion scaling past hundreds of millions of vectors."]}], "critical_failures": ["Recommends PGVector for hundreds of millions of vectors without addressing single-node RAM saturation and PostgreSQL buffer pool contention.", "Claims Milvus should always be used for simple 10,000-row applications, ignoring the massive operational overhead of deploying distributed Milvus clusters.", "Fails to recognize the transactional and relational join benefits of keeping vectors inside PostgreSQL alongside business metadata."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'Purely retrieval stage efficiency, how can it be improved by any storage based mechanism also? What additional improvements you can do at the storage level or at the type of storage itself, in addition to the storing your vectors?', '{"key_points": [{"id": "KP1", "description": "Implement vector quantization techniques (Scalar Quantization SQ8 and Product Quantization PQ) to reduce memory footprint by 4x-8x.", "required": true, "acceptable_evidence": ["Technical keywords: Scalar Quantization (SQ8), Product Quantization (PQ), FP32 to INT8 compression, memory footprint reduction, cache locality.", "Explains compressing 32-bit floating-point embedding vectors (FP32) to 8-bit integers (INT8/SQ8), reducing RAM consumption from 3KB to 768 bytes per 768-dim vector with negligible (<1%) recall degradation.", "Details how reduced memory footprints allow vector indices to fit entirely within high-speed CPU L3 cache and RAM, drastically reducing cache misses during graph traversal."]}, {"id": "KP2", "description": "Utilize memory-mapped files (mmap) and tiered NVMe storage to decouple memory constraints from index scale.", "required": true, "acceptable_evidence": ["Technical keywords: mmap, memory-mapped I/O, NVMe SSD tiering, Milvus Knowhere, warm vs cold index data, page cache.", "Explains configuring vector databases (e.g., Milvus / FAISS) with `mmap` to map on-disk vector indices directly into virtual memory space, letting the OS manage page paging dynamically without loading the entire multi-gigabyte index into physical RAM.", "Details multi-tier storage architectures: pinning top HNSW graph upper layers in RAM while paging raw vector payloads and bottom-layer leaf graphs from high-IOPS NVMe SSDs."]}, {"id": "KP3", "description": "Optimize inverted list storage layouts and column-oriented metadata storage for fast hybrid filtering.", "required": true, "acceptable_evidence": ["Technical keywords: columnar storage, Parquet, Arrow, inverted lists, SIMD vector instructions, bitset pre-filtering.", "Explains storing document metadata in columnar formats (Apache Arrow/Parquet) to execute ultra-fast vectorized predicate filtering (e.g., `tenant_id == 5 AND status == ''ACTIVE''`) using SIMD CPU instructions before performing vector distance calculations.", "Describes generating a bitset mask to prune the candidate search graph instantly."]}], "critical_failures": ["Assumes scaling vector retrieval efficiency requires endlessly adding expensive RAM without considering vector quantization (SQ8/PQ) or memory-mapping (mmap).", "Claims scalar quantization destroys semantic retrieval accuracy, failing to recognize modern SQ8 achieves >98% recall parity.", "Ignores hardware-level I/O optimizations like NVMe page caching and SIMD instruction acceleration for vector distance math."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'Tell me about Faiss and why it is used.', '{"key_points": [{"id": "KP1", "description": "Explain FAISS core architecture as an optimized C++ library for high-performance in-memory vector similarity search.", "required": true, "acceptable_evidence": ["Technical keywords: FAISS (Facebook AI Similarity Search), C++ core, Python bindings, in-memory library, GPU acceleration, SIMD AVX2/AVX-512.", "Explains that FAISS is an algorithm library (not a standalone distributed database server) engineered for ultra-fast dense vector similarity computation via native C++ routines, SIMD parallelism, and CUDA GPU kernels.", "Contrasts FAISS as an embedded search engine component with full-fledged managed vector databases like Milvus or Pinecone."]}, {"id": "KP2", "description": "Compare foundational FAISS index structures: exact IndexFlatIP/L2 vs. inverted file IndexIVFFlat.", "required": true, "acceptable_evidence": ["Technical keywords: IndexFlatL2, IndexFlatIP, IndexIVFFlat, nlist Voronoi cells, nprobe parameter, brute-force exact search.", "Contrasts exact brute-force search (`IndexFlatIP`/`IndexFlatL2`, which computes distances against all vectors with 100% recall at $O(N)$ cost) with approximate search (`IndexIVFFlat`, which clusters vectors into `nlist` Voronoi cells during training).", "Details query-time execution in IVF: hashing the query to the nearest centroids and searching only the vectors in `nprobe` inverted lists, trading small recall drops for 10x-100x latency speedups."]}, {"id": "KP3", "description": "Analyze operational trade-offs of FAISS: raw computational speed vs. lack of native persistence, replication, and metadata filtering.", "required": true, "acceptable_evidence": ["Technical keywords: operational trade-offs, lack of ACID persistence, metadata handling, horizontal clustering, standalone microservices.", "Explains that while FAISS delivers industry-leading raw search speeds (especially on NVIDIA GPUs), it lacks built-in durability, network APIs, distributed sharding, dynamic CRUD deletion without re-indexing, and native metadata filtering.", "Explains why production systems embed FAISS within custom microservices or adopt distributed platforms (Milvus) that wrap FAISS/Knowhere kernels."]}], "critical_failures": ["Describes FAISS as a distributed database cluster with built-in user management, replication, and ACID transactions rather than an in-memory C++ library.", "Claims `IndexIVFFlat` requires no training phase, confusing it with unindexed brute-force `IndexFlatL2`.", "Fails to explain the role of `nlist` (clustering centroids) and `nprobe` (number of centroids searched at query time)."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What alternative approaches can be used if embeddings are not available, and what are their limitations?', '{"key_points": [{"id": "KP1", "description": "Architect a multi-tier fallback hierarchy to maintain system availability during embedding model outages or high latency.", "required": true, "acceptable_evidence": ["Technical keywords: graceful degradation, fallback hierarchy, circuit breaker, service outage, High Availability (HA), BM25 fallback.", "Explains establishing an automated fallback ladder: if embedding inference endpoints (OpenAI / Hugging Face TEI / Bedrock) timeout or throw 5xx errors, a circuit breaker trips and automatically degrades retrieval from dense semantic search to standalone sparse BM25 / Elasticsearch keyword search.", "Emphasizes that degraded exact keyword answers are vastly superior to total system outage for live call center agents."]}, {"id": "KP2", "description": "Utilize query-response semantic caches and pre-computed static embedding tables during upstream degradation.", "required": true, "acceptable_evidence": ["Technical keywords: exact query cache, Redis cache hit, FAQ hash table, static embeddings, offline pre-computation.", "Details checking a low-latency Redis cache for exact or normalized query matches before calling external embedding APIs.", "Explains maintaining pre-computed embedding caches for frequent domain queries (e.g., top 1,000 EV charging and warranty questions) so common inquiries bypass runtime embedding generation entirely."]}, {"id": "KP3", "description": "Inject transparent system notices and adjust downstream generation prompt instructions under degraded retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: UI system notice, degraded retrieval banner, conservative generation, hallucination prevention, SME routing.", "Explains alerting downstream components: appending a degraded context flag to prompt instructions (`context_mode=''lexical_only''`), instructing the LLM to adhere strictly to keyword matches and admit lack of data rather than hallucinating answers from weak semantic context.", "Surfaces a subtle UI status indicator informing human operators that search results are operating in keyword-only mode."]}], "critical_failures": ["Allows the entire RAG pipeline and user-facing application to crash when embedding API endpoints experience rate limits or downtime.", "Attempts to generate responses without context or falls back to ungrounded LLM parametric knowledge during retrieval outages.", "Lacks circuit breakers, allowing hanging embedding requests to exhaust application connection pools and induce cascading failures."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'What are the key differences between a RAG-based system and an agentic AI system, and when would you transition between them?', '{"key_points": [{"id": "KP1", "description": "Contrast linear, single-shot RAG retrieval chains with iterative, goal-directed agentic control loops (ReAct / LangGraph).", "required": true, "acceptable_evidence": ["Technical keywords: static RAG vs agentic AI, DAG chains, ReAct loop (Thought-Action-Observation), LangGraph state graphs, dynamic replanning.", "Explains that standard RAG executes a rigid, feed-forward sequence: `Query -> Retrieve -> Augment -> Generate`, which fails on queries requiring multi-step reasoning, external tool execution, or iterative query refinement.", "Contrasts with Agentic AI, where autonomous agents maintain state, evaluate intermediate outputs, plan multi-step execution graphs, invoke external tools, and loop until goals are verified."]}, {"id": "KP2", "description": "Identify concrete enterprise failure modes of static RAG that necessitate transitioning to agentic workflows.", "required": true, "acceptable_evidence": ["Technical keywords: multi-hop queries, ambiguous inputs, external API execution, multi-repository retrieval, validation failure.", "Details specific scenarios where basic RAG fails: (1) queries requiring actions beyond text generation (e.g., booking a service appointment, querying live database telemetry), (2) multi-hop troubleshooting requiring sequential document lookups, and (3) ambiguous questions where the system must proactively ask clarifying questions before searching.", "References the EV Call Center evolution where complex battery diagnostic workflows required dynamic multi-step agent orchestration."]}, {"id": "KP3", "description": "Deconstruct specialized multi-agent collaboration patterns (Router, Diagnostic Retriever, Synthesis & Guardrail Agents).", "required": true, "acceptable_evidence": ["Technical keywords: multi-agent architecture, specialized roles, Router Agent, Retrieval Specialist, Verifier Agent, LangGraph checkpoints.", "Explains decomposing complex tasks into modular agents: an Intent Router classifies user goals; a Diagnostic Retrieval Agent executes targeted vector and graph searches; a Verification Agent cross-checks claims against safety policies; and a Response Generator crafts empathetic customer messaging.", "Details state handoffs and memory checkpointing across agents in LangGraph."]}, {"id": "KP4", "description": "Analyze operational and latency trade-offs between static RAG speed and multi-agent reasoning depth.", "required": false, "acceptable_evidence": ["Technical keywords: latency overhead, token cost, loop termination, max_iterations, deterministic guardrails.", "Analyzes trade-offs: static RAG completes in 1-2 seconds with 1 LLM call; agentic systems incur 4-10+ seconds and multiple LLM calls, requiring strict maximum iteration limits (`max_iterations=5`), cycle detection, and fallback timeouts to prevent runaway loops."]}], "critical_failures": ["Claims standard RAG can autonomously execute multi-step database mutations and external API actions without an agentic tool-calling loop.", "Recommends complex multi-agent architectures for simple factual document lookups where static RAG is faster, cheaper, and more reliable.", "Fails to specify loop termination criteria or safety guardrails in agentic systems, allowing infinite execution cycles."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'What are the key steps in the query pipeline of a RAG system, from user input to final response generation?', '{"key_points": [{"id": "KP1", "description": "Detail query intake preprocessing: validation, PII scrubbing, spell correction, and intent classification.", "required": true, "acceptable_evidence": ["Technical keywords: query cleaning, PII detection (Presidio), spell correction (SymSpell), intent classification, language detection.", "Explains the runtime intake sequence: (1) validate query length and reject prompt injection attempts, (2) redact sensitive PHI/PII via Microsoft Presidio, (3) correct technical typos in diagnostic codes via SymSpell, and (4) classify intent to determine whether retrieval is required or if it is an out-of-scope query.", "Notes that cleaning queries dramatically improves embedding quality and prevents PII leakage into vector databases."]}, {"id": "KP2", "description": "Execute runtime query embedding, hybrid multi-channel search, and metadata-constrained vector retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: query embedding, all-MiniLM-L6-v2, Milvus HNSW search, BM25 keyword search, metadata pre-filtering.", "Details query execution: generating dense 768-dim embeddings using the exact tokenizer and model used at index time, passing vector queries to Milvus with metadata filters (`model_year == 2024 AND system == ''BATTERY''`), and concurrently querying BM25 for exact code matches.", "Explains combining dense and sparse results via Reciprocal Rank Fusion (RRF)."]}, {"id": "KP3", "description": "Execute cross-encoder reranking, prompt assembly with grounding constraints, and streaming LLM generation.", "required": true, "acceptable_evidence": ["Technical keywords: Cross-Encoder reranking, top-k selection, prompt assembly, strict grounding prompt, Server-Sent Events (SSE).", "Explains passing top candidates through a Cross-Encoder (`bge-reranker-base`) to select the top 3-5 most relevant chunks, injecting chunks into structured prompt XML tags, and streaming generated tokens back to the user interface via Server-Sent Events (SSE).", "Details ensuring responses include explicit citations and confidence scores."]}], "critical_failures": ["Embeds raw, uncleaned user queries without preprocessing, allowing spelling errors and PII to degrade retrieval and violate privacy.", "Uses a different embedding model or pooling strategy at query time than was used during document ingestion indexing.", "Omits streaming (SSE) in real-time user-facing pipelines, forcing users to wait several seconds for full generation completion."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What are the main components of a RAG pipeline, and how do data processing, retrieval, augmentation, and generation interact in an end-to-end system?', '{"key_points": [{"id": "KP1", "description": "Architect the offline ingestion pipeline: document collection, layout-aware parsing, chunking, and vector indexing.", "required": true, "acceptable_evidence": ["Technical keywords: offline ingestion, Docling, OCR, semantic chunking, token overlap, Sentence-Transformers, Milvus HNSW.", "Details the data ingestion architecture: pulling multi-format enterprise documents (PDF manuals, scanned technician reports, Confluence pages, HTML portals), extracting structured text and tables with Docling, splitting into semantic chunks with 10% token overlap, generating 768-dim embeddings, and persisting vectors and metadata into Milvus.", "Highlights metadata tagging with document ID, version, section, and effective dates."]}, {"id": "KP2", "description": "Architect the online retrieval and augmentation pipeline: query processing, hybrid search, RRF fusion, and reranking.", "required": true, "acceptable_evidence": ["Technical keywords: online retrieval, query embedding, hybrid search, BM25, Reciprocal Rank Fusion, Cross-Encoder reranking.", "Explains runtime retrieval flow: converting user queries to embeddings, executing parallel Milvus vector search and BM25 keyword search, merging candidate pools via RRF ($k=60$), and scoring candidates with a Cross-Encoder to extract the top-K evidence passages.", "Details assembling prompt context with strict citation instructions."]}, {"id": "KP3", "description": "Architect the generation, guardrail validation, and observability pipeline.", "required": true, "acceptable_evidence": ["Technical keywords: grounded generation, NeMo Guardrails, hallucination checks, Langfuse tracing, audit logging.", "Explains passing the augmented prompt to an LLM (e.g., Llama-3 / GPT-4) at `temperature=0.0`, running generated outputs through guardrail filters (PII masking, toxic output filtering, NLI faithfulness verification), and logging complete execution traces (prompts, retrieved chunks, token counts, latency) to Langfuse for operational auditability."]}], "critical_failures": ["Conflates the offline ingestion pipeline with the online runtime query pipeline, failing to understand their separation of concerns.", "Omits the augmentation stage, jumping directly from raw retrieval to unconstrained generation without context structuring or prompt boundaries.", "Lacks guardrails and observability logging, making production debugging and regulatory compliance impossible."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What challenges arise when scaling from POC to production in RAG systems, and how do you address them?', '{"key_points": [{"id": "KP1", "description": "Contrast lightweight POC components (Streamlit, local ChromaDB, naive vector search) with production enterprise architecture.", "required": true, "acceptable_evidence": ["Technical keywords: POC vs Production, Streamlit to React/FastAPI, ChromaDB to Milvus, single-node to distributed Kubernetes (EKS).", "Details the architectural evolution from the Study Guides: POC used Streamlit, embedded ChromaDB, and naive cosine similarity over raw PDFs; production evolved to decoupled React frontend, containerized FastAPI on Amazon EKS, distributed Milvus with HNSW indexing, and S3 object storage.", "Explains why POC architectures collapse under multi-tenant concurrent traffic and large document corpora."]}, {"id": "KP2", "description": "Analyze retrieval quality bottlenecks encountered at scale: vocabulary mismatch, chunk fragmentation, and hallucinations.", "required": true, "acceptable_evidence": ["Technical keywords: semantic drift, exact code retrieval misses, hallucinated procedures, hybrid search (BM25 + Dense), Cross-Encoder reranker.", "Explains technical failures that emerged as corpus scaled from 100 documents to 100,000+: pure semantic search returned wrong vehicle models or missed exact error codes, fixed-size chunking broke tables, and models hallucinated answers when retrieval returned partial context.", "Details architectural fixes: layout-aware Docling parsing, hybrid retrieval with RRF, and Cross-Encoder reranking."]}, {"id": "KP3", "description": "Implement enterprise production controls: automated evaluation gates, multi-tenant RBAC, and observability tracing.", "required": true, "acceptable_evidence": ["Technical keywords: Continuous Calibration (CC/CD), Golden Dataset, Langfuse tracing, metadata filtering, PII redaction (Presidio).", "Details production operationalization: establishing automated CI/CD Golden Dataset gates to prevent accuracy regressions, enforcing department-level RBAC via metadata partition pruning, scrubbing customer PII with Presidio, and deploying distributed tracing with Langfuse.", "Demonstrates how production engineering shifted focus from basic prompting to end-to-end data pipelines and governance."]}], "critical_failures": ["Assumes scaling a RAG system to production merely requires deploying the Streamlit + ChromaDB POC onto a larger virtual machine.", "Fails to identify retrieval precision drops and exact keyword failures that inevitably occur when scaling vector databases to large corpora.", "Ignores enterprise governance requirements: data privacy (PII), multi-tenancy, CI/CD evaluation gates, and observability tracing."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'What database schema or indexing strategies do you use to enable efficient session and user data retrieval?', '{"key_points": [{"id": "KP1", "description": "Design normalized session and message entity schemas with composite indexing for sub-10ms chronological retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: session schema, message schema, composite index (session_id, created_at), foreign keys, PostgreSQL / DynamoDB.", "Details relational schema design: `chat_sessions (session_id UUID PK, user_id, tenant_id, created_at)` and `chat_messages (message_id UUID PK, session_id FK, role ENUM, content TEXT, token_count INT, metadata JSONB, created_at TIMESTAMPTZ)`.", "Explains creating a composite B-Tree index on `(session_id, created_at DESC)` to enable instantaneous retrieval of the latest $K$ conversation turns without full table scans."]}, {"id": "KP2", "description": "Architect horizontal scaling using partitioned NoSQL storage (Amazon DynamoDB) with partition and sort keys.", "required": true, "acceptable_evidence": ["Technical keywords: DynamoDB, partition key (PK: session_id), sort key (SK: message_timestamp), single-table design, TTL.", "Details NoSQL single-table schema design: `PK: SESSION#<session_id>` and `SK: MSG#<timestamp>#<message_id>`, allowing sequential range queries (`QueryAPI` with `ScanIndexForward=False` and `Limit=10`) with predictable single-digit millisecond latency regardless of total dataset size.", "Mentions configuring Time-To-Live (TTL) attributes on transient chat sessions to automatically purge expired records and manage storage costs."]}, {"id": "KP3", "description": "Integrate low-latency in-memory caching (Redis) for active conversation state and sliding window token management.", "required": true, "acceptable_evidence": ["Technical keywords: Redis List (LPUSH/LRANGE), TTL, write-through caching, session eviction, sliding window context.", "Explains using Redis to buffer the active conversation window (`LPUSH session:<id>:messages` with 2-hour TTL), enabling sub-millisecond context retrieval during active user chats while asynchronously flushing completed sessions to durable PostgreSQL/DynamoDB storage.", "Details maintaining token counters in Redis to enforce sliding window trimming before prompt compilation."]}], "critical_failures": ["Stores chat messages as a single unbounded JSON blob inside a single row, causing severe write contention and serialization latency as conversations grow.", "Queries message histories with sequential table scans (`WHERE session_id = X ORDER BY created_at`) without composite indexing.", "Omits pagination and limit bounds, loading thousands of historical messages into application memory on every user turn."]}', 1),
('TECHNICAL', 'AI Engineering', 'NLP', 'MEDIUM', 'SPECIFIC', 90, 'What happens during embedding generation, and how does it capture semantic meaning?', '{"key_points": [{"id": "KP1", "description": "Explain the mathematical process of mapping discrete text tokens to continuous dense vector embeddings via Transformer encoder layers.", "required": true, "acceptable_evidence": ["Technical keywords: tokenization, subword tokens, Transformer encoder, self-attention hidden states, continuous vector space, dimensional projection.", "Explains the transformation pipeline: text is split into subword tokens (WordPiece / Byte-Pair Encoding), passed through lookup tables into initial token embeddings, processed across multiple Transformer self-attention layers to capture contextual syntax and semantics, yielding contextualized token representations in $\\\\mathbb{R}^{L \\\\times D}$.", "Contrasts discrete sparse one-hot encodings with continuous dense representations."]}, {"id": "KP2", "description": "Analyze sentence-level pooling strategies (Mean Pooling vs. CLS Token) and vector normalization.", "required": true, "acceptable_evidence": ["Technical keywords: mean pooling, attention mask, [CLS] token pooling, L2 normalization, unit hypersphere.", "Explains aggregating token hidden states into a single sentence vector: mean pooling computes the element-wise average of all token vectors weighted by the attention mask ($\\u000bec{u} = \\\\frac{\\\\sum_{i=1}^L m_i \\\\vec{h}_i}{\\\\sum_{i=1}^L m_i}$), outperforming raw `[CLS]` embeddings in downstream similarity tasks.", "Details applying $L_2$ normalization ($\\u000bec{v} = \\\\vec{u} / \\\\|\\\\vec{u}\\\\|_2$) to project vectors onto a unit hypersphere, making cosine similarity mathematically identical to fast dot products."]}, {"id": "KP3", "description": "Explain how contrastive training (InfoNCE / MultipleNegativesRankingLoss) shapes semantic geometric proximity.", "required": true, "acceptable_evidence": ["Technical keywords: contrastive learning, MultipleNegativesRankingLoss, InfoNCE, positive pairs, in-batch negatives, cosine similarity.", "Explains how models like Sentence-Transformers are trained: pairs of semantically related sentences (query and relevant passage) are pulled together in geometric space, while in-batch negative passages are actively pushed apart via cross-entropy contrastive loss.", "Details how this training ensures texts with similar conceptual meaning cluster together regardless of lexical phrasing differences."]}], "critical_failures": ["Claims embedding models simply look up word vectors in Word2Vec dictionaries without contextual Transformer self-attention.", "Performs mean pooling without applying the attention mask, allowing zero-padded tokens to distort sentence vector representations.", "Omits L2 normalization when computing inner product similarity, leading to erroneous distance rankings influenced by text length."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'What is Graph RAG, and how does it improve retrieval by leveraging entity relationships?', '{"key_points": [{"id": "KP1", "description": "Explain GraphRAG architecture combining entity-relation knowledge graphs with dense vector embeddings.", "required": true, "acceptable_evidence": ["Technical keywords: GraphRAG, knowledge graph, entity extraction, relation extraction, Neo4j, Cypher, hybrid graph-vector retrieval.", "Explains that standard vector RAG struggles with multi-hop relational questions (e.g., ''What diagnostic steps are shared between EV battery pack A and thermal cooling module B?''); GraphRAG solves this by constructing a structured graph of entities (Vehicles, Components, Error Codes, Policies) and relations (`CAUSES`, `REQUIRES`, `PART_OF`, `REGULATES`) in Neo4j alongside vector embeddings.", "Details combining vector similarity with graph path traversal."]}, {"id": "KP2", "description": "Detail the graph extraction pipeline: LLM-based entity-relationship extraction, entity resolution, and ontology mapping.", "required": true, "acceptable_evidence": ["Technical keywords: LLM extraction, OpenIE, entity disambiguation, canonical ontology, nodes and edges, community summaries.", "Explains the construction pipeline: document chunks are passed to an LLM with structured schemas to extract subject-predicate-object triples, disambiguate entity synonyms (e.g., ''High-Voltage Battery'', ''HV Pack'', and ''Traction Battery'' resolved to node `Entity:HV_Battery`), and persist nodes and directed edges into Neo4j.", "Mentions hierarchical Leiden/community clustering to generate high-level thematic summaries."]}, {"id": "KP3", "description": "Execute graph-traversal augmented retrieval to provide global multi-hop context to the LLM.", "required": true, "acceptable_evidence": ["Technical keywords: Cypher queries, multi-hop traversal, subgraph expansion, neighborhood retrieval, global context synthesis.", "Details runtime query flow: the system identifies key entities in user queries, executes vector search for seed nodes, runs 1-to-2 hop Cypher graph traversals to gather connected dependencies and constraints, and injects both the knowledge subgraph and corresponding text passages into the prompt.", "Demonstrates how GraphRAG enables comprehensive answers across disparate document sections."]}], "critical_failures": ["Claims GraphRAG replaces vector databases completely rather than augmenting vector retrieval with structured relational traversal.", "Cannot explain how knowledge graphs are constructed from unstructured text documents using LLM entity-relation extraction.", "Fails to identify multi-hop relational reasoning as the primary problem solved by GraphRAG over standard vector search."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'What is Retrieval-Augmented Generation (RAG), and how does it improve upon a standalone LLM?', '{"key_points": [{"id": "KP1", "description": "Define Retrieval-Augmented Generation (RAG) and explain how external knowledge retrieval overcomes parametric LLM limitations.", "required": true, "acceptable_evidence": ["Technical keywords: Retrieval-Augmented Generation (RAG), parametric memory vs external knowledge, knowledge cutoff, hallucinations, private enterprise data.", "Explains that pre-trained LLMs rely strictly on static parametric memory (weights learned during training), making them prone to hallucinations, blind to post-training cutoff information, and unaware of private enterprise documentation.", "Defines RAG: a dynamic architecture that retrieves relevant factual passages from external knowledge stores (vector databases, search engines) at runtime and injects them into the prompt as verified grounding evidence."]}, {"id": "KP2", "description": "Detail core advantages of RAG over model retraining: real-time freshness, explainable citations, and data governance.", "required": true, "acceptable_evidence": ["Technical keywords: real-time data freshness, source citations, auditability, access control (RBAC), zero retraining cost.", "Details operational benefits: (1) Instant updates: new manuals, firmware notes, or policy changes become searchable immediately upon indexing without million-dollar retraining runs, (2) Verifiable citations: answers include exact document, page, and section references, and (3) Security/RBAC: access permissions are enforced at retrieval time so users only receive context they are authorized to view."]}, {"id": "KP3", "description": "Walk through the foundational tripartite RAG operational flow: Retrieve, Augment, and Generate.", "required": true, "acceptable_evidence": ["Technical keywords: Retrieve-Augment-Generate, query embedding, vector database, prompt template, grounded synthesis.", "Outlines the three core steps: (1) **Retrieve**: user query is encoded to find top-K semantically relevant chunks in vector/lexical indices, (2) **Augment**: retrieved chunks and system grounding instructions are compiled into an augmented prompt template, and (3) **Generate**: the LLM synthesizes a fluent, factually grounded answer based exclusively on the provided context."]}], "critical_failures": ["Claims RAG updates or fine-tunes LLM weights during the retrieval or generation process.", "Fails to articulate the distinction between static parametric memory in weights and dynamic non-parametric retrieval from external corpora.", "Believes RAG is merely a chatbot UI rather than an end-to-end information retrieval and synthesis architecture."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'What is a vector database, and why is it important in LLM-based applications?', '{"key_points": [{"id": "KP1", "description": "Define vector databases and contrast high-dimensional vector search with traditional relational B-Tree indexing.", "required": true, "acceptable_evidence": ["Technical keywords: vector database, high-dimensional vector space, curse of dimensionality, Approximate Nearest Neighbor (ANN), B-Tree vs vector index.", "Explains that traditional databases use scalar 1D B-Tree indexes ($O(\\\\log N)$ exact lookups) which fail in high-dimensional spaces (e.g., 768 or 1536 dimensions) due to the curse of dimensionality, where distance between points becomes uniform and B-Trees degenerate to $O(N)$ linear scans.", "Defines vector databases as specialized storage engines designed to index, store, and query high-dimensional embeddings using Approximate Nearest Neighbor (ANN) search algorithms."]}, {"id": "KP2", "description": "Explain core ANN indexing mechanics: graph-based (HNSW), inverted file (IVF), and tree-based indexes.", "required": true, "acceptable_evidence": ["Technical keywords: HNSW, IVF, Voronoi cells, graph traversal, distance metrics (Cosine, L2, Dot Product), sub-linear search.", "Details how vector databases achieve sub-linear ($O(\\\\log N)$) search speeds by constructing specialized ANN indexes: HNSW builds multi-layer proximity graphs for greedy routing, while IVF clusters vectors into Voronoi centroids to prune search space.", "Explains distance metric calculation using hardware-accelerated SIMD instructions for Cosine Similarity, Euclidean Distance ($L_2$), and Inner Product (IP)."]}, {"id": "KP3", "description": "Detail enterprise vector database capabilities: filtered search, ACID durability, horizontal sharding, and CRUD lifecycle.", "required": true, "acceptable_evidence": ["Technical keywords: metadata pre-filtering, Milvus, Qdrant, Pinecone, collection partitioning, write-ahead log (WAL), replication.", "Explains that enterprise vector databases (Milvus, Qdrant) provide complete database management features beyond raw indexing libraries: hybrid metadata filtering (searching vectors within specified tenant or date boundaries), Write-Ahead Logging (WAL) for crash durability, dynamic CRUD operations, and distributed horizontal sharding across storage and query nodes."]}], "critical_failures": ["Claims vector databases perform exact distance calculations against every vector in the database on every query, failing to understand ANN indexing.", "Asserts that traditional relational SQL databases with standard B-Trees can efficiently index 1,536-dimensional vectors at scale.", "Treats vector databases as simple file caches without recognizing their distributed storage, indexing, and metadata filtering capabilities."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'What is the end-to-end flow of your product lookup agent, including query processing, orchestration, retrieval, ranking, and response generation?', '{"key_points": [{"id": "KP1", "description": "Deconstruct customer product queries into structured attributes, technical specifications, and intent slots.", "required": true, "acceptable_evidence": ["Technical keywords: product lookup agent, query parsing, entity extraction, slot filling, Pydantic schema, structured attributes.", "Explains parsing conversational queries (e.g., ''Level 2 home EV charger compatible with 2024 model under $600'') into explicit search filters: `category: ''EV_CHARGER''`, `charge_level: 2''`, `compatibility: ''2024_EV''`, `max_price: 600.00`, and `intent: ''PURCHASE''`.", "Details using lightweight LLMs or fine-tuned NER models with Pydantic validation to ensure deterministic parameter extraction."]}, {"id": "KP2", "description": "Execute hybrid catalog retrieval combining SQL attribute filtering with dense semantic specification matching.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid attribute retrieval, SQL hard filters, vector similarity, catalog embeddings, Milvus pre-filtering.", "Details two-stage catalog matching: executing structured relational queries on hard constraints (in-stock status, price range, brand filters) combined with vector search on product descriptions, user reviews, and technical specifications.", "Explains applying vector pre-filtering so semantic similarity search executes strictly over inventory satisfying hard business constraints."]}, {"id": "KP3", "description": "Rank catalog candidates using multi-factor scoring (compatibility, price, popularity) and synthesize customer recommendations.", "required": true, "acceptable_evidence": ["Technical keywords: multi-factor ranking, compatibility score, margin/popularity weighting, personalized synthesis, source linking.", "Explains computing composite ranking scores: $Score = w_1 \\\\cdot \\\\text{SemanticSimilarity} + w_2 \\\\cdot \\\\text{ReviewRating} + w_3 \\\\cdot \\\\text{PriceFit}$, ensuring top recommendations maximize customer utility and catalog availability.", "Details prompt synthesis: presenting top 3 matched products with itemized specification comparisons, exact compatibility notes, and direct SKU links."]}], "critical_failures": ["Relies solely on dense vector search without hard attribute filtering, returning out-of-stock or incompatible products that violate customer price limits.", "Allows the agent to generate imaginary product SKUs or pricing ungrounded in the live catalog database.", "Fails to parse technical compatibility constraints, recommending accessories that do not match the customer''s specified vehicle model."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What is the role of re-ranking and top-K selection in a RAG pipeline, and how do they impact answer quality?', '{"key_points": [{"id": "KP1", "description": "Analyze the empirical trade-offs of Top-K selection between recall completeness and context clutter / token cost.", "required": true, "acceptable_evidence": ["Technical keywords: Top-K selection, K cutoff tuning, Recall vs Precision, context clutter, token cost, distraction effect.", "Explains the trade-offs: setting $K$ too low ($K=1$ or $K=2$) risks missing critical supporting evidence or multi-clause conditions; setting $K$ too high ($K=15$ or $K=20$) floods the prompt with marginally relevant noise, increases inference latency and token billing, and distracts the LLM from key facts.", "Details empirical tuning finding $K=3$ to $K=5$ optimal after Cross-Encoder reranking."]}, {"id": "KP2", "description": "Mitigate the ''lost-in-the-middle'' phenomenon by strategic positional reordering of retrieved context chunks.", "required": true, "acceptable_evidence": ["Technical keywords: lost-in-the-middle, primacy and recency bias, U-shaped attention curve, context reordering, document placement.", "Explains research showing Transformer self-attention attends heavily to tokens at the very beginning (primacy bias) and end (recency bias) of long prompts, while frequently ignoring information buried in the middle (the U-shaped attention curve).", "Details the reordering algorithm: placing the #1 highest-scoring chunk first, #2 highest-scoring chunk last, and lower-ranked chunks in the middle to ensure critical evidence receives maximum attention."]}, {"id": "KP3", "description": "Implement dynamic score-threshold cutoffs rather than static fixed-K truncation.", "required": true, "acceptable_evidence": ["Technical keywords: dynamic score threshold, delta cutoff, similarity score gap, adaptive K, quality gate.", "Explains replacing rigid fixed $K=5$ with adaptive thresholding: include candidates up to $K=5$ only if their Cross-Encoder relevance score exceeds a minimum baseline (e.g., score $> 0.60$) and falls within $\\\\Delta \\\\le 0.15$ of the top candidate.", "Details how dynamic cutoff drops irrelevant chunks when only 1 or 2 high-quality passages exist for a specific factual question."]}], "critical_failures": ["Assumes passing 20+ chunks into large context LLMs (128k context) always improves answer quality, ignoring attention dilution and the lost-in-the-middle effect.", "Sorts retrieved chunks in arbitrary or descending order without considering Transformer attention positional bias.", "Uses fixed static Top-K cutoffs that blindly inject low-scoring, irrelevant chunks when only one relevant document exists."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'EASY', 'SPECIFIC', 60, 'What is the role of the Diagnostic Retrieval Agent, and how does it leverage the vector database for information retrieval?', '{"key_points": [{"id": "KP1", "description": "Define the specialized role of the Diagnostic Retrieval Agent within the EV customer call center multi-agent system.", "required": true, "acceptable_evidence": ["Technical keywords: Diagnostic Retrieval Agent, specialized sub-agent, EV Call Center, vehicle diagnostic workflows, DTC error codes, service manuals.", "Explains that the Diagnostic Retrieval Agent is a dedicated sub-agent tasked with technical knowledge discovery across complex automotive engineering repositories: EV service manuals, high-voltage battery diagnostic trees, firmware release notes, and technical service bulletins (TSBs).", "Contrasts its technical lookup role with customer-facing conversational agents and scheduling agents."]}, {"id": "KP2", "description": "Execute targeted multi-vector queries and vehicle model metadata filtering in Milvus.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus vector search, vehicle metadata pre-filtering (VIN, model, trim, firmware_version), diagnostic code indexing.", "Details how the agent inspects vehicle telemetry (e.g., VIN prefix, model year, firmware version 2024.12) passed by the Router Agent, generates embeddings, and applies strict Milvus partition filters to ensure search runs exclusively over documentation valid for that exact vehicle configuration.", "Prevents dangerous guidance caused by cross-model or outdated firmware recommendations."]}, {"id": "KP3", "description": "Traverse multi-step diagnostic decision trees and synthesize structured troubleshooting checklists.", "required": true, "acceptable_evidence": ["Technical keywords: diagnostic decision trees, step-by-step procedures, safety warnings, structured checklist, auditable source tagging.", "Explains how the agent traverses sequential troubleshooting logic (e.g., Step 1: Verify 12V auxiliary battery voltage -> Step 2: Check high-voltage contactor state -> Step 3: Inspect charging port lock actuator).", "Details packaging output into structured, auditable checklists with high-voltage safety alerts prominently highlighted for customer care agents."]}], "critical_failures": ["Treats the Diagnostic Retrieval Agent as a generic chatbot rather than a specialized technical retrieval specialist executing metadata-filtered queries.", "Fails to filter technical searches by vehicle model year and firmware version, generating invalid or hazardous mechanical advice.", "Omits high-voltage safety warnings when returning electrical and battery troubleshooting procedures."]}', 1),
('TECHNICAL', 'AI Engineering', 'NLP', 'EASY', 'SPECIFIC', 60, 'What is the significance of embedding vector dimensions, and how did you determine that 768 dimensions were optimal for your system?', '{"key_points": [{"id": "KP1", "description": "Analyze the mathematical and geometric expressiveness of 768-dimensional embedding representations.", "required": true, "acceptable_evidence": ["Technical keywords: 768 dimensions, BERT-base, BGE-base, semantic capacity, manifold expressiveness, fine-grained distinction.", "Explains that 768 dimensions (the standard hidden size of BERT-base and Transformer encoders) provides sufficient semantic capacity to encode complex technical syntax, nuanced domain terminology, and multi-sentence relationships without collapsing semantic clusters.", "Contrasts with lower-dimensional spaces (e.g., 128 or 384 dimensions) which suffer from representation crowding and higher geometric overlap."]}, {"id": "KP2", "description": "Analyze computational, memory, and storage resource trade-offs: 384 vs. 768 vs. 1536 dimensions.", "required": true, "acceptable_evidence": ["Technical keywords: memory footprint, RAM requirements, FLOPs per query, HNSW index build time, network serialization overhead.", "Quantifies trade-offs: a 768-dim FP32 vector occupies 3,072 bytes (3KB); a 1,536-dim vector (OpenAI text-embedding-ada-002) requires 6,144 bytes (6KB), doubling RAM, HNSW graph construction time, and distance calculation FLOPs.", "Explains that 768-dim models (e.g., `bge-base-en-v1.5`) strike the sweet spot: near-identical MTEB retrieval benchmarks to 1,536-dim models at 50% lower infrastructure cost and significantly faster search latency."]}, {"id": "KP3", "description": "Detail dimensional consistency requirements across ingestion indexing and live query serving.", "required": true, "acceptable_evidence": ["Technical keywords: dimension mismatch, schema validation, index definition, Matryoshka Embeddings (MRL), vector space projection.", "Emphasizes that vector databases enforce strict dimensionality schemas: passing an embedding with different dimensionality (e.g., 384-dim query vector into a 768-dim collection) triggers immediate runtime vector engine exceptions.", "Mentions Matryoshka Representation Learning (MRL) techniques that allow truncating vectors to lower dimensions while preserving retrieval performance."]}], "critical_failures": ["Claims higher embedding dimensions always guarantee better RAG retrieval accuracy regardless of domain fine-tuning or model architecture.", "Fails to calculate memory and infrastructure costs associated with high-dimensional vector storage across millions of chunks.", "Attempts to search a 768-dimension vector collection using an embedding model that outputs 384 or 1,536 dimensions."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'Python & Data Manipulation', 'EASY', 'SPECIFIC', 60, 'What is your level of proficiency in Python, and how have you used it in building AI or RAG systems?', '{"key_points": [{"id": "KP1", "description": "Demonstrate advanced Python idioms: type hints, async/await concurrency, generators, and clean object-oriented architecture.", "required": true, "acceptable_evidence": ["Technical keywords: modern Python (3.11+), type annotations (typing / mypy), asyncio (async/await), generators/yield, Pydantic v2.", "Explains writing production-grade Python: enforcing strict static type checking with `mypy` and Pydantic schemas, utilizing `asyncio` for non-blocking I/O across parallel vector search and LLM API streaming, and using generators for memory-efficient document chunk streaming.", "Contrasts maintainable, modular Python codebases with fragile notebook scripting."]}, {"id": "KP2", "description": "Detail practical experience building robust data manipulation and ETL pipelines using NumPy, Pandas, and Polars.", "required": true, "acceptable_evidence": ["Technical keywords: NumPy vectorized operations, Pandas DataFrame, Polars, memory-efficient data processing, batch vectorization.", "Details real-world data manipulation: performing vectorized similarity math in NumPy, cleaning and restructuring heterogeneous datasets using Pandas/Polars, and handling large CSV/JSON logs with chunked batch processing to avoid out-of-memory (OOM) crashes.", "Mentions building reusable preprocessing transforms bundled in `scikit-learn` pipelines."]}, {"id": "KP3", "description": "Showcase production engineering discipline: unit testing, mocking, profiling, and package dependency management.", "required": true, "acceptable_evidence": ["Technical keywords: pytest, pytest-asyncio, unittest.mock, cProfile / memory_profiler, Poetry, ruff / black.", "Details testing practices: writing deterministic unit and integration test suites in `pytest` with mocked Milvus and OpenAI network calls, profiling CPU/memory bottlenecks using `cProfile` and `tracemalloc`, and managing deterministic dependencies via `poetry.lock`.", "Highlights continuous integration linting with `ruff` and `black` to enforce enterprise code standards."]}], "critical_failures": ["Shows familiarity with Python only through exploratory Jupyter Notebook scripts without experience in production modules, packages, or testing.", "Writes blocking, synchronous loops for network-heavy API and database operations in high-concurrency production services.", "Lacks understanding of dependency locking, type hints, or automated unit testing practices."]}', 1),
('TECHNICAL', 'AI Engineering', 'NLP', 'MEDIUM', 'SPECIFIC', 90, 'What is your understanding of BERT-s architecture, including token, segment, and positional embeddings, and how have you applied it in practice?', '{"key_points": [{"id": "KP1", "description": "Deconstruct BERT''s tripartite input embedding layer: Token Embeddings, Segment (Token Type) Embeddings, and Positional Embeddings.", "required": true, "acceptable_evidence": ["Technical keywords: BERT input representation, WordPiece token embeddings, Segment / Token Type IDs, absolute positional embeddings, element-wise addition.", "Explains that BERT constructs input tokens by summing three distinct embedding vectors element-wise: (1) **Token Embeddings** (30,522-vocab WordPiece lookup), (2) **Segment Embeddings** (binary 0 or 1 IDs indicating sentence A vs. sentence B), and (3) **Positional Embeddings** (learned absolute positional indices $0 \\\\dots 511$).", "Details how LayerNorm and Dropout are applied to this composite sum before the first Transformer encoder layer."]}, {"id": "KP2", "description": "Explain multi-head self-attention mechanics: Query, Key, Value matrix transformations and scaled dot-product attention.", "required": true, "acceptable_evidence": ["Technical keywords: Multi-Head Self-Attention, Query (Q), Key (K), Value (V), scaled dot-product attention, Softmax(QK^T / sqrt(d_k)) * V, bi-directional context.", "Explains the mathematical attention mechanism: input tokens are projected into Query, Key, and Value vectors; attention weights are computed via scaled dot products $\\\\text{Attention}(Q, K, V) = \\\\text{softmax}\\\\left(\\\\frac{QK^T}{\\\\sqrt{d_k}}\\\\right)V$.", "Highlights BERT''s bi-directional architecture: unlike causal/autoregressive models (GPT), every token attends to all tokens in both left and right directions simultaneously."]}, {"id": "KP3", "description": "Analyze how Sentence-Transformers (SBERT) adapts BERT architecture for scalable semantic vector search.", "required": true, "acceptable_evidence": ["Technical keywords: Sentence-BERT (SBERT), Siamese / Triplet networks, mean pooling, fixed-size sentence vector, Bi-Encoder inference.", "Explains that standard BERT requires passing both sentences together ($O(N^2)$ cross-attention comparisons), making large-scale retrieval computationally intractable; SBERT uses a Siamese/triplet network to tune BERT encoder weights, adding a mean pooling layer to produce fixed-size vector representations for fast cosine retrieval ($O(N)$).", "Details the transition from raw masked language modeling to contrastive sentence embedding tuning."]}], "critical_failures": ["Concatenates token, segment, and position embeddings instead of summing them element-wise.", "Confuses BERT''s bi-directional encoder architecture with GPT''s causal, autoregressive decoder architecture.", "Claims standard pre-trained BERT outputs high-quality out-of-the-box sentence embeddings via `[CLS]` token without fine-tuning or mean pooling (ignoring embedding collapse)."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What metadata did you attach to each chunk?', '{"key_points": [{"id": "KP1", "description": "Design an extensible JSON/BSON metadata schema capturing document provenance, structural hierarchy, and access boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: metadata schema, chunk metadata, document provenance, structural hierarchy, tenant_id, access_control_roles.", "Details the required metadata fields attached to every chunk: (1) **Provenance**: `document_id`, `document_title`, `source_url`, `checksum_sha256`, (2) **Hierarchy**: `page_number`, `section_heading`, `chunk_index`, `parent_section_id`, and (3) **Governance**: `tenant_id`, `department`, `classification_level` (''INTERNAL'', ''CONFIDENTIAL'').", "Explains how structured metadata enables exact citations and strict security boundaries."]}, {"id": "KP2", "description": "Incorporate domain-specific temporal and taxonomy attributes (model years, firmware versions, Medicaid program types).", "required": true, "acceptable_evidence": ["Technical keywords: domain taxonomy, effective_date, expiration_date, vehicle_model, firmware_version, state, program_type (Medicaid/CHIP).", "Provides concrete schema examples from the Study Guides: EV Call Center chunks include `vehicle_model: ''Model-X''`, `model_year: 2024`, `firmware_version: ''v2024.12''`, `system_category: ''BATTERY_CHARGING''`; Healthcare Medicaid chunks include `state: ''CA''`, `program: ''Medi-Cal''`, `effective_date: ''2026-01-01''`, `billing_code: ''CPT-99213''`.", "Explains how domain attributes prevent temporal confusion and cross-jurisdiction errors."]}, {"id": "KP3", "description": "Enable hardware-accelerated scalar pre-filtering and partition pruning in vector database queries.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus boolean expressions, pre-filtering vs post-filtering, partition pruning, index memory optimization.", "Explains using metadata fields in vector database search filters: `expr = ''tenant_id == \\"corp_a\\" and model_year == 2024 and status == \\"ACTIVE\\"''`. Pre-filtering evaluates metadata predicates to create candidate bitsets before computing vector distances, ensuring search searches strictly valid subsets.", "Contrasts pre-filtering with inefficient post-filtering (which retrieves 50 vectors and discards those failing metadata checks, risking zero returned results)."]}], "critical_failures": ["Stores raw text chunks in the vector database with no metadata or only a generic filename string.", "Omits tenant isolation and role permissions from chunk metadata, creating severe multi-tenant data leakage vulnerabilities.", "Relies on post-filtering rather than vector database native pre-filtering, causing empty results when top-k nearest neighbors belong to other tenants."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'What role did Amazon Bedrock and DynamoDB play in your system, particularly in handling embeddings and private data retrieval?', '{"key_points": [{"id": "KP1", "description": "Integrate Amazon Bedrock for managed foundation model inference, embedding generation, and enterprise security guardrails.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon Bedrock, Titan Embeddings / Cohere, Claude 3 / Llama 3, Bedrock Guardrails, serverless LLM, zero data training policy.", "Details utilizing Amazon Bedrock for serverless model invocation (embedding generation via Titan/Cohere and response generation via Claude 3 / Llama 3) within AWS security boundaries.", "Highlights enterprise data privacy assurances: customer prompts and retrieved data are never used to train base foundation models, and AWS KMS customer-managed keys encrypt payloads at rest."]}, {"id": "KP2", "description": "Enforce network isolation using AWS VPC PrivateLink endpoints to keep AI traffic entirely within private cloud boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: AWS VPC PrivateLink, VPC Endpoints, private subnets, NAT Gateway bypass, internet gateway avoidance, HIPAA/SOC2 compliance.", "Explains routing inference requests from EKS worker nodes in private subnets directly to Amazon Bedrock, S3, and DynamoDB via AWS VPC PrivateLink interface endpoints.", "Highlights security benefits: traffic never traverses the public internet, eliminating public exposure, complying with HIPAA/SOC-2, and reducing NAT Gateway data-processing fees."]}, {"id": "KP3", "description": "Utilize Amazon DynamoDB for low-latency session persistence, audit logging, and document metadata indexing.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon DynamoDB, single-digit millisecond latency, session state, audit logs, Global Secondary Indexes (GSIs), point-in-time recovery (PITR).", "Details DynamoDB usage: storing user chat sessions, tracking tool execution logs, and recording document ingestion metadata with sub-10ms latency.", "Explains using Global Secondary Indexes (GSIs) to query user session histories across dates and enabling Point-in-Time Recovery (PITR) for immutable audit compliance."]}], "critical_failures": ["Routes sensitive enterprise document embeddings and user prompts over the public internet to third-party endpoints rather than utilizing private VPC endpoints.", "Stores unencrypted API keys and secrets in plain text inside container environment variables instead of using IAM Roles and Secrets Manager.", "Fails to establish least-privilege IAM policies, granting unrestricted administrator access to Bedrock and S3 buckets."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'What roles did the router, retriever, and generator agents play in your multi-agent workflow?', '{"key_points": [{"id": "KP1", "description": "Design the Intent Router Agent to classify user goals, extract metadata slots, and route tasks to specialized domain agents.", "required": true, "acceptable_evidence": ["Technical keywords: Intent Router Agent, semantic classification, slot extraction, task dispatching, LangGraph conditional edges.", "Explains that the Router Agent serves as the intelligent dispatcher: it evaluates incoming user inquiries, classifies the primary domain (e.g., Technical Diagnostic, Billing/Warranty, General FAQ, or Human Escalation), extracts critical metadata parameters (model year, error codes, member ID), and triggers corresponding execution branches.", "Details how conditional edge routing in LangGraph prevents invoking expensive multi-step retrieval for simple greetings or FAQs."]}, {"id": "KP2", "description": "Design the Diagnostic Retriever Agent to execute multi-hop technical searches, query reformulation, and evidence validation.", "required": true, "acceptable_evidence": ["Technical keywords: Diagnostic Retriever Agent, multi-hop search, vector & keyword search, evidence sufficiency check, query reformulation.", "Details the Retriever Agent''s internal logic: it converts the Router''s task parameters into targeted hybrid vector and BM25 searches, inspects retrieved chunk confidence, and reformulates queries or traverses knowledge graphs if initial evidence is incomplete.", "Emphasizes that it acts as a research specialist returning structured, validated factual claims rather than customer-facing prose."]}, {"id": "KP3", "description": "Design the Response Generator Agent to synthesize verified evidence into empathetic, policy-aligned customer communication.", "required": true, "acceptable_evidence": ["Technical keywords: Response Generator Agent, customer-facing persona, empathy, tone calibration, policy alignment, source citation formatting.", "Explains the Generator Agent''s role: it ingests the structured evidence produced by the Retriever Agent and crafts clear, professional, and empathetic responses tailored for customer service interactions.", "Details formatting inline citations, highlighting safety warnings, and adhering to strict brand tone guidelines without adding ungrounded information."]}, {"id": "KP4", "description": "Implement shared graph state objects and checkpointing in LangGraph to coordinate inter-agent communication.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph state management, TypedDict state schema, checkpointing, Postgres/Redis checkpointer, error recovery.", "Explains maintaining a centralized `AgentState` object passing conversation context, intermediate retrieval findings, confidence flags, and step histories between nodes.", "Details using LangGraph checkpointers to persist execution state, enabling automated recovery from failures and audit replay."]}], "critical_failures": ["Designs a monolithic single-prompt agent that attempts to handle routing, retrieval, safety verification, and customer messaging all at once, leading to instruction drift.", "Lacks a formal state schema for inter-agent communication, passing unstructured raw text strings between agents.", "Allows the Generator Agent to invent facts or override findings provided by the Retriever Agent without verification."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What strategies did you use to prevent data leakage during both retrieval and generation stages?', '{"key_points": [{"id": "KP1", "description": "Deploy automated PII and PHI detection and masking pipelines using Microsoft Presidio and NER models during ingestion and runtime.", "required": true, "acceptable_evidence": ["Technical keywords: Microsoft Presidio, Named Entity Recognition (NER), PII/PHI redaction, regex patterns, HIPAA Safe Harbor, anonymization.", "Explains deploying Microsoft Presidio with spaCy NER models and custom regular expressions to detect and redact 18 HIPAA identifiers: Social Security Numbers, Medical Record Numbers, member IDs, phone numbers, email addresses, and physical addresses.", "Details replacing sensitive entities with surrogate tokens (e.g., `<MEMBER_ID>`, `<PHONE_NUMBER>`) before storing embeddings in vector databases or sending prompts to LLMs."]}, {"id": "KP2", "description": "Enforce Role-Based Access Control (RBAC) and tenant isolation at retrieval time using metadata filtering.", "required": true, "acceptable_evidence": ["Technical keywords: RBAC, tenant isolation, metadata pre-filtering, department boundaries, JWT claims, cross-tenant data leakage.", "Explains extracting user authorization roles and tenant identity from verified JWT session claims and injecting mandatory filter predicates into vector search (`tenant_id == user.tenant AND department IN user.allowed_depts`).", "Details how hardware pre-filtering ensures users can never retrieve documents, financial terms, or employee records belonging to other tenants or unauthorized departments."]}, {"id": "KP3", "description": "Implement output guardrails and egress filters to intercept accidental credential or private data leakage in generated responses.", "required": true, "acceptable_evidence": ["Technical keywords: egress guardrails, output scanner, regex leak prevention, canary tokens, NeMo Guardrails, zero data retention.", "Details scanning outgoing LLM responses with output guardrails prior to rendering in UI: detecting leaked API tokens, database connection strings, or unmasked personal data.", "Mentions embedding synthetic canary tokens into restricted document stores to automatically flag and alert on unauthorized retrieval attempts."]}], "critical_failures": ["Passes raw, unredacted customer PII/PHI payloads into external third-party LLM APIs, violating HIPAA and GDPR regulations.", "Relies on the LLM to self-enforce tenant data privacy via prompt instructions instead of enforcing hard database-level metadata filters.", "Lacks output scanning, allowing models that memorize private training data to regurgitate sensitive records to unauthorized users."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What strategies would you use to prevent duplicate file processing or duplicate key generation in storage systems?', '{"key_points": [{"id": "KP1", "description": "Generate deterministic cryptographic content hashes (SHA-256) over raw and normalized document payloads.", "required": true, "acceptable_evidence": ["Technical keywords: cryptographic hashing, SHA-256, content addressable storage, normalized payload, deterministic checksum, deduplication.", "Explains computing SHA-256 hashes over incoming document binary streams and normalized text (stripping non-semantic whitespace and formatting differences) to establish an immutable document fingerprint.", "Details using this content hash as the primary idempotency key for ingestion tracking."]}, {"id": "KP2", "description": "Implement distributed idempotent ingestion gates using relational unique constraints or Redis atomic locks.", "required": true, "acceptable_evidence": ["Technical keywords: idempotency gate, UNIQUE constraint, Redis SETNX, atomic lock, duplicate message suppression, transactional upsert.", "Explains preventing duplicate processing in distributed worker pools (e.g., Celery/Kafka consumers): checking the content hash against a metadata table with a `UNIQUE(content_hash)` constraint, or acquiring an atomic Redis distributed lock (`SET lock:<hash> NX EX 300`).", "Details how duplicate webhook triggers or re-delivered Kafka messages safely exit as no-ops."]}, {"id": "KP3", "description": "Construct deterministic vector ID schemes and upsert semantics in the vector store to prevent vector duplication.", "required": true, "acceptable_evidence": ["Technical keywords: deterministic vector IDs, UUID5, upsert semantics, Milvus primary keys, index explosion prevention.", "Explains generating deterministic vector primary keys using UUIDv5 derived from `document_hash + chunk_index`: `chunk_id = uuid5(NAMESPACE_DNS, f''{doc_hash}_{idx}'')`.", "Details configuring vector database `upsert` calls so re-processing an identical document overwrites existing embeddings rather than creating duplicate vector records that degrade search precision."]}], "critical_failures": ["Uses random UUIDs (UUIDv4) for vector chunk primary keys, causing re-ingested documents to create millions of redundant duplicate vectors in Milvus.", "Lacks distributed idempotency locks, allowing parallel worker pods to process and chunk the exact same uploaded PDF multiple times.", "Relies solely on filename matching for deduplication, allowing identical files with different names to duplicate, or overwriting different files that share generic names (''manual.pdf'')."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What techniques would you use to normalize different data types before embedding?', '{"key_points": [{"id": "KP1", "description": "Normalize heterogeneous document structures (PDF tables, JSON schemas, HTML, Markdown) into standardized textual representations.", "required": true, "acceptable_evidence": ["Technical keywords: data normalization, Markdown serialization, table linearization, JSON flattening, HTML sanitization, Docling.", "Explains converting diverse enterprise data sources into unified semantic Markdown: transforming tabular grid data into Markdown pipe tables or linearized key-value strings (`Feature: Value`), stripping HTML styling tags, and flattening nested JSON trees into human-readable property lists.", "Emphasizes that embedding models perform best on well-punctuated, coherent natural language syntax."]}, {"id": "KP2", "description": "Standardize domain-specific entities, abbreviations, dates, and measurement units across document corpora.", "required": true, "acceptable_evidence": ["Technical keywords: entity canonicalization, ISO 8601 dates, unit standardization (kW/kWh), synonym normalization, regex dictionary.", "Details domain normalization: converting heterogeneous date formats to ISO 8601 (`YYYY-MM-DD`), standardizing electrical measurement units (normalizing ''kilowatts'', ''kW'', ''k.w.'' to canonical ''kW''), and expanding critical domain abbreviations (e.g., ''HV'' to ''High-Voltage'', ''PA'' to ''Prior Authorization'').", "Explains how entity canonicalization ensures dense embeddings project related concepts into aligned vector neighborhoods."]}, {"id": "KP3", "description": "Inject contextual breadcrumb headers and hierarchical section metadata directly into chunk text bodies.", "required": true, "acceptable_evidence": ["Technical keywords: breadcrumb injection, contextual chunking, document hierarchy, title prefixing, semantic contextualization.", "Explains prefixing every text chunk with its hierarchical provenance: `[Document: 2024 EV Service Manual > Section: High-Voltage Battery > Subsection: Contactor Diagnostics]`, followed by the chunk body.", "Details how embedding this structural breadcrumb ensures isolated procedural sentences retain critical parent context during vector similarity scoring."]}], "critical_failures": ["Flattens multi-row complex tables into raw unspaced text strings, destroying column relationships and row semantic bindings.", "Passes raw HTML tags, CSS styling, and JavaScript boilerplate directly to embedding tokenizers.", "Chunks section text in isolation without document title or heading prefixes, leaving chunks without semantic anchors (e.g., ''Step 1: Disconnect'' without knowing what vehicle component is being serviced)."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What was the business problem your RAG system was solving, and how did it improve outcomes?', '{"key_points": [{"id": "KP1", "description": "Formulate the operational challenges of customer call centers: knowledge fragmentation, manual search latency, and answer inconsistency.", "required": true, "acceptable_evidence": ["Technical keywords: operational challenges, knowledge fragmentation, Average Handle Time (AHT 8-12m), First Call Resolution (FCR), manual search effort (40-60%).", "Details the concrete business problem from the Study Guides: support agents spend 40-60% of call time manually searching across fragmented repositories (vehicle service manuals, firmware release notes, warranty PDFs, technician notes).", "Highlights operational consequences: high Average Handle Time (8-12 minutes per call), low agent call capacity (60-80 calls/day), and a 10-15% error rate due to inconsistent interpretation of technical guidelines."]}, {"id": "KP2", "description": "Analyze why legacy keyword search systems (Elasticsearch) failed for complex diagnostic and policy inquiries.", "required": true, "acceptable_evidence": ["Technical keywords: Elasticsearch limitations, lack of semantic understanding, vocabulary mismatch, noisy recall, ungrounded search.", "Explains the failure of traditional keyword search: customers ask conceptual questions (''car won''t charge in cold weather'') while manuals describe technical procedures (''battery preconditioning and low-temperature thermal management''); Elasticsearch returns dozens of partially relevant PDFs requiring manual reading.", "Notes that keyword search cannot synthesize direct answers or verify logical entailment across multiple documents."]}, {"id": "KP3", "description": "Define business objectives and measurable ROI targets for the production RAG assistant.", "required": true, "acceptable_evidence": ["Technical keywords: business objectives, AHT reduction (30-40%), FCR improvement, CSAT targets, auditable traceability.", "Outlines core project objectives: (1) reduce Average Handle Time by 30-40% by delivering instant grounded answers within seconds, (2) improve First Call Resolution and Customer Satisfaction (CSAT > 4.5), and (3) enforce 100% auditable source citations traceable to official manuals to guarantee compliance and safety."]}], "critical_failures": ["Describes the business case purely as an AI novelty project without citing operational metrics like AHT, FCR, search overhead, or error rates.", "Fails to articulate why existing keyword search engines (Elasticsearch) fell short on semantic intent and vocabulary mismatch.", "Omits compliance, auditability, and safety risks associated with human support agents delivering incorrect technical advice."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What were your key contributions across different phases of the RAG system development lifecycle?', '{"key_points": [{"id": "KP1", "description": "Detail leadership and hands-on contributions during the initial Proof of Concept (POC) validation phase.", "required": true, "acceptable_evidence": ["Technical keywords: POC phase, technical lead, rapid prototyping, Streamlit, ChromaDB, stakeholder alignment, customer care leadership.", "Explains partnering with the Director of AI and Product Managers to scope and build the initial POC: implementing data ingestion for core service manuals, building a lightweight Streamlit interface backed by ChromaDB, and conducting validation sessions with senior call center agents and technicians.", "Highlights translating qualitative agent feedback into concrete technical requirements for Phase-1 approval."]}, {"id": "KP2", "description": "Demonstrate core architectural ownership during production engineering: hybrid retrieval, Milvus migration, and evaluation pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: production engineering, Milvus on EKS, hybrid BM25 + dense search, Reciprocal Rank Fusion, Cross-Encoder reranking, DeepEval.", "Details technical ownership during productionization: architecting the migration from ChromaDB to distributed Milvus, implementing hybrid search with RRF to eliminate domain code retrieval misses, and establishing automated Golden Dataset CI evaluation gates with DeepEval and RAGAS.", "Highlights guiding ML engineers and Data Scientists on chunking optimizations and vector indexing parameters."]}, {"id": "KP3", "description": "Drive cross-functional deployment, security governance, and operational observability in production.", "required": true, "acceptable_evidence": ["Technical keywords: cross-functional collaboration, DevOps / Platform teams, Helm / ArgoCD, Presidio PII redaction, Langfuse tracing, ROI impact.", "Details collaborating with DevOps to containerize FastAPI services and deploy via Helm on Amazon EKS, enforcing PII data privacy with Presidio, and configuring Langfuse distributed tracing.", "Connects technical delivery to business results: cutting call handle times, reducing agent ramp-up time, and delivering measurable ROI."]}], "critical_failures": ["Claims to have done everything in isolation without acknowledging cross-functional collaboration with DevOps, Product, and support stakeholders.", "Cannot articulate specific technical decisions owned versus tasks delegated or handled by third-party packages.", "Focuses purely on high-level management without demonstrating deep hands-on technical ownership of retrieval and evaluation pipelines."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'When you moved it to production on EKS, what was your strategy for dealing with model drift in the embedding space?', '{"key_points": [{"id": "KP1", "description": "Define embedding drift and differentiate between semantic distribution drift and query vocabulary drift.", "required": true, "acceptable_evidence": ["Technical keywords: embedding drift, semantic distribution shift, query concept drift, vocabulary drift, out-of-distribution (OOD) queries.", "Explains that embedding drift occurs when user query representations diverge geometrically from the indexed document vector manifold: caused by emerging customer terminology, newly released vehicle models/features not yet in corpus, or seasonal customer shift patterns.", "Contrasts document corpus updates with user query distribution shifts."]}, {"id": "KP2", "description": "Implement statistical distance metrics and dimensionality reduction to monitor embedding distributions over time.", "required": true, "acceptable_evidence": ["Technical keywords: Maximum Mean Discrepancy (MMD), Wasserstein distance, Population Stability Index (PSI), PCA / UMAP projections, centroid tracking.", "Details monitoring techniques: tracking the statistical drift of daily query embedding centroids against baseline centroids, computing Maximum Mean Discrepancy (MMD) or Wasserstein distance between sliding windows, and monitoring Population Stability Index (PSI) on top principal components.", "Explains using Evidently AI or custom monitoring jobs to trigger alerts when drift exceeds tolerance."]}, {"id": "KP3", "description": "Establish operational remediation protocols: zero-downtime corpus re-indexing and dual-model transitional routing.", "required": true, "acceptable_evidence": ["Technical keywords: corpus re-indexing, blue-green collection swap, dual embedding routing, retraining triggers, active learning.", "Details remediation runbooks: (1) harvest high-drift and low-confidence queries into an annotation queue, (2) update document corpus with latest technical service bulletins, and (3) if upgrading the embedding model itself, index into a parallel Milvus collection, validate calibration, and execute a zero-downtime collection alias swap.", "Notes that embedding models cannot be partially upgraded without re-indexing the entire corpus due to mismatched geometric spaces."]}], "critical_failures": ["Attempts to upgrade the query embedding model while querying documents indexed with an older or different embedding model, causing catastrophic retrieval collapse.", "Believes embedding vectors never drift because model weights are frozen, failing to recognize that user query distributions and real-world language shift dynamically.", "Lacks statistical distance metrics (MMD, Wasserstein, centroid tracking) to detect embedding distribution shifts in production."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'Which LLM did you use for response generation, and how did it integrate with your retrieval pipeline?', '{"key_points": [{"id": "KP1", "description": "Select generative models based on context window capacity, instruction-following adherence, and licensing governance.", "required": true, "acceptable_evidence": ["Technical keywords: LLM selection, Llama 3 70B, GPT-4o, Claude 3.5 Sonnet, instruction following, enterprise governance, open-weights vs proprietary APIs.", "Analyzes selection criteria: evaluated open-weights models (Llama-3-70B-Instruct hosted on AWS Bedrock/vLLM for strict data residency and fixed cost) versus proprietary APIs (GPT-4o / Claude 3.5 Sonnet for complex multi-hop reasoning).", "Emphasizes that RAG requires models with exceptional negative constraint adherence (refusing to answer when context is absent)."]}, {"id": "KP2", "description": "Enforce deterministic sampling parameters (temperature=0.0, top_p=1.0) to eliminate creative hallucination in factual synthesis.", "required": true, "acceptable_evidence": ["Technical keywords: temperature=0.0, greedy decoding, top_p=1.0, deterministic generation, factual consistency, hallucination suppression.", "Explains that while creative writing benefits from higher temperature (0.7-1.0), enterprise technical support and policy synthesis require greedy or near-greedy decoding (`temperature=0.0` or `0.1`, `top_p=1.0`).", "Details how greedy sampling forces the model to select the highest-probability factual tokens directly derived from the retrieved context."]}, {"id": "KP3", "description": "Structure context injection using strict XML/Markdown delimiters and explicit negative fallback instructions.", "required": true, "acceptable_evidence": ["Technical keywords: context injection, XML tagging (<context>, <query>), negative constraint prompt, citation requirement, system instructions.", "Details the prompt architecture: placing system constraints first, retrieved passages inside structured tags (`<retrieved_context>\\n[Doc 1]: ...\\n</retrieved_context>`), followed by explicit instructions: ''Answer strictly using the facts in <retrieved_context>. If the context does not contain the answer, reply: \\"Information not found in active documentation.\\" Do not speculate.''", "Explains how strict prompt sandboxing prevents prompt injection from malicious document text."]}], "critical_failures": ["Sets temperature to 0.7 or higher in factual enterprise customer support pipelines, inducing high hallucination rates and answer variability.", "Concatenates retrieved text naively without delimiters or negative fallback instructions, allowing the model to hallucinate from parametric memory when context is insufficient.", "Uses models known for weak instruction-following that ignore citation constraints or fabricate answers."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'Why did you transition from ChromaDB to Milvus, and what benefits did it provide in production?', '{"key_points": [{"id": "KP1", "description": "Identify architectural limitations of embedded vector databases (ChromaDB) that necessitated production migration.", "required": true, "acceptable_evidence": ["Technical keywords: ChromaDB limitations, SQLite/DuckDB backend, single-node embedded architecture, memory saturation, lack of distributed scaling, concurrency bottlenecks.", "Explains that while ChromaDB was excellent for rapid single-developer POC prototyping, it hit severe limitations under enterprise load: single-process file locks, lack of multi-replica horizontal read scaling, memory exhaustion as index grew past 500k chunks, and lack of enterprise RBAC/partition isolation.", "Details why an embedded engine cannot serve high-concurrency production microservices."]}, {"id": "KP2", "description": "Architect distributed Milvus on Kubernetes (Amazon EKS) with decoupled query, data, and index nodes.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus distributed architecture, Kubernetes (EKS), Query Nodes, Data Nodes, Index Nodes, MinIO/S3 object storage, Etcd coordination.", "Details Milvus production deployment: separating stateless Query Nodes (scaled via HPA to handle query QPS surges) from Data Nodes (streaming write ingestion via Pulsar/Kafka) and Index Nodes (building HNSW/IVF graphs in background).", "Explains persisting vector data in durable S3/MinIO object storage with Etcd managing cluster metadata."]}, {"id": "KP3", "description": "Quantify operational benefits achieved in production: throughput, latency consistency, and partition pruning.", "required": true, "acceptable_evidence": ["Technical keywords: high concurrency, QPS scaling, sub-20ms search latency, partition keys, zero-downtime rolling upgrades.", "Provides production metrics from the Study Guides: QPS capacity scaled from 15 QPS (ChromaDB choking on concurrent reads) to 500+ QPS with p95 search latency dropping to under 20ms in Milvus.", "Highlights enterprise features gained: physical partition pruning by model year/tenant and zero-downtime Kubernetes rolling deployments."]}], "critical_failures": ["Deploys single-node embedded ChromaDB in high-traffic multi-pod Kubernetes production, leading to database lock contention and crashing pods.", "Cannot explain the microservice components of Milvus (Query Nodes, Data Nodes, Index Nodes, Object Storage).", "Fails to identify the scalability, concurrency, and persistence differences between local embedded stores and distributed vector databases."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'Why is cosine similarity preferred over Euclidean distance in vector search, and how does sorting impact retrieval results?', '{"key_points": [{"id": "KP1", "description": "Deconstruct mathematical definitions of Cosine Similarity, Inner Product (IP), and Euclidean Distance (L2).", "required": true, "acceptable_evidence": ["Technical keywords: Cosine Similarity, Inner Product (Dot Product), Euclidean Distance (L2), vector magnitude, angle between vectors.", "Defines the mathematical formulations: (1) Cosine Similarity: $\\\\cos(\\\\theta) = \\\\frac{\\\\vec{u} \\\\cdot \\\\vec{v}}{\\\\|\\\\vec{u}\\\\|_2 \\\\|\\\\vec{v}\\\\|_2}$, measuring angular directional alignment $[-1, 1]$, (2) Euclidean Distance ($L_2$): $\\\\|\\\\vec{u} - \\\\vec{v}\\\\|_2 = \\\\sqrt{\\\\sum (u_i - v_i)^2}$, measuring geometric spatial distance $[0, \\\\infty)$, and (3) Inner Product: $\\\\vec{u} \\\\cdot \\\\vec{v} = \\\\sum u_i v_i$.", "Explains how magnitude affects each metric."]}, {"id": "KP2", "description": "Explain why Cosine Similarity / Inner Product is preferred over Euclidean Distance for text embeddings.", "required": true, "acceptable_evidence": ["Technical keywords: text length invariance, magnitude distortion, semantic direction, word count variation, unit hypersphere.", "Explains that text documents and user queries vary greatly in length: a short 10-word query and a 300-word paragraph covering the exact same concept produce embedding vectors pointing in the exact same direction, but with different vector lengths/magnitudes.", "Details how Euclidean distance penalizes length differences (ranking the short query far from the paragraph), whereas Cosine similarity focuses purely on semantic direction, making it length-invariant."]}, {"id": "KP3", "description": "Prove mathematical equivalence of Cosine Similarity and Inner Product under L2 unit normalization.", "required": true, "acceptable_evidence": ["Technical keywords: L2 normalization, unit vector (||v|| = 1), dot product speedup, hardware SIMD acceleration, sorting equivalence.", "Proves that when vectors are normalized to unit length ($\\\\|\\\\vec{u}\\\\| = 1, \\\\|\\\\vec{v}\\\\| = 1$): $\\\\cos(\\\\theta) = \\\\vec{u} \\\\cdot \\\\vec{v}$ and $\\\\|\\\\vec{u} - \\\\vec{v}\\\\|^2 = 2 - 2(\\\\vec{u} \\\\cdot \\\\vec{v})$.", "Explains why production vector databases (Milvus/FAISS) pre-normalize vectors to unit length and use Inner Product (IP) distance: computing pure dot products eliminates square root and division operations, maximizing hardware SIMD instruction throughput."]}], "critical_failures": ["Claims Euclidean distance is superior for text retrieval without recognizing that text length differences distort vector magnitude in $L_2$ space.", "Fails to recognize that Cosine Similarity and Dot Product are mathematically identical when vectors are $L_2$-normalized.", "Calculates cosine similarity dynamically in unnormalized loops rather than pre-normalizing vectors during ingestion for hardware-accelerated dot product search."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'Why is the ingestion pipeline manually triggered, and what would be required to convert it into a fully automated microservices-based system?', '{"key_points": [{"id": "KP1", "description": "Identify operational flaws and latency lag of manual, scheduled batch document ingestion pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: batch ingestion limitations, manual cron triggers, high knowledge staleness, bursty resource utilization, operational friction.", "Details operational problems with legacy batch pipelines: documents uploaded or modified during the day remain invisible to call center agents until nightly batch jobs run (hours of latency), large batch spikes overwhelm GPU embedding workers, and pipeline errors require manual engineering triage.", "Contrasts with real-time support demands where newly published firmware patches must be searchable immediately."]}, {"id": "KP2", "description": "Architect an event-driven ingestion microservice using S3 object notifications, Kafka message queues, and worker pools.", "required": true, "acceptable_evidence": ["Technical keywords: event-driven architecture, S3 Event Notifications, Apache Kafka / AWS SQS, Celery workers, decoupled microservices, idempotent consumer.", "Details the decoupled event-driven architecture: (1) S3 `ObjectCreated` event triggers a Kafka message, (2) Ingestion Controller consumes event and verifies file checksum, (3) Document Parser Worker pool extracts text/tables via Docling, (4) Embedding Worker pool generates vectors using GPU batches, and (5) Vector Indexer Worker updates Milvus.", "Explains how Kafka partitions and dead-letter queues (DLQs) provide resilience and backpressure control."]}, {"id": "KP3", "description": "Implement zero-downtime index updates and atomic document replacement in the live vector database.", "required": true, "acceptable_evidence": ["Technical keywords: zero-downtime ingestion, atomic upsert, soft deletes, collection alias, near-real-time index building.", "Explains real-time vector updating: incoming document revisions are indexed with deterministic `chunk_id`s, existing chunks for that document ID are atomically replaced or flagged with newer version timestamps, and index segments are built incrementally.", "Details ensuring live agent queries experience zero downtime, search lockouts, or inconsistent state during document processing."]}], "critical_failures": ["Proposes running heavy PDF parsing and embedding generation synchronously within user-facing API request threads.", "Lacks message queues (Kafka/SQS) or dead-letter queues, allowing transient worker crashes to permanently lose incoming document updates.", "Fails to handle document updates atomically, causing queries to return a mix of old and new chunk versions during ingestion."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain the difference between retrieval evaluation and generation evaluation, and the metrics used for each?', '{"key_points": [{"id": "KP1", "description": "Decouple RAG system evaluation into distinct, orthogonal evaluation planes: Retrieval Quality and Generation Quality.", "required": true, "acceptable_evidence": ["Technical keywords: decoupled evaluation, two-plane evaluation, retrieval plane vs generation plane, error isolation, modular benchmarking.", "Explains why end-to-end evaluation alone is insufficient: an incorrect final answer could stem from (a) the retriever failing to find the relevant manual section, or (b) the LLM hallucinating despite receiving the exact correct section.", "Details separating evaluation: measuring the retriever strictly against gold document chunks, and measuring the generator strictly against retrieved context and reference answers."]}, {"id": "KP2", "description": "Define and measure specialized Retrieval Quality metrics: Contextual Recall, Contextual Precision, and MRR.", "required": true, "acceptable_evidence": ["Technical keywords: Contextual Recall, Contextual Precision, Mean Reciprocal Rank (MRR@10), NDCG, gold chunk IDs.", "Details retrieval evaluation mechanics: (1) **Contextual Recall**: did retrieved chunks contain all factual information needed to answer the query? ($|\\\\text{gold facts in context}| / |\\\\text{gold facts required}|$), (2) **Contextual Precision**: were relevant chunks placed at the top of the ranked list? ($(\\\\text{Rank of first relevant chunk})^{-1}$ for MRR), and (3) **Hit Rate@K**.", "Notes that retrieval evaluation requires no generative LLM call when evaluated against gold chunk IDs."]}, {"id": "KP3", "description": "Define and measure specialized Generation Quality metrics: Faithfulness (Groundedness) and Answer Relevance.", "required": true, "acceptable_evidence": ["Technical keywords: Faithfulness / Groundedness, Answer Relevance, hallucination rate, semantic similarity, RAGAS / DeepEval.", "Details generation evaluation mechanics: (1) **Faithfulness**: what percentage of claims in the generated response are entailed by the retrieved context? ($|\\\\text{faithful claims}| / |\\\\text{total claims}|$), and (2) **Answer Relevance**: does the response directly address the user''s question without extraneous digressions?", "Explains using RAGAS/DeepEval test harnesses to compute these metrics automatically across Golden Datasets."]}, {"id": "KP4", "description": "Construct a diagnostic root-cause quadrant matrix to guide targeted engineering remediation.", "required": false, "acceptable_evidence": ["Technical keywords: diagnostic quadrant matrix, high recall + low faithfulness (prompting/model flaw), low recall + high faithfulness (retrieval/chunking flaw).", "Presents the diagnostic 2x2 matrix: (1) **Low Retrieval Recall + High Faithfulness**: model is behaving conservatively but retrieval failed (fix: adjust chunk size, add BM25 hybrid search, tune HNSW parameters), (2) **High Retrieval Recall + Low Faithfulness**: retriever succeeded but model hallucinated (fix: set `temperature=0`, strengthen negative prompt constraints, switch to stronger LLM)."]}], "critical_failures": ["Evaluates RAG systems solely by checking final answer text using surface metrics like BLEU/ROUGE without isolating retrieval from generation.", "Cannot diagnose whether an incorrect answer was caused by retrieval failure (missing context) or generation failure (LLM hallucination).", "Conflates Faithfulness (factual alignment with retrieved context) with Answer Correctness (factual alignment with real-world truth)."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'Can you walk me through a SQL query for latest conversation that had RAG tool call failures in NoSQL DB?', '{"key_points": [{"id": "KP1", "description": "Author JSONB path queries in PostgreSQL to extract the latest conversation session with agent tool execution failures.", "required": true, "acceptable_evidence": ["Technical keywords: PostgreSQL JSONB, jsonb_path_query, ->, ->>, jsonb_array_elements, WHERE metadata @>, ORDER BY created_at DESC LIMIT 1.", "Details the query structure in PostgreSQL: querying `agent_executions` where `tool_calls` JSONB array contains an object with `status = ''FAILED''`: `SELECT session_id, created_at, execution_data FROM agent_traces WHERE execution_data->''tool_calls'' @> ''[{\\"status\\": \\"FAILED\\"}]'' ORDER BY created_at DESC LIMIT 1;`.", "Explains using the containment operator `@>` with GIN indexing for fast execution."]}, {"id": "KP2", "description": "Construct equivalent document queries in MongoDB using aggregation pipelines and `$elemMatch`.", "required": true, "acceptable_evidence": ["Technical keywords: MongoDB, $elemMatch, db.conversations.find(), aggregation pipeline, sort({created_at: -1}), limit(1).", "Details MongoDB document querying: `db.agent_sessions.find({ ''tools_executed'': { $elemMatch: { ''status'': ''FAILURE'', ''tool_name'': ''vector_retrieval'' } } }).sort({ ''timestamp'': -1 }).limit(1)`.", "Explains how `$elemMatch` inspects sub-document elements within arrays to locate exact tool failure states."]}, {"id": "KP3", "description": "Design indexing strategies on semi-structured JSON columns (GIN / Multi-Key Indexes) to support low-latency error auditing.", "required": true, "acceptable_evidence": ["Technical keywords: GIN index (jsonb_path_ops), multi-key index, compound index (tenant_id, created_at), audit table partitioning.", "Explains creating a Generalized Inverted Index (GIN) in PostgreSQL (`CREATE INDEX idx_tool_failures ON agent_traces USING gin ((execution_data->''tool_calls'') jsonb_path_ops);`), reducing audit query latency from full-table scans to single-digit milliseconds.", "Details partitioning trace tables by date to optimize telemetry storage."]}], "critical_failures": ["Writes queries that load all unstructured JSON strings into Python memory to search for errors using regular expressions rather than database-native JSONB/NoSQL queries.", "Queries unindexed JSONB columns across millions of trace records in production, inducing severe CPU spikes.", "Cannot write valid syntax for querying nested JSON arrays in either PostgreSQL JSONB or MongoDB."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'Describe the RAG data ingestion pipeline, detailing how you pre-processed unstructured data (including tables and scanned documents using OCR/Docling), handled PII redaction, and managed overlapping chunks.', '{"key_points": [{"id": "KP1", "description": "Implement layout-aware document parsing using Docling to preserve table structure, reading order, and document hierarchy.", "required": true, "acceptable_evidence": ["Technical keywords: Docling, layout-aware parsing, table extraction, reading order, document hierarchy, Markdown conversion.", "Explains using Docling (or LlamaParse / Unstructured) to parse complex PDFs: utilizing computer vision layout models to identify bounding boxes for headers, multi-column text, tables, and callout blocks, reconstructing reading order rather than naive left-to-right character streams.", "Details converting complex tabular data into structured Markdown pipe tables or JSON arrays, preserving header-to-cell semantic relationships."]}, {"id": "KP2", "description": "Apply optical character recognition (OCR) and layout correction on scanned technician reports and legacy forms.", "required": true, "acceptable_evidence": ["Technical keywords: OCR (AWS Textract / Tesseract), image preprocessing, scanned documents, deskewing, binarization, technician notes.", "Details handling scanned historical documents: applying image preprocessing (deskewing, contrast normalization), executing OCR via AWS Textract or Tesseract, and merging extracted text with structural document metadata.", "Explains filtering OCR artifact noise before downstream chunking."]}, {"id": "KP3", "description": "Execute deterministic PII and PHI scrubbing with Microsoft Presidio before storing chunks in vector storage.", "required": true, "acceptable_evidence": ["Technical keywords: Microsoft Presidio Analyzer & Anonymizer, PII scrubbing, HIPAA compliance, custom recognizers, token replacement.", "Details the scrubbing pipeline: document text is processed by Presidio Analyzer to detect sensitive entities (SSNs, names, phone numbers, member IDs), followed by Presidio Anonymizer replacing entities with typed placeholders (`<SSN>`, `<PHONE>`).", "Explains custom regex recognizers for domain identifiers (e.g., VIN numbers or Medicaid claim IDs)."]}, {"id": "KP4", "description": "Enforce table integrity during chunking to prevent splitting related rows and column headers.", "required": true, "acceptable_evidence": ["Technical keywords: atomic table chunking, table row preservation, header repetition, semantic chunk boundaries.", "Explains keeping small tables intact as atomic chunks, and for large tables, repeating column header rows across chunks so that every chunk maintains complete semantic context."]}], "critical_failures": ["Uses naive text extractors (like PyPDF2) that scramble multi-column layouts and turn tabular rows into meaningless unstructured strings.", "Omits PII redaction during ingestion, persisting sensitive member or customer data into shared vector stores and embedding vectors.", "Splits tables arbitrarily in the middle of data rows without repeating table headers, destroying data interpretation."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'Describe your chunking strategy, including how you handled complex unstructured data like car manuals containing tables and images, and why you moved from fixed-length to a hybrid approach combining semantic chunking and overlapping windows.', '{"key_points": [{"id": "KP1", "description": "Analyze unique technical complexities in automotive documentation: wiring schematics, diagnostic decision trees, and multi-tier tables.", "required": true, "acceptable_evidence": ["Technical keywords: EV service manuals, high-voltage schematics, diagnostic trees, DTC troubleshooting tables, multi-column technical PDFs.", "Details the technical nature of vehicle manuals from the Study Guides: 500+ page PDFs containing dense electrical schematics, conditional branching flowcharts (If DTC P0A80 is present -> Check fuse 14 -> If voltage < 12V), and specification tables.", "Explains why standard naive fixed-size chunking (e.g., 500 characters) catastrophically fragments diagnostic workflows and separates error conditions from their corrective actions."]}, {"id": "KP2", "description": "Transition from rigid fixed-length chunking to hybrid structure-aware semantic chunking with overlapping windows.", "required": true, "acceptable_evidence": ["Technical keywords: fixed-length failure, structure-aware chunking, hybrid approach, sliding window overlap (15-20%), section boundaries.", "Explains the architectural evolution: replacing arbitrary character splits with layout-aware structural chunking: respecting document sections, keeping procedural troubleshooting steps grouped together, and applying a 15-20% sliding token overlap to preserve transitional logic across page breaks.", "Details how overlapping windows ensure diagnostic condition sentences remain bound to their target resolution steps."]}, {"id": "KP3", "description": "Extract and linearize visual diagrams, wiring schematics, and tabular specifications into searchable textual representations.", "required": true, "acceptable_evidence": ["Technical keywords: schematic linearization, component pinout mapping, Docling table extraction, OCR diagram annotation, image metadata.", "Details converting visual schematics: parsing wiring diagrams into structured component-pinout-wire text descriptions (`Relay K1 -> Pin 4 -> Contactor Coil (+) -> 12V Auxiliary Supply`), and converting diagnostic flowcharts into step-by-step nested Markdown checklists.", "Mentions associating extracted component images with their textual chunks via S3 image URLs in metadata."]}], "critical_failures": ["Applies naive 200-character fixed chunking to automotive manuals, splitting diagnostic steps and error codes in half.", "Discards tables and electrical schematics during PDF parsing as ''unparseable images'', leaving the RAG system unable to answer wiring or specification questions.", "Fails to maintain hierarchical manual metadata (Vehicle Model, Model Year, System, Subsystem) on chunks."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'Did you also have confidence scoring in your hallucination mitigation? How and at which layer did you include this?', '{"key_points": [{"id": "KP1", "description": "Architect multi-layer confidence scoring across the retrieval, reranking, and generation stages of RAG.", "required": true, "acceptable_evidence": ["Technical keywords: multi-layer confidence scoring, retrieval confidence, reranker probability, generation confidence, defense-in-depth.", "Explains that hallucination prevention requires confidence gates at multiple architectural layers: (1) Vector Retrieval layer (dense cosine similarity distance), (2) Reranking layer (Cross-Encoder calibrated sigmoid probability), and (3) Generation layer (LLM token log probabilities / self-consistency agreement).", "Emphasizes that relying on a single end-to-end score fails to catch early pipeline degradation."]}, {"id": "KP2", "description": "Establish quantitative gating thresholds on Cross-Encoder reranker outputs to trigger fallback actions.", "required": true, "acceptable_evidence": ["Technical keywords: Cross-Encoder score threshold (e.g., 0.65), sigmoid probability, retrieval sufficiency gate, fallback trigger.", "Details the reranking quality gate: after Cross-Encoder reranking (`bge-reranker-base`), if the top candidate score falls below a calibrated threshold (e.g., $Score < 0.65$), the system flags the retrieval as ''insufficient'' and bypasses generation.", "Explains how this prevents feeding weak, marginally related passages into the LLM, which is the primary cause of extrinsic hallucinations."]}, {"id": "KP3", "description": "Implement automated fallback handling: admitting lack of documentation and triggering human specialist escalation.", "required": true, "acceptable_evidence": ["Technical keywords: graceful fallback, deterministic refusal, Human-in-the-Loop escalation, out-of-scope handling, call center transfer.", "Details fallback execution: returning a safe, deterministic system response (''The requested procedure is not documented in the active vehicle service manual. Please escalate to Field Technical Support.''), and presenting the human agent with an escalation button.", "Emphasizes that in safety-critical domains (EV high-voltage batteries), admitting lack of context is infinitely safer than generating plausible hallucinated advice."]}], "critical_failures": ["Feeds low-scoring retrieval results (e.g., cosine similarity < 0.40) to the LLM and expects the prompt to magically prevent hallucinations.", "Lacks quantitative confidence thresholds, treating all retrieved documents as equally authoritative.", "Allows the system to guess or fabricate answers when retrieved documents are insufficient rather than executing a deterministic fallback refusal."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'Did you implement any strategies for multi-hop reasoning or cross-repository retrieval, and what approach did you take?', '{"key_points": [{"id": "KP1", "description": "Analyze limitations of single-shot vector retrieval on multi-hop questions requiring evidence from multiple disparate documents.", "required": true, "acceptable_evidence": ["Technical keywords: multi-hop reasoning, cross-document dependencies, single-shot retrieval limits, bridge entities, knowledge fragmentation.", "Explains that complex enterprise questions (e.g., ''If high-voltage battery diagnostic code P0A80 is active, what warranty claim policy applies in California for a 2023 model?'') cannot be answered by a single chunk: the diagnostic code resides in a service manual, vehicle warranty limits reside in a warranty booklet, and California emissions rules reside in state regulatory guidelines.", "Details why single-shot vector search only finds chunks related to one aspect of the question."]}, {"id": "KP2", "description": "Implement iterative multi-hop retrieval using sub-query decomposition and intermediate reasoning hops (ReAct / LangGraph).", "required": true, "acceptable_evidence": ["Technical keywords: iterative retrieval, sub-query decomposition, ReAct loop, LangGraph state machine, intermediate entity extraction.", "Details the multi-hop execution flow: (1) Hop 1: retrieve diagnostic manual chunk for code P0A80 -> extract component ''Traction Battery Pack Assembly'', (2) Hop 2: generate sub-query for ''Traction Battery warranty duration 2023 EV'' -> retrieve warranty guide -> extract ''8 years / 100k miles (10 years / 150k miles in CARB states)'', (3) Hop 3: check California CARB status.", "Explains how LangGraph maintains state across sequential retrieval nodes."]}, {"id": "KP3", "description": "Traverse cross-repository graph relationships in Neo4j to link disparate knowledge domains deterministically.", "required": true, "acceptable_evidence": ["Technical keywords: Neo4j graph traversal, Cypher relationship querying, multi-repository linkage, PART_OF, COVERED_BY, REGULATED_BY.", "Explains augmenting iterative search with knowledge graph traversals: querying explicit cross-domain relationships (`(Error:P0A80)-[:INDICATES]->(Comp:HV_Battery)-[:COVERED_BY]->(Warranty:CARB_Warranty)`), pulling chunk IDs directly from graph node properties.", "Demonstrates how graph traversal resolves multi-hop connections with 100% precision without relying on multiple LLM reasoning hops."]}], "critical_failures": ["Attempts to resolve complex multi-hop cross-repository queries using a single basic vector search, returning incomplete answers that miss secondary policy conditions.", "Implements iterative loops without state bounds or termination conditions, resulting in infinite retrieval loops.", "Fails to synthesize intermediate evidence across retrieval hops, losing context from earlier documents."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'Explain to me what LangFuse is and how you can use it in the best possible way in your RAG.', '{"key_points": [{"id": "KP1", "description": "Integrate Langfuse SDK into the RAG pipeline to capture hierarchical execution traces, spans, and metadata.", "required": true, "acceptable_evidence": ["Technical keywords: Langfuse, OpenTelemetry, traces and spans, @observe decorator, async background telemetry, session tracking.", "Explains instrumenting FastAPI microservices and LangChain/LangGraph pipelines with Langfuse SDK: creating parent traces per user request with nested child spans for query preprocessing, embedding generation, Milvus vector search, Cross-Encoder reranking, and LLM streaming generation.", "Details passing metadata (`user_id`, `session_id`, `tenant_id`, `model_name`) to enable multi-dimensional trace filtering."]}, {"id": "KP2", "description": "Profile latency bottlenecks, token consumption, and dollar costs across foundation models and pipeline stages.", "required": true, "acceptable_evidence": ["Technical keywords: latency profiling, time-to-first-token (TTFT), token usage (prompt vs completion), dollar cost tracking, p95/p99 breakdown.", "Details operational observability in Langfuse: decomposing total response latency (e.g., 2.1s total = 45ms embedding + 35ms Milvus search + 40ms reranker + 1.2s LLM generation), monitoring prompt/completion token consumption, and calculating live dollar cost per query across models (Claude 3.5 vs Llama 3 on Bedrock).", "Explains using cost dashboards to optimize prompt token budgets."]}, {"id": "KP3", "description": "Harvest production failures, user feedback, and low-confidence traces into CI/CD Golden Datasets.", "required": true, "acceptable_evidence": ["Technical keywords: failure harvesting, thumbs up / thumbs down, user feedback API, score tagging, Golden Dataset curation, active learning.", "Explains logging user feedback (thumbs down, agent corrections) and automated score tags (e.g., `faithfulness < 0.70`, `retrieval_miss`) via Langfuse Scores API.", "Details the active learning workflow: exporting flagged low-quality traces from Langfuse directly into the developer evaluation repository to expand the versioned Golden Dataset and prevent regressions."]}], "critical_failures": ["Logs verbose production traces and prompts synchronously in the critical API request path, adding significant latency overhead to user calls.", "Logs unredacted customer PII/PHI payloads into Langfuse dashboards, violating data security standards.", "Treats Langfuse merely as a read-only logging viewer without utilizing its scoring, feedback tracking, or failure harvesting capabilities for active learning."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'Given a faulty similarity-based retrieval implementation, how would you identify and fix issues related to incorrect similarity calculation and sorting logic?', '{"key_points": [{"id": "KP1", "description": "Identify mathematical errors in similarity calculation: omitting L2 normalization when computing inner products as cosine similarity.", "required": true, "acceptable_evidence": ["Technical keywords: missing L2 normalization, dot product vs cosine similarity, vector magnitude bias, norm calculation, np.linalg.norm.", "Diagnoses the root cause: code computes dot product $\\\\vec{u} \\\\cdot \\\\vec{v}$ but treats it as cosine similarity without dividing by norms $\\\\|\\\\vec{u}\\\\|_2 \\\\|\\\\vec{v}\\\\|_2$. As a result, long chunks with larger token counts and higher vector norms receive artificially inflated scores, dominating search results regardless of relevance.", "Details fixing by either explicitly dividing by norms or pre-normalizing all vectors to unit length: `v_norm = v / np.linalg.norm(v, axis=1, keepdims=True)`."]}, {"id": "KP2", "description": "Detect sorting order inversions between similarity metrics (descending) and distance metrics (ascending).", "required": true, "acceptable_evidence": ["Technical keywords: sorting inversion, argsort ascending vs descending, cosine similarity (reverse=True), Euclidean distance (reverse=False), top-k error.", "Diagnoses sorting bugs: similarity metrics (Cosine, Dot Product) require descending sort (higher is closer, `scores.argsort()[::-1]`), whereas distance metrics (Euclidean, Manhattan) require ascending sort (lower is closer).", "Explains that using default `np.argsort()` on cosine similarities incorrectly returns the most dissimilar, irrelevant documents in the corpus."]}, {"id": "KP3", "description": "Fix numerical instability: floating-point precision clamping and zero-division protection.", "required": true, "acceptable_evidence": ["Technical keywords: numerical instability, division by zero (eps=1e-12), floating point drift, np.clip(-1.0, 1.0), NaN propagation.", "Details handling edge cases: (1) adding a small epsilon (`eps = 1e-12`) to denominators to prevent division by zero on zero-padded vectors, and (2) clamping cosine values to `[-1.0, 1.0]` using `np.clip()` to prevent out-of-range floats from triggering `NaN`s in downstream trigonometric math or scoring thresholds.", "Explains unit testing similarity calculations with known orthogonal and identical vector fixtures."]}], "critical_failures": ["Cannot identify why unnormalized dot product produces length-biased retrieval rankings.", "Sorts cosine similarity scores in ascending order, passing the least relevant chunks to the LLM.", "Omits zero-division protection or float clamping, causing `NaN` propagation that crashes vector search endpoints."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did project timelines vary across different phases such as RAG implementation, retrieval improvements, and agent development?', '{"key_points": [{"id": "KP1", "description": "Structure multi-phase delivery milestones: Phase 0 POC (3-4 weeks), Phase 1 Enterprise RAG (8-10 weeks), and Phase 2 Agentic Systems (12+ weeks).", "required": true, "acceptable_evidence": ["Technical keywords: project scoping, phased roadmap, POC (3-4 weeks), Phase 1 Production RAG (8-10 weeks), Phase 2 Multi-Agent (12+ weeks), milestone gates.", "Details realistic timeline allocation based on the Study Guides: (1) **Phase 0 POC (4 weeks)**: ingest 50 sample manuals, deploy ChromaDB + Streamlit prototype, conduct agent feedback validation, (2) **Phase 1 Production RAG (10 weeks)**: migrate to Milvus on EKS, build hybrid BM25 search, Cross-Encoder reranking, Presidio PII redaction, Golden Dataset CI gates, and (3) **Phase 2 Agentic Expansion (12 weeks)**: LangGraph state machine, Diagnostic Retrieval Agent, tool integrations.", "Explains establishing quantitative exit criteria for each phase."]}, {"id": "KP2", "description": "Manage resource allocation across data engineering, modeling, infrastructure, and validation workstreams.", "required": true, "acceptable_evidence": ["Technical keywords: workstream allocation, data engineering (40%), ML/retrieval tuning (25%), platform/EKS (20%), SME validation (15%), sprint planning.", "Explains balancing team efforts: data engineering and PDF layout parsing dominate the initial 40% of sprint capacity; retrieval tuning and reranking take 25%; cloud infrastructure and GitOps deployment take 20%; and continuous domain SME validation takes 15%.", "Highlights running parallel tracks to prevent modeling work from blocking on infrastructure provisioning."]}, {"id": "KP3", "description": "Mitigate project risks: scope creep, unstructured data parsing bottlenecks, and stakeholder alignment.", "required": true, "acceptable_evidence": ["Technical keywords: risk mitigation, scope creep, OCR/table parsing risks, buffer allocation, bi-weekly stakeholder reviews, AHT tracking.", "Details risk mitigation strategies: budgeting extra buffer for complex table parsing (which frequently underperforms in initial tests), defining strict MVP boundaries (excluding nice-to-have features like multilingual/multimodal until Phase 2), and holding bi-weekly demonstrations with Customer Care leadership to maintain alignment.", "Demonstrates mature engineering project governance."]}], "critical_failures": ["Promises full enterprise production deployment with agentic tools in 2 weeks, demonstrating unrealistic scoping and lack of enterprise engineering experience.", "Allocates 90% of project time to prompt engineering and LLM selection while ignoring the massive data engineering, parsing, and infrastructure requirements.", "Operates without phased milestones, MVP boundaries, or domain stakeholder validation gates."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did you clean, preprocess, and prepare large volumes of enterprise unstructured data for a production RAG system?', '{"key_points": [{"id": "KP1", "description": "Design unified multi-format ingestion connectors for enterprise document sources (PDFs, Confluence, SharePoint, HTML, APIs).", "required": true, "acceptable_evidence": ["Technical keywords: multi-format connectors, SharePoint API, Confluence REST API, S3 document lake, Firecrawl / web scraping, Apache Tika.", "Details building automated source extractors: pulling internal technical wikis via Confluence REST API, legacy policy repositories via SharePoint connectors, web portals via Firecrawl, and raw technical manuals from S3 buckets.", "Explains standardizing diverse incoming formats into clean UTF-8 text and structured JSON metadata."]}, {"id": "KP2", "description": "Execute multi-stage text cleaning, structural hierarchy preservation, and table extraction.", "required": true, "acceptable_evidence": ["Technical keywords: Docling layout analysis, Markdown conversion, table linearization, boilerplate removal, unicode normalization.", "Details preprocessing stages: (1) normalize Unicode encoding and whitespace, (2) strip repeating page headers, footers, and copyright disclaimers, (3) preserve H1-H4 heading hierarchy to maintain parent section context, and (4) extract complex multi-row tables into Markdown pipe tables.", "Highlights how structural preservation prevents table cells from blurring into unstructured sentences."]}, {"id": "KP3", "description": "Orchestrate asynchronous batch and streaming ingestion workflows using distributed message queues and S3 versioning.", "required": true, "acceptable_evidence": ["Technical keywords: Celery / Kafka, S3 versioning, distributed worker pool, backpressure management, Dead Letter Queue (DLQ).", "Explains distributed processing: incoming files are written to versioned S3 buckets, triggering Kafka/SQS events consumed by autoscaling Celery worker pods on Amazon EKS.", "Details using Dead Letter Queues (DLQs) to isolate corrupted or password-protected PDFs without stalling the overall ingestion queue."]}], "critical_failures": ["Treats all documents as plain raw text, stripping headings, sections, and tables during preprocessing.", "Processes multi-gigabyte document batches synchronously on a single web server thread, causing out-of-memory crashes and timeouts.", "Omits deduplication and structural validation, storing corrupt files and noisy boilerplates in the vector index."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'HARD', 'SPECIFIC', 120, 'How did you combine RAG and fine-tuning in a single system, and what trade-offs did you consider?', '{"key_points": [{"id": "KP1", "description": "Architect a symbiotic hybrid system combining Parameter-Efficient Fine-Tuning (PEFT/LoRA) with dynamic RAG retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid RAG-PEFT, LoRA / QLoRA, domain adaptation, style and syntax alignment, dynamic knowledge grounding.", "Explains the division of responsibilities: fine-tuning teaches the model *how* to reason and format (domain syntax, professional call center tone, structured JSON schemas, medical terminology), while RAG supplies *what* to know (the live, changing vehicle manuals, active Medicaid rules, and exact policy text).", "Overcomes the limitations of using either approach alone."]}, {"id": "KP2", "description": "Fine-tune foundation models to adhere to strict context grounding and reduce ungrounded hallucination tendencies.", "required": true, "acceptable_evidence": ["Technical keywords: context-grounding fine-tuning, rejection training, citation generation, synthetic training pairs, Llama-3 LoRA.", "Details fine-tuning objectives: training an open-weights model (e.g., Llama-3-8B) on paired examples of `[Context, Question] -> [Grounded Answer + Citations]`, including adversarial ''unanswerable'' questions where the model is rewarded for explicitly generating refusal statements (''Information not found in context'').", "Details how grounding fine-tuning dramatically reduces intrinsic hallucination rates compared to off-the-shelf base models."]}, {"id": "KP3", "description": "Analyze operational, compute, and lifecycle maintenance trade-offs of the hybrid architecture.", "required": true, "acceptable_evidence": ["Technical keywords: operational complexity, training compute (GPUs), MLflow model registry, vector store decoupled updates, deployment cost.", "Analyzes lifecycle trade-offs: the fine-tuned LoRA weights change infrequently (quarterly or biannually when formatting standards evolve) and are tracked via MLflow Model Registry; the RAG vector database updates continuously (daily or hourly as service bulletins arrive).", "Demonstrates how this hybrid decoupling provides high formatting fidelity without continuous model retraining costs."]}], "critical_failures": ["Fine-tunes the model on dynamic factual data that changes weekly, forcing constant expensive retraining cycles.", "Claims fine-tuning eliminates the need for vector retrieval or external knowledge bases in enterprise policy workflows.", "Fails to articulate the distinct roles of fine-tuning (style, format, task behavior) versus RAG (live factual evidence and verifiable citations)."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How did you conduct A/B testing to compare different retrievers, and what insights did you gain from the results?', '{"key_points": [{"id": "KP1", "description": "Establish a dual-stage evaluation methodology combining offline replay benchmarking with online canary/traffic-split A/B testing.", "required": true, "acceptable_evidence": ["Technical keywords: A/B testing, traffic split, canary deployment, offline replay, golden test set, statistical significance, p-value.", "Explains that new retrievers (e.g., hybrid BM25 + dense vs. dense-only) are first calibrated offline against a golden query-document test set, before running live 50/50 or 90/10 traffic splits via Envoy/Kong API gateway routing.", "Details using paired t-tests or Mann-Whitney U tests to ensure observed differences in user metrics are statistically significant."]}, {"id": "KP2", "description": "Define online proxy engagement metrics and ground-truth retrieval correlation signals for comparative evaluation.", "required": true, "acceptable_evidence": ["Technical keywords: click-through rate (CTR), citation click rate, answer copy rate, thumbs-up/thumbs-down, session duration, abandonment rate.", "Tracks operational and user feedback signals per variant: chunk citation clicks, thumbs up/down, user reformulations within 30 seconds (indicating poor retrieval), and session resolution rates.", "Correlates live user behavior with offline NDCG@10 and Recall@10 improvements."]}, {"id": "KP3", "description": "Quantify end-to-end operational trade-offs including p95/p99 query latency, infrastructure costs, and resource consumption across variants.", "required": true, "acceptable_evidence": ["Technical keywords: latency budget, p95/p99 latency, compute overhead, embedding inference cost, vector DB QPS, trade-off analysis.", "Measures whether an advanced retriever (e.g., introducing ColBERT or Cross-Encoder reranking) justifies an extra 80-150ms p95 latency and additional GPU memory footprint.", "Establishes automated rollback triggers if the candidate retriever exceeds latency budgets or increases error rates."]}], "critical_failures": ["Advocates rolling out uncalibrated retrievers straight to 100% production traffic without offline golden dataset validation or traffic splitting.", "Measures retriever quality purely by LLM output length or subjective developer impressions rather than quantitative user engagement and ranking metrics.", "Ignores latency, QPS throughput, and server compute costs when evaluating candidate retrieval algorithms."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How did you construct and use a ground truth or golden dataset to evaluate retrieval and response quality?', '{"key_points": [{"id": "KP1", "description": "Construct a stratified golden evaluation dataset sampling real user queries, edge cases, multi-hop reasoning, and out-of-domain scenarios.", "required": true, "acceptable_evidence": ["Technical keywords: golden dataset, stratified sampling, ground truth, query taxonomy, out-of-domain, edge cases, multi-hop queries.", "Partitions evaluation queries into representative strata: single-fact lookup (40%), complex multi-chunk synthesis (30%), ambiguous/unanswerable queries (15%), and adversarial/jailbreak queries (15%).", "Ensures production log queries are anonymized, deduplicated, and reviewed by domain experts (e.g., EV technicians or policy specialists)."]}, {"id": "KP2", "description": "Employ LLM-assisted synthetic dataset generation (Ragas, G-Eval) with human-in-the-loop audit and verification flywheels.", "required": true, "acceptable_evidence": ["Technical keywords: Ragas, synthetic data generation, query synthesis, human verification, question-context-answer triplets.", "Uses frontier models to generate synthetic `(query, relevant_chunk_ids, expected_answer)` triplets from raw documentation corpus using evolution prompts (reasoning, conditioning, multi-context).", "Domain matter experts filter and validate synthetic triplets to eliminate synthetic hallucinations from contaminating the benchmark."]}, {"id": "KP3", "description": "Establish continuous regression test suites and version-controlled golden sets integrated into git CI/CD pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: DVC, git-LFS, versioned benchmark, regression suite, CI/CD gate, non-regression threshold.", "Stores golden benchmark triplets in version-controlled repositories (e.g., DVC or HuggingFace Datasets) tied to specific release tags.", "Runs automated regression tests on every prompt, chunking, or embedding model change to prevent regressions in MRR or faithfulness."]}], "critical_failures": ["Relies exclusively on 10-20 ad-hoc developer queries typed directly into a chat playground to evaluate production RAG performance.", "Uses fully unverified synthetic queries generated by LLMs without expert verification or filtering of erroneous ground truths.", "Fails to include unanswerable and out-of-domain test queries to measure system rejection and fallback behavior."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Containers & Orchestration', 'HARD', 'SPECIFIC', 120, 'How did you deploy your RAG system using FastAPI, React, and AWS EKS, and what were the key deployment considerations?', '{"key_points": [{"id": "KP1", "description": "Architect containerized microservices separating the React frontend (CloudFront/S3) from asynchronous FastAPI backend pods on Amazon EKS.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon EKS, FastAPI, uvicorn, async/await, CloudFront, S3, Docker, Helm, multi-stage builds.", "Deploys containerized FastAPI services running with high-performance ASGI workers (uvicorn), decoupled from static React single-page applications hosted on S3 and distributed via CloudFront CDN.", "Packages Kubernetes manifests into versioned Helm charts specifying deployments, services, ingress controllers (AWS Load Balancer Controller), and ConfigMaps."]}, {"id": "KP2", "description": "Implement robust Horizontal Pod Autoscaler (HPA) policies based on custom CPU, memory, and HTTP concurrency/latency metrics.", "required": true, "acceptable_evidence": ["Technical keywords: Horizontal Pod Autoscaler (HPA), metrics-server, Prometheus Adapter, custom metrics, concurrency limits, pod resource limits.", "Configures HPA targeting both average CPU utilization (e.g., 70%) and Prometheus custom metrics such as active HTTP connections or request queue depth.", "Sets explicit container `resources.requests` and `resources.limits` to prevent noisy neighbors and avoid Out-Of-Memory (OOMKilled) pod terminations during bursty embedding inference."]}, {"id": "KP3", "description": "Design resilient networking, liveness/readiness probes, and rolling zero-downtime deployment strategies.", "required": true, "acceptable_evidence": ["Technical keywords: livenessProbe, readinessProbe, rolling update, maxSurge, maxUnavailable, pod disruption budget (PDB).", "Configures readiness probes checking upstream database and vector index connectivity before routing ingress traffic to newly spun pods.", "Employs rolling deployment strategies (`maxSurge: 25%`, `maxUnavailable: 0`) and PodDisruptionBudgets (PDB) to ensure seamless zero-downtime updates during production releases."]}], "critical_failures": ["Deploys synchronous, blocking WSGI applications that serialize slow LLM inference requests, crippling pod throughput.", "Omits readiness and liveness probes, allowing Kubernetes to route client traffic to uninitialized pods loading multi-gigabyte models.", "Deploys raw unversioned YAML manifests directly with `kubectl apply` rather than templated, reproducible Helm charts and GitOps pipelines."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did you design a reusable RAG framework that allows different teams to customize AI solutions using their own data?', '{"key_points": [{"id": "KP1", "description": "Architect a multi-tenant platform with logical tenant isolation, configurable ingestion pipelines, and per-tenant vector namespaces.", "required": true, "acceptable_evidence": ["Technical keywords: multi-tenant platform, tenant isolation, collection partitioning, namespace isolation, modular ingestion, metadata scoping.", "Enforces tenant boundary isolation using dedicated vector collections or tenant-indexed partitions (e.g., `tenant_id` hard filter in Milvus/Pinecone) combined with tenant-scoped S3 buckets.", "Provides extensible document parsers and chunking strategies configurable via tenant configuration profiles (YAML/JSON schemas)."]}, {"id": "KP2", "description": "Design clean modular abstractions and plugin SDKs decoupling retrieval engines, rerankers, and foundation model providers.", "required": true, "acceptable_evidence": ["Technical keywords: abstract base classes (ABC), Strategy pattern, dependency injection, pluggable components, LLM gateway, model-agnostic.", "Implements abstract interfaces (`BaseRetriever`, `BaseEmbedder`, `BaseReranker`, `BaseLLM`) allowing internal product teams to swap models (e.g., Claude 3.5 Sonnet vs. Llama 3) without changing orchestration logic.", "Exposes a unified RESTful/gRPC API with standard request envelopes supporting custom hyperparameters (top_k, temperature, reranking weights)."]}, {"id": "KP3", "description": "Implement centralized governance, per-tenant rate limiting, token quota allocation, and billing observability.", "required": true, "acceptable_evidence": ["Technical keywords: rate limiting, token quotas, tenant cost attribution, chargeback model, API key management, Redis token bucket.", "Enforces per-tenant rate limiting and token consumption quotas via Redis sliding window / token bucket algorithms.", "Emits granular Prometheus metrics tagged with `tenant_id` to enable automated chargeback reporting and cost attribution across engineering divisions."]}], "critical_failures": ["Proposes hardcoding business logic and prompt templates into a monolithic backend that forces all enterprise teams to share identical chunking and model settings.", "Stores all multi-tenant enterprise data in a single unpartitioned vector table without tenant filtering, causing catastrophic cross-tenant data leakage.", "Omits tenant rate limiting and cost attribution, allowing a single rogue tenant script to exhaust company-wide LLM API rate limits."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'How did you design and manage multi-turn conversation memory, including short-term and long-term storage?', '{"key_points": [{"id": "KP1", "description": "Design a tiered memory architecture separating fast short-term working state from persistent long-term historical memory.", "required": true, "acceptable_evidence": ["Technical keywords: short-term memory, long-term memory, working memory, tiered architecture, Redis session store, persistent database.", "Stores immediate multi-turn turns (e.g., last 5-10 turns) in low-latency Redis cache as structured JSON message lists keyed by `session_id` with TTL.", "Persists complete immutable conversation histories in relational or document databases (PostgreSQL/MongoDB) for auditing, analysis, and long-term retrieval."]}, {"id": "KP2", "description": "Implement token-bounded conversational management using sliding message windows and background recursive summarization.", "required": true, "acceptable_evidence": ["Technical keywords: sliding window buffer, recursive summarization, rolling summary, token budget, conversational compression.", "Calculates exact cumulative token counts using tokenizers (e.g., tiktoken) to retain the system prompt plus the most recent $K$ turns.", "When token thresholds are reached, asynchronously triggers a smaller LLM worker to compress older turns into an evolving structured summary entity state prepended to the context window."]}, {"id": "KP3", "description": "Incorporate episodic semantic memory retrieval via vector indexing of historical user conversations and profile attributes.", "required": true, "acceptable_evidence": ["Technical keywords: episodic memory, semantic memory, conversational vector retrieval, user profile embedding, cross-session continuity.", "Embeds past resolved user sessions and key facts into a dedicated memory vector collection, retrieving historical context when a returning user references past interactions.", "Applies metadata filtering on `user_id` to strictly limit cross-session recall to the authenticated individual."]}], "critical_failures": ["Appends infinite conversational turns into the raw context window until the LLM crashes with context length exceeded errors.", "Stores active chat session state only in local server container memory, causing conversation amnesia upon pod restarts or horizontal scaling.", "Summarizes conversation history synchronously on every single turn, adding 1-2 seconds of unnecessary latency to every user query."]}', 1),
('TECHNICAL', 'AI Engineering', 'NLP', 'HARD', 'SPECIFIC', 120, 'How did you design and use an intent classifier to guide retrieval and metadata filtering?', '{"key_points": [{"id": "KP1", "description": "Implement a high-throughput intent classification stage prior to retrieval to route queries to specialized execution branches.", "required": true, "acceptable_evidence": ["Technical keywords: intent classification, query router, SetFit, fasttext, fine-tuned cross-encoder, routing branch, zero-shot classifier.", "Deploys a low-latency (<15ms) classification model (e.g., lightweight DeBERTa, SetFit, or fine-tuned text classifier) to categorize queries into distinct intents (e.g., Technical Troubleshooting, Billing, Policy Lookup, Chit-Chat).", "Bypasses expensive vector search entirely for non-retrieval intents (e.g., greetings, conversational acknowledgments, direct database lookups)."]}, {"id": "KP2", "description": "Extract structured slot entities (e.g., vehicle model, error code, year, document type) using NER and regex rule pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: Named Entity Recognition (NER), slot extraction, GLiNER, spaCy, Pydantic, regex patterns, structured metadata.", "Identifies domain-specific entities (e.g., `model=''Model 3''`, `dtc_code=''B1020''`, `component=''High Voltage Battery''`) using fast NER models or rule-based token extractors.", "Validates extracted slots against known system taxonomies and enum dictionaries."]}, {"id": "KP3", "description": "Translate extracted slots into dynamic vector database metadata filters and search scope constraints.", "required": true, "acceptable_evidence": ["Technical keywords: metadata filter, boolean expression, partition pruning, pre-filtering, targeted vector search.", "Translates extracted entity slots into database query expressions (e.g., `expr=\\"model == ''Model 3'' and year >= 2021\\"` in Milvus).", "Restricts ANN vector search space to relevant document partitions, eliminating off-topic chunks and boosting retrieval precision."]}], "critical_failures": ["Routes every single input query directly to vector search without classification, causing greetings or pure chitchat to retrieve random documentation chunks.", "Relies on a massive slow LLM call (e.g., GPT-4) purely for basic intent classification, adding 800ms of avoidable latency to the retrieval path.", "Fails to leverage extracted entity slots for metadata filtering, searching the entire unpartitioned multi-model corpus for model-specific questions."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 120, 'How did you formalize evaluation for your retrieval system, and how were metrics like precision@k, recall@k, and MRR integrated into your CI/CD pipeline?', '{"key_points": [{"id": "KP1", "description": "Define and mathematically formalize ranking and retrieval evaluation metrics: Precision@K, Recall@K, MRR@K, and NDCG@K.", "required": true, "acceptable_evidence": ["Technical keywords: Precision@K, Recall@K, Mean Reciprocal Rank (MRR@K), Normalized Discounted Cumulative Gain (NDCG@K), DCG, IDCG, binary relevance vs. graded relevance.", "Formulates MRR@K as $\\\\frac{1}{|Q|} \\\\sum_{i=1}^{|Q|} \\\\frac{1}{\\\\text{rank}_i}$ to measure where the first relevant chunk appears in the top $K$ results.", "Defines NDCG@K to evaluate graded document relevance with logarithmic rank discount (penalizing highly relevant chunks appearing lower in results).", "Contrasts Precision@K (fraction of top $K$ chunks that are relevant) with Recall@K (fraction of all relevant chunks captured in top $K$)."]}, {"id": "KP2", "description": "Integrate automated retrieval evaluation benchmarks as blocking gates in CI/CD pull request pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD gate, GitHub Actions, GitLab CI, regression gate, automated evaluation, pull request check.", "Executes an offline retrieval evaluation runner against the golden benchmark suite whenever changes are made to chunking parameters, embedding models, or indexing configurations.", "Fails the build if PR changes cause NDCG@10 or Recall@5 to drop below established thresholds (e.g., drop > 2% relative to main branch)."]}, {"id": "KP3", "description": "Isolate retrieval evaluation from downstream generation to diagnose embedding and ranking bottlenecks independently.", "required": true, "acceptable_evidence": ["Technical keywords: isolated retrieval evaluation, decoupled testing, error decomposition, retrieval recall vs. generator faithfulness.", "Assesses retriever effectiveness purely on ground-truth chunk IDs without calling the LLM generator, minimizing evaluation runtime and cost.", "Identifies whether RAG failures stem from retriever omission (relevant chunk not retrieved) or generator distortion (chunk retrieved but ignored/hallucinated)."]}], "critical_failures": ["Evaluates retrieval quality solely by inspecting final generated answers rather than computing standalone ranking metrics (MRR, NDCG) on retrieved chunks.", "Confuses Precision@K with Recall@K or treats NDCG as a binary metric without rank position discounting.", "Lacks automated CI/CD evaluation gates, allowing untested embedding changes or chunking alterations to degrade retrieval in production."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Infrastructure as Code & Security', 'MEDIUM', 'SPECIFIC', 90, 'How did you implement authentication and authorization for your RAG system, including securing service-to-service communication?', '{"key_points": [{"id": "KP1", "description": "Enforce end-to-end identity authentication and token-based authorization via OAuth2/OIDC (JWT) at the ingress API gateway.", "required": true, "acceptable_evidence": ["Technical keywords: OAuth2, OIDC, JWT, API Gateway, Keycloak, Auth0, role-based access control (RBAC), token validation.", "Validates cryptographically signed JWT tokens issued by enterprise identity providers at the API gateway layer before forwarding requests to internal services.", "Extracts user identity, organization ID, and role claims from the JWT to propagate downstream user context."]}, {"id": "KP2", "description": "Secure inter-service mesh communication using mutual TLS (mTLS) with Istio/Linkerd and zero-trust network policies.", "required": true, "acceptable_evidence": ["Technical keywords: mutual TLS (mTLS), service mesh, Istio, Linkerd, SPIFFE/SPIRE, Kubernetes NetworkPolicies, zero-trust.", "Encrypts all pod-to-pod traffic between FastAPI, Redis, vector databases, and model serving instances with automated cryptographic mTLS certificate rotation.", "Defines Kubernetes NetworkPolicies restricting egress/ingress so that only authorized API services can query vector database endpoints."]}, {"id": "KP3", "description": "Eliminate static credentials using AWS IAM Roles for Service Accounts (IRSA) and fine-grained cloud role policies.", "required": true, "acceptable_evidence": ["Technical keywords: IAM Roles for Service Accounts (IRSA), OIDC provider, least privilege, AWS Secrets Manager, KMS encryption.", "Associates Kubernetes service accounts directly with scoped AWS IAM roles via OIDC federation, eliminating hardcoded AWS access keys.", "Restricts container permissions to least privilege: e.g., read-only S3 access to specific document buckets and KMS-encrypted vector store access."]}], "critical_failures": ["Hardcodes long-lived AWS IAM access keys or database passwords directly inside Docker container images or Git repositories.", "Allows unauthenticated, cleartext HTTP communication between internal microservices and vector databases without mTLS or network policies.", "Fails to propagate user identity and organizational claims to the vector database, enabling unauthorized cross-user data access."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How did you implement guardrails in your RAG system?', '{"key_points": [{"id": "KP1", "description": "Deploy multi-layered input guardrails to intercept prompt injections, jailbreaks, PII, and out-of-scope domain queries.", "required": true, "acceptable_evidence": ["Technical keywords: input guardrails, prompt injection detection, jailbreak filter, Llama Guard, NeMo Guardrails, Presidio, PII redaction.", "Filters raw user inputs through specialized lightweight security models (e.g., Llama Guard, Prompt Shield) and heuristic pattern matchers before passing to retrieval or LLMs.", "Redacts PII/PHI (SSN, credit card numbers, patient health identifiers) using Microsoft Presidio to maintain strict regulatory compliance."]}, {"id": "KP2", "description": "Implement contextual output guardrails for hallucination detection, topical boundary adherence, and policy compliance.", "required": true, "acceptable_evidence": ["Technical keywords: output guardrails, topical rails, hallucination check, Colang, NeMo Guardrails, policy rails, self-check hallucination.", "Enforces Colang dialogue flows and programmable topical rails preventing the model from giving legal, financial, or competitor advice.", "Executes an output verification pass verifying that generated claims are entailed by the retrieved context before releasing the answer to the user."]}, {"id": "KP3", "description": "Enforce strict syntactic and semantic output schema validation using Pydantic, Instructor, or JSON schema mode.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, Instructor, JSON schema, structured outputs, regex parser, retry logic, deterministic parsing.", "Forces LLM responses into structured Pydantic models with field constraints (e.g., confidence scores between 0 and 1, mandatory citations list).", "Implements automated repair and retry loops when the generated output fails schema validation or regex integrity checks."]}], "critical_failures": ["Relies solely on basic system prompt instructions (e.g., ''Please do not answer questions outside of our domain'') without programmatic input/output guardrail enforcement.", "Sends unredacted customer PII and sensitive data directly to external third-party model APIs.", "Permits unstructured, unvalidated model outputs to be parsed directly by downstream services without Pydantic schema validation or fallback handling."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How did you implement hybrid retrieval using semantic search, keyword search, and graph-based search, and when did each method add value?', '{"key_points": [{"id": "KP1", "description": "Architect a tri-modal retrieval pipeline integrating dense semantic vectors, BM25 sparse keyword indices, and knowledge graph traversal.", "required": true, "acceptable_evidence": ["Technical keywords: tri-modal retrieval, dense vector, sparse BM25, knowledge graph, hybrid retrieval, multi-path candidate generation.", "Executes parallel retrieval across three distinct indices: dense embeddings (semantic meaning), BM25 (exact part numbers, acronyms, rare tokens), and Neo4j/Amazon Neptune (hierarchical entity relationships).", "Aggregates candidate nodes and text chunks across all three retrieval modalities into a unified candidate pool."]}, {"id": "KP2", "description": "Delineate the distinct operational strengths, failure modes, and complementary roles of each retrieval mode.", "required": true, "acceptable_evidence": ["Technical keywords: vocabulary mismatch, out-of-vocabulary (OOV), rare tokens, multi-hop reasoning, relationship traversal, trade-offs.", "Explains that dense vectors excel at conversational paraphrasing but fail on exact part numbers (e.g., ''HV-BATT-042''); BM25 captures exact tokens but misses semantic synonyms; knowledge graphs resolve multi-hop entity relationships (e.g., ''Which components connect to Inverter Subsystem B?'').", "Combines the three to cover individual blind spots and eliminate single-point retrieval failures."]}, {"id": "KP3", "description": "Unify and rerank tri-modal results using Reciprocal Rank Fusion (RRF) and cross-encoder relevance scoring.", "required": true, "acceptable_evidence": ["Technical keywords: Reciprocal Rank Fusion (RRF), cross-encoder reranking, score normalization, rank fusion constant k=60, BGE-Reranker.", "Merges candidate rankings using RRF: $RRF(d) = \\\\sum_{m \\\\in M} \\\\frac{1}{k + r_m(d)}$, ensuring uncalibrated score distributions across modalities do not bias candidate selection.", "Passes top fused candidates through a cross-encoder (e.g., bge-reranker-large) to produce a unified relevance ranking for context assembly."]}], "critical_failures": ["Directly adds raw vector cosine similarities to BM25 BM-scores without score normalization or rank fusion, creating severely distorted rankings.", "Claims dense vector search alone is sufficient for all enterprise queries, ignoring its systematic failure on exact part numbers, serial codes, and error codes.", "Omits cross-encoder reranking or rank fusion, arbitrarily picking results from only one modality."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did you use metadata filtering in your vector database, and how did it improve retrieval accuracy and performance?', '{"key_points": [{"id": "KP1", "description": "Design structured chunk metadata schemas capturing tenant, department, security classification, document type, and effective dates.", "required": true, "acceptable_evidence": ["Technical keywords: metadata schema, scalar attributes, payload indexing, tenant_id, department, access_level, effective_date.", "Attaches structured scalar payloads to each vector: `tenant_id`, `department`, `document_type`, `version`, `effective_date`, `access_roles`.", "Indexes metadata attributes in the vector database using inverted indices or B-trees for sub-millisecond filtering."]}, {"id": "KP2", "description": "Analyze pre-filtering versus post-filtering vector search strategies and their impact on recall and latency.", "required": true, "acceptable_evidence": ["Technical keywords: pre-filtering, post-filtering, single-stage filtering, partition pruning, HNSW graph disconnectedness, recall degradation.", "Explains that naive post-filtering (retrieve top 100 then filter by metadata) can result in zero returned chunks if high-similarity vectors belong to unauthorized departments.", "Details modern single-stage filtered HNSW search or partition pruning (searching only the relevant department partition) to guarantee $K$ valid chunks without graph traversal trapping."]}, {"id": "KP3", "description": "Quantify retrieval performance gains, search space reduction, and security isolation achieved via metadata-guided filtering.", "required": true, "acceptable_evidence": ["Technical keywords: search space reduction, query latency, index pruning, precision gain, multi-tenant isolation.", "Demonstrates that restricting search to specific metadata partitions reduces vector candidate space from millions to tens of thousands, cutting p95 query latency by 40-70%.", "Guarantees data confidentiality by enforcing security role filters directly at the database engine level."]}], "critical_failures": ["Advocates naive post-filtering where queries retrieve top-k vectors first and discard non-matching metadata in Python, causing empty or incomplete results.", "Stores vector embeddings completely without metadata, requiring full-table scans across all documents and enterprise divisions.", "Fails to index metadata fields, causing vector database pre-filtering to perform slow unindexed sequential scans."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How did your agentic workflow manage both short-term memory (using LangGraph state objects) and long-term memory (using a vector database)?', '{"key_points": [{"id": "KP1", "description": "Architect short-term agent working memory using LangGraph state objects and persistent checkpointers (Sqlite/PostgresSaver).", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, AgentState, TypedDict, Checkpointer, MemorySaver, PostgresSaver, thread_id, state persistence.", "Defines structured agent state schemas (`messages`, `tool_outputs`, `intermediate_steps`, `extracted_slots`) passed across workflow graph nodes.", "Uses checkpoint savers (e.g., `PostgresSaver`) keyed by `thread_id` to persist working execution state, enabling state recovery across crashes and multi-turn human-in-the-loop interruptions."]}, {"id": "KP2", "description": "Implement long-term episodic and semantic memory storage in external vector databases (Milvus/PGVector).", "required": true, "acceptable_evidence": ["Technical keywords: long-term memory, episodic memory, vector store, Milvus, PGVector, user preference embedding, past session retrieval.", "Stores cross-session user preferences, resolved historical tickets, and agent-learned facts in an external vector database.", "Embeds user interactions at the end of each session and indexes them tagged with `user_id` and timestamp metadata."]}, {"id": "KP3", "description": "Coordinate dynamic memory recall within agent execution nodes prior to planning and tool execution.", "required": true, "acceptable_evidence": ["Technical keywords: memory recall node, context injection, LangGraph node transition, prompt construction, memory decay/relevance.", "Inserts an initial graph node that queries long-term vector memory using the incoming user prompt, injecting relevant historical memories into the short-term working state.", "Balances short-term working memory and retrieved long-term memories within strict context token limits."]}], "critical_failures": ["Conflates LangGraph short-term graph execution state with long-term vector database storage, treating them as interchangeable.", "Maintains agent execution state purely in ephemeral in-memory variables without checkpointing, losing all state if a worker pod restarts.", "Injects entire unindexed historical chat logs into every agent prompt without vector retrieval or relevance filtering."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 120, 'How do you balance latency in an LLM pipeline, considering aspects like retrieval latency, caching, and horizontal scaling?', '{"key_points": [{"id": "KP1", "description": "Dissect the RAG latency breakdown across network hops, embedding generation, vector search, reranking, and LLM Time-to-First-Token (TTFT).", "required": true, "acceptable_evidence": ["Technical keywords: latency profiling, Time-to-First-Token (TTFT), Time-per-Output-Token (TPOT), p95/p99 latency, embedding latency, vector search latency, reranker overhead.", "Profiles the complete latency waterfall: client hop (20ms) -> embedding inference (15-30ms) -> ANN vector search (10-25ms) -> cross-encoder reranking (50-120ms) -> LLM TTFT (300-800ms) -> LLM token streaming (20-40ms/token).", "Identifies TTFT and model generation as the dominant latency bottlenecks requiring optimization."]}, {"id": "KP2", "description": "Implement asynchronous token streaming via Server-Sent Events (SSE) and parallelized multi-source retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: Server-Sent Events (SSE), asyncio.gather, async streaming, parallel retrieval, concurrent execution, perceived latency.", "Streams tokens immediately to the client frontend over HTTP SSE or WebSockets as they are generated by the model, slashing perceived user latency from 3+ seconds to under 400ms.", "Executes sparse keyword search, dense vector search, and metadata lookups concurrently using Python `asyncio.gather`."]}, {"id": "KP3", "description": "Apply multi-layer caching, connection pooling, and speculative retrieval execution to minimize round-trip times.", "required": true, "acceptable_evidence": ["Technical keywords: semantic cache, Redis, prompt caching, connection pooling, speculative execution, persistent HTTP client sessions.", "Implements Redis semantic caching to return sub-50ms responses for near-identical queries without hitting the retriever or LLM.", "Leverages persistent HTTP/2 connection pooling (`httpx.AsyncClient`) and model provider prompt prefix caching (Anthropic/OpenAI) to eliminate redundant TTFT overhead."]}], "critical_failures": ["Waits for full generation completion before returning a massive monolithic JSON payload instead of streaming tokens via SSE.", "Executes vector search, keyword search, and metadata lookups sequentially rather than concurrently using `asyncio.gather`.", "Creates fresh database and HTTP client connections on every incoming request instead of utilizing persistent connection pools."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'How do you design a DAG-based pipeline for document retrieval and generation using tools like LangChain, and LLMs?', '{"key_points": [{"id": "KP1", "description": "Model complex document ingestion and RAG generation workflows as deterministic Directed Acyclic Graphs (DAGs).", "required": true, "acceptable_evidence": ["Technical keywords: Directed Acyclic Graph (DAG), Apache Airflow, Celery, task graph, deterministic dependencies, topological sort.", "Structures ingestion pipelines into sequential and parallel DAG nodes: Document Extraction -> OCR/Parsing -> Chunking -> Vector Embedding -> Index Insertion -> Inverted Index Update.", "Ensures tasks have strictly defined inputs, outputs, and acyclic dependency graphs."]}, {"id": "KP2", "description": "Implement robust task retry policies, exponential backoff, dead-letter queues, and idempotent task execution.", "required": true, "acceptable_evidence": ["Technical keywords: task retries, exponential backoff, dead-letter queue (DLQ), idempotency, content hash deduplication, fault tolerance.", "Configures Celery/Airflow operators with exponential backoff retries for transient third-party API rate limits or network glitches.", "Ensures each task is idempotent (e.g., upserting vectors keyed by content SHA-256 hash) so retried runs never generate duplicate chunks or corrupted database state."]}, {"id": "KP3", "description": "Manage distributed worker queues, Redis/RabbitMQ message brokers, and pipeline state monitoring.", "required": true, "acceptable_evidence": ["Technical keywords: message broker, Redis, RabbitMQ, Celery workers, queue isolation, concurrency management, Flower, Airflow UI.", "Segregates workloads into dedicated worker queues: e.g., CPU-bound parsing/OCR queues, GPU-bound embedding generation queues, and I/O-bound indexing queues.", "Monitors task health, worker lag, and pipeline throughput using Celery Flower, Prometheus exporters, and Airflow DAG dashboards."]}], "critical_failures": ["Designs ingestion workflows as a single fragile monolithic script that crashes completely on page 95 of a 100-page document without checkpointing.", "Lacks idempotent execution, resulting in duplicate chunks and corrupted vector indices upon task restarts.", "Runs heavy GPU embedding generation on the same unmanaged threads as user-facing API request handlers, causing worker deadlocks."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How do you design a multi-agent system with RAG, such as an AI code review agent that leverages repository-level knowledge?', '{"key_points": [{"id": "KP1", "description": "Architect specialized multi-agent roles: PR Diff Analyzer, Architectural Standards Checker, and Security & Linting Specialist.", "required": true, "acceptable_evidence": ["Technical keywords: multi-agent system, role specialization, PR Diff Analyzer, Standards Checker, Security Agent, Synthesizer Agent, orchestrator.", "Decomposes code review into specialized agent personas: Diff Analyzer parses git hunks; Standards Checker retrieves team wiki rules and conventions; Security Agent checks for OWASP vulnerabilities; Synthesizer resolves conflicting comments.", "Coordinates agent interactions through a centralized orchestrator or state machine."]}, {"id": "KP2", "description": "Implement repository-level RAG combining Abstract Syntax Tree (AST) code chunking with architectural documentation retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: Abstract Syntax Tree (AST), Tree-sitter, code chunking, symbol indexing, repository graph, documentation retrieval.", "Parses source files using Tree-sitter into syntax-aware chunks (classes, methods, functions) retaining file path, imports, and symbol signatures in metadata.", "Indexes repo markdown wikis, design guidelines, and API specs to provide contextual grounding for reviewer agents."]}, {"id": "KP3", "description": "Incorporate deterministic linting and static analysis tools as callable agent tools to eliminate hallucinations.", "required": true, "acceptable_evidence": ["Technical keywords: tool integration, static analysis, Flake8, Ruff, SonarQube, Semgrep, AST verification, tool calling.", "Equips agents with deterministic CLI/API tools (Ruff, Semgrep, bandit) to verify syntax errors, unused imports, and security vulnerabilities prior to comment generation.", "Filters out LLM hallucinated suggestions by compiling or executing static rule checkers against candidate code changes."]}], "critical_failures": ["Feeds raw 20,000-line git diffs directly into a single generic prompt without AST parsing, chunking, or agent specialization.", "Allows the agent to hallucinate fake linting rules or non-existent library methods without grounding reviews in static analysis tools or repository wikis.", "Generates noisy, uncoordinated review comments from multiple agents without a synthesizer agent de-duplicating and formatting the final PR review."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How do you determine the optimal chunk size, and what trade-offs influenced your choice of 1,000-2,000 tokens?', '{"key_points": [{"id": "KP1", "description": "Analyze empirical trade-offs of small chunk sizes (200-500 tokens): high retrieval precision, low semantic dilution, but lost cross-passage context.", "required": true, "acceptable_evidence": ["Technical keywords: small chunk size, 200-500 tokens, embedding density, semantic dilution, high precision, lost cross-paragraph context.", "Explains that short chunks produce tight, focused vector representations that maximize cosine similarity on specific factual queries and minimize noise.", "Highlights the trade-off: short chunks fragment complex explanations across boundaries, failing on questions that require multi-sentence synthesis."]}, {"id": "KP2", "description": "Analyze empirical trade-offs of large chunk sizes (1,000-2,000 tokens): broad context retention, narrative continuity, but diluted embeddings and context crowding.", "required": true, "acceptable_evidence": ["Technical keywords: large chunk size, 1000-2000 tokens, contextual completeness, embedding dilution, lost-in-the-middle, context window consumption.", "Explains that large chunks preserve complete procedures, multi-step troubleshooting guides, and nested table data without breaking logic.", "Highlights the trade-off: embedding vectors become averaged and diffuse (dilution effect), lowering cosine similarity for pinpoint queries, while rapidly consuming LLM context token budgets."]}, {"id": "KP3", "description": "Implement parent-document retrieval or hierarchical chunking to achieve small-chunk retrieval precision with large-chunk synthesis context.", "required": true, "acceptable_evidence": ["Technical keywords: Parent Document Retriever, hierarchical chunking, child chunks, parent chunks, small-to-large retrieval, context expansion.", "Embeds and indexes small 200-token ''child'' chunks for laser-focused vector retrieval, but returns their enclosing 1,500-token ''parent'' document chunk to the LLM for synthesis.", "Provides the mathematical best of both worlds: high vector search precision combined with rich generative context."]}], "critical_failures": ["Arbitrarily selects chunk size without empirical testing or awareness of the embedding dilution trade-off.", "Claims 2,000-token chunks always outperform 300-token chunks without recognizing that dense embedding models (e.g., MiniLM with 512 max sequence length) truncate or dilute large passages.", "Fails to mention hierarchical chunking or parent-document retrieval as a solution to the chunk-size dilemma."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How do you evaluate the quality of generated responses in a RAG system using metrics like BERTScore and LLM-based evaluation?', '{"key_points": [{"id": "KP1", "description": "Formalize embedding-based semantic generation metrics: BERTScore and Semantic Answer Similarity (SAS) using cosine similarity.", "required": true, "acceptable_evidence": ["Technical keywords: BERTScore, Semantic Answer Similarity (SAS), cross-encoder SAS, token embedding alignment, cosine similarity, BLEU/ROUGE limitations.", "Calculates BERTScore by matching token embeddings between generated and reference answers via maximal cosine similarity and precision/recall/F1 scoring.", "Contrasts semantic similarity with rigid n-gram metrics (BLEU/ROUGE), highlighting that BERTScore accommodates valid paraphrasing and vocabulary shifts."]}, {"id": "KP2", "description": "Implement LLM-as-a-Judge evaluation frameworks (G-Eval, Ragas) with structured multi-criteria rubrics.", "required": true, "acceptable_evidence": ["Technical keywords: LLM-as-a-Judge, G-Eval, Ragas, evaluation rubric, Likert scale, faithfulness, answer relevance, chain-of-thought evaluation.", "Deploys frontier evaluator models (GPT-4 / Claude 3.5 Sonnet) prompted with detailed rubrics evaluating faithfulness (entailment against retrieved context) and answer relevance (alignment with user intent).", "Requires the evaluator LLM to generate chain-of-thought explanations before outputting numeric scores (1-5 scale) to boost rating consistency."]}, {"id": "KP3", "description": "Mitigate LLM-as-a-Judge biases: position bias, self-enhancement bias, verbosity bias, and score calibration.", "required": true, "acceptable_evidence": ["Technical keywords: position bias, verbosity bias, self-enhancement bias, calibration, judge consensus, pairwise swap, Cohen''s kappa.", "Mitigates position bias in pairwise evaluations by swapping candidate answer order and checking for score flips.", "Penalizes ungrounded verbosity, calibrates evaluator prompts against human-annotated sample sets, and measures inter-annotator agreement (Cohen''s Kappa)."]}], "critical_failures": ["Relies solely on BLEU or ROUGE to evaluate open-ended RAG generation, penalizing legitimate synonymous responses.", "Uses uncalibrated LLM-as-a-Judge prompts without structured rubrics, chain-of-thought reasoning, or bias mitigation controls.", "Fails to separate faithfulness evaluation (evaluating generation vs. retrieved context) from answer relevance evaluation (evaluating generation vs. user query)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you evaluate whether a use case requires semantic search, classification, or another retrieval approach when designing an AI system?', '{"key_points": [{"id": "KP1", "description": "Establish decision criteria for supervised classification: finite discrete label sets, high precision, low latency, and deterministic taxonomies.", "required": true, "acceptable_evidence": ["Technical keywords: supervised classification, discrete taxonomy, labeled dataset, low latency (<10ms), deterministic outputs, BERT/RoBERTa.", "Chooses supervised classification when target outputs are bounded and well-defined (e.g., routing support tickets to 15 fixed categories, sentiment analysis, spam detection).", "Highlights advantages: sub-10ms inference, zero hallucination risk, low compute cost, and strict deterministic behavior."]}, {"id": "KP2", "description": "Establish decision criteria for relational SQL lookups: structured tabular data, exact key lookups, ACID guarantees, and aggregate computations.", "required": true, "acceptable_evidence": ["Technical keywords: relational SQL, ACID transactions, exact match, foreign keys, aggregations, deterministic queries, PostgreSQL.", "Chooses relational databases when queries involve structured schema fields, transactional integrity (ACID), mathematical aggregates (`SUM`, `AVG`), or exact key lookups (e.g., user account balance, order status).", "Emphasizes that vector search cannot perform exact arithmetic or reliable relational joins."]}, {"id": "KP3", "description": "Establish decision criteria for semantic vector search: open-ended unstructured queries, concept fuzziness, and knowledge retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: semantic vector search, unstructured data, cross-vocabulary retrieval, conceptual similarity, knowledge bases, approximate nearest neighbors.", "Chooses vector search when queries are natural language descriptions, documents are unstructured prose (PDFs, manuals, FAQs), and users seek conceptual relevance rather than exact keyword matches.", "Advocates a composite architecture routing structured intents to SQL, category routing to classifiers, and knowledge retrieval to vector stores."]}], "critical_failures": ["Forces vector search into use cases requiring exact transactional lookups or arithmetic aggregations (e.g., querying an account balance with vector embeddings).", "Builds complex generative RAG pipelines for simple fixed-class categorization tasks that a lightweight 10ms classifier handles deterministically.", "Fails to present a comparative architectural matrix evaluating latency, cost, determinism, and data structure suitability across the paradigms."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How do you implement caching in your retrieval system to avoid repeated queries to the vector database?', '{"key_points": [{"id": "KP1", "description": "Implement an exact-match query cache using Redis key-value stores with cryptographic query hashing.", "required": true, "acceptable_evidence": ["Technical keywords: exact query cache, Redis, SHA-256 hash, normalized query string, TTL expiration, sub-5ms latency.", "Hashes normalized, lowercased, whitespace-stripped incoming query strings and checks Redis for cached chunk IDs or completed responses.", "Delivers sub-5ms p95 latency on frequent identical queries, completely bypassing embedding inference and vector database lookups."]}, {"id": "KP2", "description": "Implement a semantic vector cache (GPTCache) matching conceptually equivalent queries via cosine similarity thresholds.", "required": true, "acceptable_evidence": ["Technical keywords: semantic cache, GPTCache, cosine similarity threshold, embedding comparison, cache hit ratio, false positive trade-off.", "Embeds incoming queries and searches an in-memory or low-latency vector cache index; if similarity exceeds a tuned threshold (e.g., $\\\\ge 0.96$), serves cached results.", "Handles natural language paraphrasing (e.g., ''How do I reset my Tesla screen?'' vs. ''Rebooting Tesla touchscreen display'') with zero downstream LLM cost."]}, {"id": "KP3", "description": "Leverage model provider prompt prefix caching and implement cache invalidation upon knowledge base updates.", "required": true, "acceptable_evidence": ["Technical keywords: prompt prefix caching, Anthropic/OpenAI prompt cache, cache invalidation, write-through invalidation, cache stampede mitigation.", "Structures LLM prompts with static system rules and documentation headers placed first to hit model-level KV-pair prompt caches, cutting generation cost and TTFT by up to 80%.", "Configures automated cache invalidation (evicting related Redis/GPTCache keys) when documents are modified or deleted in the primary ingestion pipeline."]}], "critical_failures": ["Sets overly loose semantic cache similarity thresholds (e.g., 0.80), causing queries with subtly different intents to receive incorrect cached responses.", "Lacks cache invalidation mechanisms, continuing to serve stale and outdated answers after knowledge base documents have been edited or revoked.", "Caches dynamic multi-turn conversational responses keyed solely on the user''s latest query without including user permissions or session context."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How do you implement tool calling in an agentic system, and how does it enable actions beyond simple retrieval?', '{"key_points": [{"id": "KP1", "description": "Define formal tool schemas with Pydantic typing, clear docstrings, and strict parameter specifications.", "required": true, "acceptable_evidence": ["Technical keywords: tool schemas, function calling, JSON Schema, Pydantic, tool descriptions, OpenAI tools API, LangChain `@tool`.", "Provides the LLM with structured JSON schema declarations specifying tool names, precise semantic descriptions, parameter types, required fields, and boundary constraints.", "Highlights that clear parameter docstrings directly govern the model''s ability to select appropriate tools and extract correct argument values."]}, {"id": "KP2", "description": "Implement the agent execution loop: tool call generation, argument validation, safe execution, and output observation injection.", "required": true, "acceptable_evidence": ["Technical keywords: ReAct loop, tool call invocation, parameter parsing, exception handling, observation feedback, agent reflection.", "Parses the LLM''s `tool_calls` payload, validates arguments against Pydantic models, and dispatches execution to internal functions or microservices.", "Captures function outputs (or error stack traces) and feeds them back into the conversation context as `ToolMessage` observations for next-step reasoning."]}, {"id": "KP3", "description": "Integrate standardized tool protocols (Model Context Protocol - MCP) and enforce security sandboxing on destructive operations.", "required": true, "acceptable_evidence": ["Technical keywords: Model Context Protocol (MCP), client-server tool architecture, sandboxing, human-in-the-loop (HITL), authorization scopes.", "Adopts standard protocols like Anthropic''s MCP to discover and connect tools dynamically across distributed services.", "Enforces read-only sandboxing by default and inserts human-in-the-loop confirmation gates prior to executing state-mutating or high-impact actions (e.g., executing SQL updates, sending external emails)."]}], "critical_failures": ["Executes raw LLM-generated strings directly via `eval()` or unvalidated shell execution, introducing catastrophic remote code execution vulnerabilities.", "Permits autonomous execution of destructive actions (database deletes, financial transactions) without authorization checks or human approval gates.", "Crashes the agent workflow when a tool returns an API error instead of catching exceptions and feeding error messages back to the model for recovery."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How do you manage the infrastructure and cost considerations when hosting embedding models on platforms like EKS?', '{"key_points": [{"id": "KP1", "description": "Evaluate self-hosted model serving on Amazon EKS (Triton / Text-Embeddings-Inference) versus managed serverless APIs (Amazon Titan / OpenAI).", "required": true, "acceptable_evidence": ["Technical keywords: Amazon EKS, Text Embeddings Inference (TEI), Triton Inference Server, managed APIs, OpenAI Embeddings, Amazon Titan, cost break-even.", "Performs a rigorous cost-volume analysis: managed APIs are cost-effective at low/variable request volumes ($0.00002/1k tokens), but self-hosted containers become substantially cheaper at massive sustained throughput (>50M tokens/day).", "Notes enterprise benefits of self-hosting: zero data egress to external vendors, predictable latency, and HIPAA/SOC2 compliance isolation."]}, {"id": "KP2", "description": "Compare hardware acceleration options on AWS: NVIDIA Tensor Core GPUs (g5/g6 instances) versus AWS Inferentia/Neuron (inf2 instances).", "required": true, "acceptable_evidence": ["Technical keywords: NVIDIA GPU, g5.xlarge, A10G, AWS Inferentia2, inf2 instances, AWS Neuron SDK, price-performance ratio, batch inference throughput.", "Evaluates AWS Inf2 instances powered by Neuron accelerators, delivering up to 40-50% lower cost per inference compared to equivalent NVIDIA GPU instances for transformer models.", "Analyzes trade-offs: NVIDIA offers standard CUDA compatibility and out-of-the-box HuggingFace support, while Neuron requires model compilation via Neuron SDK."]}, {"id": "KP3", "description": "Optimize serving throughput using HuggingFace Text Embeddings Inference (TEI), dynamic batching, and Karpenter node autoscaling.", "required": true, "acceptable_evidence": ["Technical keywords: Text Embeddings Inference (TEI), dynamic batching, token padding elimination, FlashAttention, Karpenter, spot instances.", "Deploys HuggingFace TEI or vLLM to leverage dynamic request batching and FlashAttention, maximizing GPU saturation and achieving 1,000+ embeddings/second.", "Utilizes Karpenter with AWS Spot Instances to autoscale GPU/Neuron node pools dynamically, reducing infrastructure expenditure during off-peak hours."]}], "critical_failures": ["Proposes provisioning expensive 24/7 dedicated GPU instances (e.g., p4d/g5 instances) for tiny workloads processing only a few hundred queries per day.", "Deploys raw Python Flask/Torch scripts without dynamic batching or production inference servers (TEI/Triton), running GPUs at sub-5% utilization.", "Ignores data security and regulatory constraints, assuming external third-party embedding APIs are universally permitted for classified enterprise data."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How do you prevent hallucinations in LLM-based systems using evaluation and guardrail techniques?', '{"key_points": [{"id": "KP1", "description": "Engineer constrained system prompts enforcing strict contextual grounding, explicit citations, and refusal instructions.", "required": true, "acceptable_evidence": ["Technical keywords: prompt constraints, grounding instructions, answer refusal condition, citation requirement, system prompt engineering.", "Configures explicit system instructions directing the model: ''Answer solely based on the provided context. If the context does not explicitly contain the answer, state that information is unavailable. Never speculate or infer beyond provided facts.''", "Requires the LLM to bracket every factual assertion with source chunk IDs (e.g., `[Doc-12]`)."]}, {"id": "KP2", "description": "Deploy post-generation Natural Language Inference (NLI) and self-check verification models to detect ungrounded claims.", "required": true, "acceptable_evidence": ["Technical keywords: Natural Language Inference (NLI), DeBERTa-v3-large, premise-hypothesis entailment, self-check hallucination, atomic claim extraction.", "Deconstructs generated answers into atomic factual claims and tests each claim as a hypothesis against retrieved context premises using a fine-tuned NLI classifier.", "Flags responses as hallucinations if any atomic claim produces a contradiction or neutral (unsupported) entailment prediction."]}, {"id": "KP3", "description": "Integrate programmatic guardrails and automated fallback interception prior to serving responses to users.", "required": true, "acceptable_evidence": ["Technical keywords: NeMo Guardrails, hallucination rail, response interception, programmatic fallback, human escalation.", "Configures guardrail checks that intercept answers failing faithfulness thresholds ($\\text{faithfulness} < 0.85$).", "Replaces hallucinated model text with safe, standardized fallback messages directing users to human specialists or verified documentation links."]}], "critical_failures": ["Assumes default prompt settings without negative constraints will naturally prevent hallucinations on missing knowledge.", "Deploys unverified generative answers directly to enterprise users without entailment checking or NLI verification.", "Allows the model to speculate or extrapolate plausible-sounding explanations when retrieved documentation contains no relevant facts."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How do you prevent hallucinations in LLM-based systems, particularly when using retrieved data and structured outputs like SQL results?', '{"key_points": [{"id": "KP1", "description": "Enforce grammar-constrained decoding and Pydantic schema validation for deterministic structured JSON outputs.", "required": true, "acceptable_evidence": ["Technical keywords: grammar-constrained decoding, JSON schema, Pydantic, Instructor, Outlines, CFG grammar, deterministic parsing.", "Uses grammar-guided logit masking (e.g., Outlines, llama.cpp grammars, or OpenAI structured outputs) to restrict token generation strictly to valid JSON tokens conforming to a predefined schema.", "Validates parsed JSON against Pydantic models with field-level regex and type assertions, eliminating syntax parsing errors entirely."]}, {"id": "KP2", "description": "Prevent schema hallucinations in Text-to-SQL generation through database introspection and read-only AST parsing.", "required": true, "acceptable_evidence": ["Technical keywords: Text-to-SQL, database introspection, information_schema, SQLGlot, AST validation, read-only permissions.", "Injects exact live database schemas (table definitions, foreign keys, column data types) into the prompt context to prevent the LLM from inventing non-existent table or column names.", "Parses generated SQL using SQLGlot AST analyzer to verify column existence and ensure the query contains only read-only `SELECT` statements, rejecting any `DROP`, `UPDATE`, or `DELETE` statements."]}, {"id": "KP3", "description": "Implement automated error correction loops that feed database syntax/validation errors back to the model for self-repair.", "required": true, "acceptable_evidence": ["Technical keywords: self-repair loop, iterative refinement, exception feedback, transaction rollback, bounded retries.", "Captures database query execution exceptions (e.g., syntax errors, missing join keys) and passes the failed SQL query and error traceback back into the prompt context for targeted regeneration.", "Caps self-repair retries at 2-3 attempts before safely aborting to a human analyst or fallback message."]}], "critical_failures": ["Executes raw LLM-generated SQL strings directly against production databases without AST validation or read-only credential constraints.", "Parses JSON outputs using naive string manipulation or regex without formal Pydantic schema validation or grammar-constrained sampling.", "Fails to provide actual database schemas in the context, resulting in rampant hallucinations of column and table names."]}', 1),
('TECHNICAL', 'AI Engineering', 'NLP', 'MEDIUM', 'SPECIFIC', 90, 'How do you select and evaluate embedding models for a RAG system, and why did you choose Sentence Transformers (MiniLM)?', '{"key_points": [{"id": "KP1", "description": "Benchmark candidate embedding models on domain-specific test suites using MTEB retrieval metrics and latency profiles.", "required": true, "acceptable_evidence": ["Technical keywords: Massive Text Embedding Benchmark (MTEB), all-MiniLM-L6-v2, BGE-large-en, text-embedding-3-small, NDCG@10, p95 latency.", "Evaluates candidate models (e.g., `all-MiniLM-L6-v2`, `bge-small-en-v1.5`, `text-embedding-3-large`) against internal domain datasets measuring NDCG@10, Recall@10, and indexing speed.", "Compares embedding dimension sizes (384 vs. 768 vs. 1536) and maximum token sequence lengths (256, 512, 8192)."]}, {"id": "KP2", "description": "Analyze technical and operational justifications for selecting compact models like all-MiniLM-L6-v2 in high-throughput environments.", "required": true, "acceptable_evidence": ["Technical keywords: 384 dimensions, CPU inference, latency budget (<10ms), memory footprint, high-throughput, edge deployment.", "Justifies MiniLM selection: compact 384-dimensional vectors reduce vector database index memory and disk footprint by 50-75% compared to 768/1536-dim models.", "Enables sub-10ms CPU inference using ONNX Runtime without requiring dedicated GPUs for embedding generation."]}, {"id": "KP3", "description": "Identify boundary limitations of lightweight embedding models and establish criteria for upgrading to advanced models.", "required": true, "acceptable_evidence": ["Technical keywords: sequence length truncation (256/512 tokens), complex semantic nuance, cross-domain degradation, upgrade path.", "Recognizes limitations: 512-token sequence limits cause aggressive truncation on long passages, and shallow representations degrade on complex technical jargon.", "Establishes upgrade criteria: when technical terminology causes NDCG@10 to fall below 0.65, fine-tune domain embeddings or transition to BGE/OpenAI embeddings."]}], "critical_failures": ["Selects embedding models solely based on global public MTEB leaderboards without benchmarking on domain-specific company data.", "Ignores model sequence length constraints, attempting to encode 2,000-token chunks into a 512-token maximum sequence model like MiniLM.", "Fails to account for vector database memory scaling and CPU vs. GPU inference latency differences across embedding models."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How does approximate nearest neighbor (ANN) search work, and why is it important for semantic retrieval?', '{"key_points": [{"id": "KP1", "description": "Explain the algorithmic architecture of Hierarchical Navigable Small World (HNSW) graphs across multi-layer skip-lists.", "required": true, "acceptable_evidence": ["Technical keywords: HNSW, multi-layer graph, skip-list analogy, logarithmic search complexity O(log N), entry point, greedy routing.", "Describes HNSW as a hierarchical multi-layer graph where top layers contain sparse long-range connections for rapid global exploration, while bottom layer 0 contains dense short-range connections for local exploitation.", "Traces query traversal: starts at top-layer entry point, greedily hops to nearest neighbors, drops down layers, and performs fine-grained beam search at layer 0."]}, {"id": "KP2", "description": "Analyze key HNSW indexing and search hyperparameters: M, efConstruction, and efSearch.", "required": true, "acceptable_evidence": ["Technical keywords: M (bi-directional links), efConstruction (build beam width), efSearch (query beam width), recall-latency trade-off, memory overhead.", "Details $M$ (number of bi-directional links per node, e.g., 16-64), balancing index graph connectivity against RAM usage.", "Details $efConstruction$ (candidate evaluation list size during index build) and $efSearch$ (candidate beam size at query time, e.g., 64-128), which directly tunes recall versus query latency."]}, {"id": "KP3", "description": "Contrast ANN graph search with brute-force k-NN (Flat) in high-throughput enterprise systems.", "required": true, "acceptable_evidence": ["Technical keywords: k-NN Flat, brute-force exact search, linear O(N) complexity, scalability wall, recall vs. speed trade-off.", "Explains that brute-force Flat search has $O(N \\\\cdot D)$ complexity, which becomes unacceptably slow (>100ms) beyond 100k vectors.", "Demonstrates that HNSW achieves $O(\\\\log N)$ sub-10ms latency over millions of vectors while maintaining >95-98% recall accuracy."]}], "critical_failures": ["Confuses HNSW graph navigation with inverted file indexing (IVF) or locality-sensitive hashing (LSH).", "Fails to explain the role of HNSW hyperparameters (M, efConstruction, efSearch) in balancing recall, memory footprint, and query latency.", "Claims approximate nearest neighbor search is required for tiny datasets of 500 vectors where exact flat search runs in 1ms with zero memory overhead."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How does your system handle cases where retrieved results are irrelevant or insufficient to answer the user-s query?', '{"key_points": [{"id": "KP1", "description": "Implement multi-threshold gating using vector distance cutoffs and cross-encoder reranker confidence scores.", "required": true, "acceptable_evidence": ["Technical keywords: distance threshold, cosine cutoff, reranker logit score, relevance gating, threshold calibration.", "Sets empirical similarity thresholds (e.g., minimum cosine similarity $\\\\ge 0.72$ or cross-encoder reranker probability $\\\\ge 0.40$) to detect when all retrieved chunks are irrelevant.", "Rejects chunks failing the cutoff to prevent noisy, uninformative context from reaching the LLM."]}, {"id": "KP2", "description": "Incorporate LLM contextual sufficiency verification prior to synthesis.", "required": true, "acceptable_evidence": ["Technical keywords: sufficiency verification, context relevance check, binary decision gate, self-assessment.", "Executes a fast check asking the LLM or an auxiliary classifier: ''Does the retrieved context provide sufficient factual evidence to answer query X?''", "If the assessment is negative, immediately aborts generation and routes to fallback."]}, {"id": "KP3", "description": "Design graceful degradation and fallback strategies including transparent refusal, web search, and human agent escalation.", "required": true, "acceptable_evidence": ["Technical keywords: graceful degradation, transparent refusal, human escalation, ticket creation, active learning log.", "Returns polite, deterministic refusal responses: ''I don''t have enough information in the verified knowledge base to answer this question accurately.''", "Logs failed/out-of-corpus queries to an active learning queue for knowledge base expansion, and offers the user an option to escalate to a human tier-2 support agent."]}], "critical_failures": ["Forces the LLM to generate an answer regardless of chunk relevance scores, resulting in hallucinated fabrications.", "Lacks confidence score thresholds, passing low-similarity random noise chunks directly into the context window.", "Fails to capture and log unanswered out-of-corpus queries, missing critical visibility into knowledge base coverage gaps."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you build a data-driven case to justify architectural improvements (e.g., reranking, graph-based retrieval) to stakeholders?', '{"key_points": [{"id": "KP1", "description": "Translate technical RAG failure metrics into concrete business costs, customer churn, and brand reputation risks.", "required": true, "acceptable_evidence": ["Technical keywords: business impact, customer churn, support escalation cost, SLA violations, brand risk, executive communication.", "Translates technical issues (e.g., 18% hallucination rate) into financial reality: each hallucinated answer causes an escalated call costing $25/ticket, totaling $45,000/month in avoidable support overhead.", "Communicates risks clearly in business terms without alienating non-technical stakeholders with purely academic jargon."]}, {"id": "KP2", "description": "Present empirical proof-of-concept benchmark data demonstrating measurable gains from proposed improvements.", "required": true, "acceptable_evidence": ["Technical keywords: POC benchmark, A/B offline experiment, NDCG@10 lift, error reduction, ROI projection, side-by-side comparison.", "Presents concrete offline evaluation results: adding a cross-encoder reranker and metadata filtering improved NDCG@10 from 0.58 to 0.84 and slashed hallucination rates by 62% on 200 real customer failure cases.", "Provides side-by-side before-and-after answer comparisons demonstrating immediate quality improvements."]}, {"id": "KP3", "description": "Deliver a phased rollout roadmap detailing engineering effort, infrastructure costs, and expected payback horizon.", "required": true, "acceptable_evidence": ["Technical keywords: phased rollout, incremental delivery, GPU cost delta, payback period, milestone tracking, risk mitigation.", "Outlines a realistic 4-week refactoring roadmap with clear weekly milestones: Week 1 offline reranking benchmark; Week 2 staging integration; Week 3 shadow traffic canary; Week 4 full rollout.", "Shows that the additional $300/month GPU reranker hosting cost yields a net savings of $12,000/month in human agent escalations, demonstrating a 40x ROI."]}], "critical_failures": ["Demands a complete architectural rewrite using pure technical jargon (e.g., ''We need HNSW and ColBERT because they are state-of-the-art'') without connecting changes to business metrics or cost savings.", "Fails to provide empirical benchmark data or POC results justifying the engineering investment.", "Ignores infrastructure costs, implementation timelines, and operational risks in the proposal."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How would you design a RAG system for a large corpus of legal contracts, including storage, retrieval, and serving components?', '{"key_points": [{"id": "KP1", "description": "Design legal document ingestion with structure-aware parsing, numbered clause extraction, and hierarchical chunking.", "required": true, "acceptable_evidence": ["Technical keywords: legal contract RAG, hierarchical chunking, clause extraction, section numbering, OCR, Docling, preamble and schedules.", "Parses legal contracts preserving structural hierarchy: Agreement -> Article -> Section -> Clause (e.g., Section 11.4(b) Indemnification).", "Chunks text by complete self-contained legal clauses rather than arbitrary token boundaries, attaching contract title, governing law, and parties in chunk metadata."]}, {"id": "KP2", "description": "Implement hybrid retrieval combining exact legal term matching (BM25) with semantic clause vector search.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid retrieval, BM25, exact terms of art, semantic clause matching, defined terms index, cross-encoder reranking.", "Combines BM25 for precise legal terms of art (e.g., ''Force Majeure'', ''gross negligence'', ''indemnification cap'') with dense vectors for conceptual query matching (e.g., ''Can the vendor terminate without cause?'').", "Maintains an explicit cross-referenced index of Defined Terms to resolve ambiguous definitions across contract sections."]}, {"id": "KP3", "description": "Integrate standard contract playbooks and redlining guidelines into context assembly for policy compliance auditing.", "required": true, "acceptable_evidence": ["Technical keywords: contract playbook, deviation analysis, fallback clause, redlining, compliance scoring, audit trail.", "Injects corporate playbook rules alongside retrieved contract clauses, directing the LLM to identify deviations from standard preferred terms.", "Generates structured redline recommendations highlighting high-risk liability clauses with exact section citations."]}], "critical_failures": ["Splits legal contracts using fixed 500-token windows that slice legal clauses and sentences in half, distorting contractual liability meaning.", "Relies solely on dense vector search, missing crucial exact legal definitions and defined-term capitalizations.", "Permits open-ended generation without citing exact contract section numbers and clause paragraphs."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'How would you design a RAG-based agent system for an insurance claim workflow, including data retrieval, validation, and decision-making?', '{"key_points": [{"id": "KP1", "description": "Architect a multi-step agent workflow orchestrating document ingestion, policy coverage lookup, and claim evidence matching.", "required": true, "acceptable_evidence": ["Technical keywords: claim verification agent, multi-step orchestration, LangGraph, document traversal, policy coverage, claim evidence.", "Structures the agent workflow across sequential stages: Ingest Claim Form & Bills -> Extract Claim Items -> Query Policy Vector Store -> Cross-Reference Exclusions -> Adjudicate Coverage.", "Traverses multi-page PDF medical records and repair estimates to extract line-item billed amounts and diagnostic codes."]}, {"id": "KP2", "description": "Integrate deterministic business rule engines with RAG policy retrieval for mathematical and regulatory compliance.", "required": true, "acceptable_evidence": ["Technical keywords: deterministic rule engine, deductible calculation, co-pay, policy limits, fraud check, hybrid validation.", "Enforces strict separation between semantic policy interpretation (via LLM) and financial calculation (via deterministic Python/SQL rule engine for deductible subtraction and co-insurance percentages).", "Validates that total payouts never exceed hard policy liability caps regardless of LLM generation."]}, {"id": "KP3", "description": "Implement human-in-the-loop (HITL) review gates for high-dollar claims, fraud anomalies, and coverage rejections.", "required": true, "acceptable_evidence": ["Technical keywords: Human-in-the-Loop (HITL), claims adjuster review, escalation threshold, audit trail, confidence score.", "Automatically routes claims exceeding dollar thresholds (e.g., >$5,000), flagged by fraud detection models, or facing denial to a licensed claims adjuster queue.", "Presents the human adjuster with a synthesized decision summary including direct clickable citations to policy clauses and bill items."]}], "critical_failures": ["Permits an autonomous LLM to calculate financial payouts and approve multi-thousand-dollar claim checks without deterministic calculation validation or human review.", "Denies insurance claims automatically based purely on generative AI answers without human adjuster escalation and audit logging.", "Fails to ground claim verification in the claimant''s specific effective policy document version and rider endorsements."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How would you design a chunking algorithm from scratch, including handling chunk size, overlap, and recursion?', '{"key_points": [{"id": "KP1", "description": "Implement recursive text splitting utilizing an ordered list of semantic separators (`[''\\\\n\\\\n'', ''\\\\n'', ''. '', '' '', '''']`).", "required": true, "acceptable_evidence": ["Technical keywords: recursive text splitting, separator hierarchy, paragraph break, sentence break, boundary preservation.", "Implements recursive splitting logic: attempts splitting at primary paragraph boundaries (`\\\\n\\\\n`); if resulting chunks exceed max size, recursively splits down through sentences (`. `), words (` `), and characters (`''`).", "Preserves structural integrity by keeping semantic paragraphs and sentences intact whenever possible."]}, {"id": "KP2", "description": "Engineer sliding window token overlap with strict tokenizer length constraints.", "required": true, "acceptable_evidence": ["Technical keywords: sliding window, chunk overlap, tiktoken, cl100k_base, token length counting, boundary continuity.", "Measures chunk size using exact model tokenizers (e.g., `tiktoken` for OpenAI, HuggingFace tokenizer for MiniLM) rather than naive character counts.", "Maintains an overlap buffer (e.g., 50-100 tokens) between consecutive chunks to ensure sentences spanning chunk boundaries do not lose context."]}, {"id": "KP3", "description": "Handle algorithmic edge cases: long code blocks, nested tables, lists, and metadata preservation.", "required": true, "acceptable_evidence": ["Technical keywords: code blocks, Markdown tables, list preservation, metadata inheritance, chunk_id, sequence index.", "Prevents breaking Markdown tables or fenced code blocks mid-structure by implementing specialized block-aware separators.", "Attaches original document ID, sequential chunk index, and token offset metadata to each generated chunk dictionary."]}], "critical_failures": ["Measures chunk size using character length (`len(text)`) rather than model token count, causing token limit overflow during embedding generation.", "Slices text arbitrarily at fixed character indices without word or sentence boundary awareness, creating chopped words like ''con- / tractor''.", "Omits chunk overlap entirely, causing multi-chunk queries to fail when key relational facts cross chunk boundaries."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a scalable knowledge base system in AWS for processing and retrieving information from billions of documents?', '{"key_points": [{"id": "KP1", "description": "Architect a distributed asynchronous ingestion pipeline on AWS utilizing S3, SQS, EKS worker pools, and OpenSearch / Milvus.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon S3, Amazon SQS, Amazon EKS, distributed ingestion, Milvus distributed, Amazon OpenSearch Service, sharding.", "Decouples document ingestion via S3 event notifications triggering SQS message queues, consumed by scalable EKS worker pods running distributed Celery/Ray tasks.", "Stores billions of embeddings across a horizontally sharded vector cluster (Milvus or OpenSearch) with distributed query nodes and partitioned storage."]}, {"id": "KP2", "description": "Implement vector quantization and storage tiering to manage multi-terabyte vector memory and infrastructure costs.", "required": true, "acceptable_evidence": ["Technical keywords: Scalar Quantization (SQ8), Product Quantization (PQ), memory mapping (MMap), EBS gp3, S3 storage tiering, cost optimization.", "Applies vector quantization (SQ8 or PQ) to compress 768-dim FP32 vectors by 75%, allowing billions of vectors to reside in RAM/disk cache at a fraction of raw storage cost.", "Implements hot/warm/cold storage tiering: active collections in RAM/NVMe SSD, historical archives in EBS gp3 and S3 Glacier."]}, {"id": "KP3", "description": "Design high-availability distributed retrieval routing, read replicas, and partition pruning for high QPS.", "required": true, "acceptable_evidence": ["Technical keywords: read replicas, query coordinator, partition pruning, horizontal scaling, sub-50ms latency, high QPS.", "Deploys stateless query proxy nodes behind an internal Application Load Balancer routing queries across read-only replica shards.", "Enforces tenant, time-range, or departmental partition pruning to restrict search sweeps to small sub-indexes, sustaining 10,000+ QPS."]}], "critical_failures": ["Proposes storing billions of vectors in a single unshared, unquantized in-memory instance, resulting in hundreds of gigabytes of RAM exhaustion and multi-second query latencies.", "Uses synchronous HTTP ingestion calls for billions of documents without message queues (SQS/Kafka) or backpressure management.", "Ignores vector quantization and tiered storage, causing runaway cloud infrastructure bills exceeding hundreds of thousands of dollars per month."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a semantic search-based networking agent to identify relevant connections for a job seeker?', '{"key_points": [{"id": "KP1", "description": "Extract and embed structured professional profiles across skills, experience, industry domains, and career goals.", "required": true, "acceptable_evidence": ["Technical keywords: profile embedding, resume parsing, skill ontology, two-tower embedding, structured representation, dense semantic matching.", "Parses unstructured resumes and LinkedIn profiles into structured JSON (skills, seniority level, industries, target roles) and generates multi-attribute semantic embeddings.", "Applies domain-tuned embedding models to map complementary skill sets (e.g., pairing a startup founder with a backend systems engineer)."]}, {"id": "KP2", "description": "Implement bilateral mutual fit scoring combining candidate-to-peer and peer-to-candidate compatibility vectors.", "required": true, "acceptable_evidence": ["Technical keywords: bilateral matching, mutual fit scoring, cosine similarity, geometric mean, reciprocal ranking, preference weighting.", "Calculates mutual compatibility using bidirectional scoring: $S_{\\\\text{mutual}} = \\\\sqrt{\\\\text{sim}(u_A, p_B) \\\\cdot \\\\text{sim}(u_B, p_A)}$ where both parties'' preferences and profiles are evaluated.", "Ensures recommendations satisfy both the seeker''s criteria and the target contact''s networking preferences."]}, {"id": "KP3", "description": "Incorporate hard constraint filtering and personalized outreach draft generation within the agent workflow.", "required": true, "acceptable_evidence": ["Technical keywords: hard constraint filter, geographic location, seniority matching, LLM outreach generator, personalized icebreaker, guardrails.", "Applies hard pre-filters (geographic radius, open-to-networking status, non-compete domains) before running vector similarity ranking.", "Synthesizes tailored, contextual outreach introduction messages highlighting shared connections, common university alumni, or mutual technical interests."]}], "critical_failures": ["Performs naive unilateral vector search that matches a junior candidate with an executive without verifying if the connection fits both parties'' mutual interests.", "Relies solely on exact keyword matching for job titles, missing strong semantic matches across equivalent titles (e.g., ''MLOps Engineer'' vs. ''AI Infrastructure Engineer'').", "Allows the agent to send automated unreviewed spam messages without user review or personalization."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a simple in-memory retrieval system using sentence transformers and cosine similarity?', '{"key_points": [{"id": "KP1", "description": "Build an in-memory vector storage class encoding text corpus into a normalized 2D NumPy float32 matrix.", "required": true, "acceptable_evidence": ["Technical keywords: SentenceTransformer, NumPy array, float32, L2 normalization, matrix dot product, in-memory index.", "Encodes raw documents using `SentenceTransformer(''all-MiniLM-L6-v2'')` into a 2D NumPy array of shape `(N, D)`.", "Performs L2 vector normalization (`vec / np.linalg.norm(vec, axis=1, keepdims=True)`) at indexing time so cosine similarity simplifies to a fast matrix dot product."]}, {"id": "KP2", "description": "Implement vectorized top-K similarity search using batch dot products and `np.argpartition`.", "required": true, "acceptable_evidence": ["Technical keywords: np.dot, matrix multiplication, np.argpartition, O(N) selection, argsort, top-K retrieval.", "Computes query-document similarity in a single vectorized operation: `scores = np.dot(doc_embeddings, query_embedding)`.", "Uses `np.argpartition(-scores, k)[:k]` to retrieve top $K$ indices in $O(N)$ linear time without doing a full $O(N \\\\log N)$ array sort."]}, {"id": "KP3", "description": "Analyze memory footprint, scalability boundaries, and when to transition to dedicated vector engines.", "required": true, "acceptable_evidence": ["Technical keywords: memory footprint calculation, N * D * 4 bytes, scalability boundary, transition to FAISS/Milvus, thread safety.", "Calculates exact memory: 100k vectors of 384 dimensions in float32 require $100{,}000 \\\\times 384 \\\\times 4 \\\\approx 153.6\\\\text{ MB}$, easily fitting in RAM with sub-15ms search times.", "Establishes transition threshold: beyond 500k-1M vectors, linear matrix multiplication latency exceeds 50ms and lacks persistence/sharding, requiring FAISS or Milvus."]}], "critical_failures": ["Computes cosine similarity using nested Python `for` loops and `scipy.spatial.distance.cosine` per item instead of vectorized NumPy matrix multiplication.", "Sorts the entire score array using `np.argsort` for small top-K queries instead of optimal $O(N)$ `np.argpartition`.", "Fails to normalize vectors, causing dot products to reflect vector magnitudes rather than angular cosine similarity."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a system that leverages past user interactions to provide personalized recommendations and insights?', '{"key_points": [{"id": "KP1", "description": "Construct dynamic user preference profile embeddings from past interactions, query history, and clicked citations.", "required": true, "acceptable_evidence": ["Technical keywords: user profile vector, interaction history, clicked citations, exponential decay, user representation, dynamic preference.", "Constructs a persistent user preference vector by aggregating embeddings of past queries, clicked documents, and bookmarked snippets.", "Applies exponential time decay (e.g., half-life of 14 days) to prioritize recent user interests while preventing outdated past topics from dominating."]}, {"id": "KP2", "description": "Implement hybrid query blending combining current intent vectors with personalized user profile embeddings.", "required": true, "acceptable_evidence": ["Technical keywords: query vector blending, alpha parameter, convex combination, $v_{query} = \\\\alpha v_q + (1-\\\\alpha) v_u$, personalized reranking.", "Formulates blended query representations: $v_{\\\\text{final}} = \\\\alpha v_{\\\\text{query}} + (1 - \\\\alpha) v_{\\\\text{user}}$, tuning $\\\\alpha$ (e.g., 0.7-0.8) to balance immediate query intent with user profile affinity.", "Uses personal profile attributes (e.g., ''EV technician'' vs. ''novice driver'') to steer ambiguous queries to appropriate technical depths."]}, {"id": "KP3", "description": "Prevent echo chambers, filter bubbles, and privacy leakage across multi-user environments.", "required": true, "acceptable_evidence": ["Technical keywords: filter bubble, exploration vs. exploitation, epsilon-greedy retrieval, privacy isolation, GDPR compliance, tenant scoping.", "Introduces exploration mechanisms (e.g., epsilon-greedy candidate injection) ensuring users can discover new information outside past behavior.", "Enforces strict data isolation ensuring one user''s private interactions never influence another user''s retrieval results or profile embeddings."]}], "critical_failures": ["Overweights user profile vectors to the extent that the system ignores current query intent, returning irrelevant personalized favorites.", "Leaks private user interaction histories and search topics across organizational or multi-tenant user boundaries.", "Fails to incorporate temporal decay, permanently biasing recommendations based on one-off queries made months prior."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a system to show users the exact source (sentence or paragraph) of retrieved information in a document?', '{"key_points": [{"id": "KP1", "description": "Implement granular ingestion indexing capturing document IDs, page numbers, paragraph indices, and character offsets.", "required": true, "acceptable_evidence": ["Technical keywords: source provenance, granular attribution, character offsets, page number, bounding box, chunk metadata.", "Stores precise locator metadata for every indexed chunk: `doc_id`, `page_number`, `paragraph_idx`, `start_char`, `end_char`, and PDF bounding box coordinates.", "Enables the UI to jump directly to the exact page and highlight the referenced passage."]}, {"id": "KP2", "description": "Direct the LLM to output sentence-level inline citation anchors tied to indexed context passages.", "required": true, "acceptable_evidence": ["Technical keywords: inline citations, citation brackets, sentence-level attribution, structured citations, reference mapping.", "Prompts the LLM with formatting rules: every asserted claim must terminate with an explicit bracketed citation tag corresponding to retrieved chunk IDs (e.g., `[Doc-12, p.4]`).", "Validates generated citation tags against the actual retrieved context list, stripping ungrounded or non-existent citation references."]}, {"id": "KP3", "description": "Verify attribution faithfulness using cross-encoder NLI and render interactive UI highlights.", "required": true, "acceptable_evidence": ["Technical keywords: attribution verification, NLI entailment check, interactive highlighting, PDF viewer, clickable citations.", "Verifies that each cited sentence is logically entailed by the corresponding source text using an NLI verification pass before displaying to users.", "Provides interactive UI pills: clicking a citation pill opens a side-by-side document viewer highlighting the exact source passage in yellow."]}], "critical_failures": ["Displays vague document-level links (e.g., ''Source: User Manual.pdf'') forcing users to manually read through a 200-page document to find proof.", "Permits the LLM to hallucinate fake citation numbers that point to chunks that do not exist or do not support the assertion.", "Omits character offset and page metadata at ingestion time, making it impossible to perform automated passage highlighting in the client UI."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How would you design the RAG pipeline for textual knowledge in a multimodal system?', '{"key_points": [{"id": "KP1", "description": "Implement multimodal document layout parsing extracting text, structured tables, and visual technical schematics.", "required": true, "acceptable_evidence": ["Technical keywords: multimodal RAG, layout-aware parsing, Docling, Unstructured, table structure extraction, schematic cropping.", "Parses rich engineering manuals and PDFs using vision-based layout analysis models to identify and separate paragraphs, Markdown tables, and graphical wiring schematics.", "Crops schematic diagrams and figures as high-resolution images linked to surrounding text captions."]}, {"id": "KP2", "description": "Generate dual representations for complex visual elements: vision-language summarization and joint image-text embeddings.", "required": true, "acceptable_evidence": ["Technical keywords: vision-language model (VLM), GPT-4o-mini, Claude 3.5 Sonnet, CLIP, ColPali, table-to-markdown, image description.", "Passes extracted diagrams and schematics through a vision model to generate dense technical descriptions (components, pinouts, voltage levels) indexed in the text search engine.", "Optionally utilizes joint multimodal embeddings (CLIP or ColPali) to retrieve diagram images directly from natural language queries."]}, {"id": "KP3", "description": "Construct multimodal context prompts interleaving retrieved text chunks and diagram image payloads for synthesis.", "required": true, "acceptable_evidence": ["Technical keywords: multimodal context assembly, interleaved text and images, base64 payload, vision reasoning, circuit troubleshooting.", "Assembles context payloads feeding both retrieved text explanations and cropped schematic images (via base64 or pre-signed S3 URLs) to the multimodal LLM.", "Enables the model to reason across text specifications and visual wiring diagrams simultaneously during diagnostic troubleshooting."]}], "critical_failures": ["Discards all images, diagrams, and tables during ingestion via naive `pdfminer` text scraping, losing 80% of technical manual diagnostics.", "Embeds raw OCR text of tables without structure preservation, destroying column-row relationships and corrupting specifications.", "Sends unparsed, massive multi-page raw PDF image files to expensive vision APIs for every query, blowing up token budgets and latency."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'MEDIUM', 'SPECIFIC', 90, 'How would you diagnose and resolve increasing lag in a Kafka ingestion pipeline as data volume grows significantly over time?', '{"key_points": [{"id": "KP1", "description": "Diagnose consumer lag bottlenecks across Kafka brokers, network I/O, partition counts, and slow consumer workers.", "required": true, "acceptable_evidence": ["Technical keywords: Kafka consumer lag, Burrow, Prometheus kafka-exporter, partition-to-consumer ratio, commit offset, high lag alert.", "Monitors lag metrics: `records-lag-max` and `consumer_lag` per partition using Prometheus and Grafana dashboards.", "Diagnoses whether lag stems from broker-level under-replication, consumer processing stalls (e.g., slow OCR or GPU embedding generation), or insufficient partition concurrency."]}, {"id": "KP2", "description": "Tune consumer concurrency, partition scaling, and batch configuration (`max.poll.interval.ms`, `max.poll.records`).", "required": true, "acceptable_evidence": ["Technical keywords: max.poll.interval.ms, max.poll.records, session.timeout.ms, partition rebalance storms, consumer group scaling.", "Prevents frequent rebalance storms by tuning `max.poll.interval.ms` higher than the worst-case batch processing time or lowering `max.poll.records` (e.g., from 500 to 50).", "Increases Kafka topic partition count and scales consumer group worker pods up to matching partition limits to achieve linear parallel consumption."]}, {"id": "KP3", "description": "Implement decoupled asynchronous processing pools, batch vector upserts, and backpressure rate limiting.", "required": true, "acceptable_evidence": ["Technical keywords: decoupled worker pool, ThreadPoolExecutor, batch upsert, backpressure, rate limiting, graceful degradation.", "Decouples the Kafka consumer poll loop from downstream heavy processing using internal bounded queues and worker thread pools, committing offsets only upon batch completion.", "Batches embedding requests and vector database upserts (e.g., 256 chunks per batch) to achieve 10x throughput efficiency over single-item inserts."]}], "critical_failures": ["Performs slow synchronous GPU embedding inference directly inside the `poll()` loop, exceeding `max.poll.interval.ms` and triggering endless consumer rebalance storms.", "Attempts to add more consumer instances than partitions in a Kafka topic, failing to realize idle consumers cannot consume from zero partitions.", "Commits offsets prematurely before downstream processing finishes, causing massive silent data loss if consumer worker pods crash."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How would you enforce only current active policy at retrieval time and in generation, including what happens when a newer version is partially ingested?', '{"key_points": [{"id": "KP1", "description": "Model temporal validity in chunk metadata schemas with strict effective and expiration timestamps.", "required": true, "acceptable_evidence": ["Technical keywords: temporal validity, effective_date, expiration_date, ISO 8601, policy versioning, chunk metadata schema.", "Attaches explicit date attributes to all policy chunks: `effective_from` and `effective_to` as epoch or ISO 8601 timestamps in scalar metadata.", "Enables deterministic temporal filtering to ensure queries evaluate only rules legally active at the reference event date."]}, {"id": "KP2", "description": "Enforce query-time temporal filtering to restrict retrieval scope to policies active at the target event date.", "required": true, "acceptable_evidence": ["Technical keywords: query-time filtering, temporal pre-filter, reference date extraction, metadata boolean expression.", "Extracts the event date from the user query (or defaults to current server timestamp) and applies a strict pre-filter expression: `effective_from <= query_date AND effective_to > query_date`.", "Completely excludes deprecated or future unpublished policy clauses from the vector search candidate pool."]}, {"id": "KP3", "description": "Execute zero-downtime blue/green collection swaps and atomic vector index versioning upon policy republishing.", "required": true, "acceptable_evidence": ["Technical keywords: blue/green collection swap, collection aliasing, atomic pointer switch, zero-downtime, Milvus alias, cache eviction.", "Indexes newly published policy editions into an isolated staging collection, runs automated validation checks, and atomically switches the production collection alias to the new version with zero downtime.", "Invalidates related semantic caches and prompt caches immediately upon alias update to eliminate stale cached answers."]}], "critical_failures": ["Retrieves from an unpartitioned vector store containing both active and superseded policies, allowing the LLM to cite outdated or expired guidelines.", "Overwrites production vector collections in place with long-running batch jobs, corrupting search results and causing production outages during indexing.", "Fails to purge cached queries upon policy updates, continuing to serve stale expired policy answers to enterprise users."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How would you engineer a minimax scoring pipeline that combines candidate retrieval, hard constraints, hypothesis scoring, and final match selection?', '{"key_points": [{"id": "KP1", "description": "Architect a multi-stage candidate scoring pipeline: candidate retrieval, hard boolean constraints, and hypothesis scoring.", "required": true, "acceptable_evidence": ["Technical keywords: multi-stage funnel, candidate retrieval, hard constraints, hypothesis scoring, confidence intervals, minimax selection.", "Filters candidates through a cascading funnel: Stage 1 broad two-tower vector retrieval (top 1000) -> Stage 2 hard business constraints (budget, location, licensing) -> Stage 3 multi-attribute scoring model -> Stage 4 confidence interval estimation.", "Eliminates ineligible candidates before applying compute-heavy scoring models."]}, {"id": "KP2", "description": "Formulate a minimax optimization objective balancing worst-case candidate fit and multi-attribute utility.", "required": true, "acceptable_evidence": ["Technical keywords: minimax objective, worst-case bound, risk minimization, multi-attribute utility, conservative matching.", "Applies minimax criteria: selects candidates that maximize the minimum performance score across critical dimensions (e.g., ensuring a candidate satisfies at least 80% on every mandatory skill rather than 100% on one and 0% on another).", "Prevents high scores in non-essential attributes from compensating for catastrophic deficits in core requirements."]}, {"id": "KP3", "description": "Calculate statistical confidence intervals on candidate scores to distinguish true separation from ranking noise.", "required": true, "acceptable_evidence": ["Technical keywords: confidence intervals, score variance, bootstrapping, ranking stability, tie-breaking logic.", "Computes score confidence bands (e.g., 95% confidence interval via bootstrap sampling) reflecting score uncertainty from sparse candidate interaction data.", "Treats overlapping confidence intervals as statistical ties, routing candidates to human review or secondary tie-breaker criteria."]}], "critical_failures": ["Ranks candidates using naive unweighted vector cosine similarity without enforcing hard non-negotiable eligibility constraints.", "Allows a high score in an irrelevant peripheral attribute to mask a complete failure in a mandatory core requirement.", "Presents point estimates as absolute certainties without accounting for score variance or statistical confidence intervals."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'Let''s say you have a RAG system and it is providing you irrelevant answers. How would you go about it? What will you check? How would you do the RCA on it?', '{"key_points": [{"id": "KP1", "description": "Deconstruct the RAG pipeline error surface into distinct failure stages: query parsing, retrieval, reranking, and generation.", "required": true, "acceptable_evidence": ["Technical keywords: Root Cause Analysis (RCA), failure triage, error decomposition, retrieval failure vs. generation failure, observability trace.", "Follows a structured RCA decision tree: inspect user query and rewrite -> inspect retrieved chunks and similarity scores -> inspect reranker rankings -> inspect LLM prompt and generated answer.", "Determines precisely whether the correct document was omitted by the retriever (retrieval bug) or present in context but ignored/distorted by the LLM (synthesis bug)."]}, {"id": "KP2", "description": "Investigate retrieval stage root causes: chunking boundaries, vocabulary mismatch, embedding model drift, and index corruption.", "required": true, "acceptable_evidence": ["Technical keywords: chunking fragmentation, out-of-vocabulary, vector distance, metadata filter mismatch, index staleness, cosine cutoff.", "Checks if the target answer was sliced across chunk boundaries, if technical acronyms suffered out-of-vocabulary semantic drift, or if overly restrictive metadata filters accidentally excluded relevant documents.", "Verifies whether vector index embeddings are synchronized with the latest version of source documentation."]}, {"id": "KP3", "description": "Investigate generation stage root causes: lost-in-the-middle context placement, conflicting prompt instructions, and context overflow.", "required": true, "acceptable_evidence": ["Technical keywords: lost-in-the-middle, context stuffing, prompt interference, temperature setting, context window limit, citation verification.", "Examines whether relevant chunks were buried in the middle of a crowded context window (lost-in-the-middle phenomenon) where LLM attention degrades.", "Tests whether conflicting system prompt directives, high generation temperatures, or misleading distractor chunks caused model hallucination."]}], "critical_failures": ["Immediately blames the LLM generator or tweaks system prompts without first inspecting the retrieved chunks in the Langfuse/trace logs.", "Treats the RAG pipeline as an indivisible black box rather than systematically decoupling retrieval recall from generation faithfulness.", "Lacks execution tracing or logging of retrieved chunk IDs, making post-incident forensic investigation impossible."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'Looking back, what would you have done differently in designing your RAG-based system, particularly around guardrails, cost optimization, and caching strategies?', '{"key_points": [{"id": "KP1", "description": "Reflect candidly on early architecture mistakes: fixed-size chunking, dense-only retrieval, and lack of evaluation-driven development.", "required": true, "acceptable_evidence": ["Technical keywords: retrospective, lessons learned, naive RAG mistakes, fixed chunking pitfalls, hybrid search necessity, evaluation-driven development (EDD).", "Acknowledges initial naive architectural choices: relying purely on fixed 500-character chunking broke diagnostic tables, and dense-only vector search failed catastrophically on exact error codes and part numbers.", "Reflects on the mistake of delaying evaluation harness development, which made early prompt engineering subjective and prone to regressions."]}, {"id": "KP2", "description": "Detail high-impact architectural pivots that unlocked production reliability: hybrid BM25 search, rerankers, and programmatic guardrails.", "required": true, "acceptable_evidence": ["Technical keywords: architectural pivot, cross-encoder reranking, BM25 + dense hybrid search, NeMo Guardrails, structured evaluation, NDCG@10 lift.", "Explains key successful refactorings: introducing BM25 hybrid search and BGE cross-encoder rerankers boosted retrieval recall by over 35%.", "Highlights how deploying programmatic guardrails (Pydantic validation, NLI faithfulness checkers) eliminated customer-facing hallucinations."]}, {"id": "KP3", "description": "Articulate strategic production principles: build evaluation suites first, prioritize data curation over model size, and engineer for latency.", "required": true, "acceptable_evidence": ["Technical keywords: engineering principles, data quality over model parameters, evaluation-first mindset, latency budget, continuous improvement.", "Summarizes core engineering takeaways: ''Clean parsed data and layout-aware chunking matter 5x more than swapping foundation models.''", "Emphasizes establishing automated evaluation benchmarks in CI/CD before writing production code, and designing for streaming low-latency from day one."]}], "critical_failures": ["Claims everything worked flawlessly on day one without any architectural trade-offs, mistakes, or iterative refactorings.", "Attributes all RAG improvements solely to switching to a newer, larger proprietary foundation model rather than architectural and retrieval engineering.", "Fails to articulate clear engineering takeaways or principles derived from real-world production experience."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What SLIs and observability signals would you set for this RAG system? And how would you detect and respond to a policy incorrect answer incident?', '{"key_points": [{"id": "KP1", "description": "Establish core Service Level Indicators (SLIs) and Service Level Objectives (SLOs) spanning quality, latency, and cost.", "required": true, "acceptable_evidence": ["Technical keywords: Service Level Indicators (SLIs), Service Level Objectives (SLOs), faithfulness SLI (>95%), p95 latency (<1.5s), error budget, cost per query.", "Defines technical SLIs: Answer Faithfulness (>= 95% of sampled responses entailed by context), Answer Relevance (>= 90%), p95 End-to-End Latency (< 1.5 seconds), and Retrieval Empty Rate (< 2%).", "Monitors token consumption and cost per query to prevent infrastructure budget overruns."]}, {"id": "KP2", "description": "Implement automated drift detection alarms for retrieval quality degradation, policy changes, and embedding distribution shifts.", "required": true, "acceptable_evidence": ["Technical keywords: drift detection, CloudWatch alarms, Prometheus alertmanager, retrieval score distribution shift, PagerDuty, query volume anomaly.", "Configures automated alerts on sudden drops in mean vector similarity, spikes in fallback refusal rates, or increased cross-encoder rejection ratios.", "Detects semantic distribution shifts when users begin asking about newly released vehicle models or updated regulatory policies before knowledge ingestion occurs."]}, {"id": "KP3", "description": "Formulate rapid incident response runbooks for policy drift, vector index corruption, and upstream LLM degradation.", "required": true, "acceptable_evidence": ["Technical keywords: incident runbook, blue/green rollback, emergency cache purge, secondary provider failover, post-mortem.", "Documents standard operational procedures: trigger automated rollback to the previous blue/green vector collection alias upon detecting corrupted ingestion.", "Enforces secondary LLM provider failover (e.g., Bedrock Claude -> Azure OpenAI) if upstream latency exceeds 3,000ms or error rates exceed 5%."]}], "critical_failures": ["Monitors only standard HTTP 200 vs 500 error codes, completely oblivious to semantic failures where the system successfully returns 200 OK containing hallucinations.", "Lacks automated alerting for retrieval degradation or sudden spikes in user question refusal rates.", "Has no incident remediation runbooks or blue/green rollback mechanisms for corrupted knowledge base deployments."]}', 1);
